# V310 first-party dependency bootstrap.  The release ZIP bundles these files;
# automatic GitHub recovery exists for single-file/partial third-party installs.
CLAIRECJS_UTILS_GITHUB_RAW_ROOT = (
    "https://raw.githubusercontent.com/ClaireCJS/clairecjs_bat/main/"
    "BAT-and-UTIL-files-1/clairecjs_utils"
)
CLAIRECJS_DEPENDENCIES: dict[str, dict[str, object]] = {
    "claire_audio_processing": {
        "filename": "claire_audio_processing.py",
        "minimum_api": 2,
        "release_sha256": "53e639eb84b71aac97bd2d7f066b114f49b3e286b4cda2e404fb747b99f7fff0",
    },
}
_CLAIRECJS_IMPORTED_MODULES: dict[str, object] = {}


def clairecjs_dependency_search_dirs() -> tuple[Path, ...]:
    """Return supported same-folder/subfolder/system Claire utility locations."""
    script_dir = Path(__file__).resolve().parent
    candidates = [
        script_dir,
        script_dir / "clairecjs_utils",
        script_dir / "clairecjs_util",  # compatibility spelling used by older tools
        Path.cwd(),
        Path.cwd() / "clairecjs_utils",
        Path.cwd() / "clairecjs_util",
    ]
    if os.name == "nt":
        candidates.extend([
            Path(r"C:\BAT\clairecjs_utils"),
            Path(r"C:\BAT\clairecjs_util"),
            Path(r"C:\clairecjs_utils"),
        ])
    seen: set[str] = set()
    unique: list[Path] = []
    for candidate in candidates:
        key = str(candidate).casefold()
        if key not in seen:
            seen.add(key)
            unique.append(candidate)
    return tuple(unique)


def _load_clairecjs_module_from_path(module_name: str, path: Path):
    spec = importlib.util.spec_from_file_location(module_name, path)
    if spec is None or spec.loader is None:
        raise ImportError(f"Could not create import spec for {path}")
    module = importlib.util.module_from_spec(spec)
    previous = sys.modules.get(module_name)
    sys.modules[module_name] = module
    try:
        spec.loader.exec_module(module)
    except Exception:
        if previous is None:
            sys.modules.pop(module_name, None)
        else:
            sys.modules[module_name] = previous
        raise
    return module


def _clairecjs_dependency_api_ok(module_name: str, module: object) -> bool:
    requirement = CLAIRECJS_DEPENDENCIES[module_name]
    minimum = int(requirement.get("minimum_api", 0) or 0)
    if module_name == "claire_audio_processing":
        # The helper's published contract uses *_VERSION (for example V120),
        # while an early PAFPlayer bootstrap incorrectly looked only for the
        # nonexistent *_API_VERSION alias. Accept both spellings and parse the
        # leading V so installed V120 helpers are not misreported as version 0.
        raw_version = getattr(module, "CLAIRE_AUDIO_PROCESSING_API_VERSION", None)
        if raw_version is None:
            raw_version = getattr(module, "CLAIRE_AUDIO_PROCESSING_VERSION", 0)
        match = re.search(r"\d+", str(raw_version or ""))
        found = int(match.group(0)) if match else 0
        return found >= minimum
    return True


def find_clairecjs_dependency(module_name: str):
    """Find and validate one first-party helper without importing package __init__."""
    if module_name in _CLAIRECJS_IMPORTED_MODULES:
        return _CLAIRECJS_IMPORTED_MODULES[module_name]
    requirement = CLAIRECJS_DEPENDENCIES[module_name]
    filename = str(requirement["filename"])
    for directory in clairecjs_dependency_search_dirs():
        candidate = directory / filename
        if not candidate.is_file():
            continue
        try:
            module = _load_clairecjs_module_from_path(module_name, candidate)
            if _clairecjs_dependency_api_ok(module_name, module):
                _CLAIRECJS_IMPORTED_MODULES[module_name] = module
                return module
        except Exception:
            continue
    return None


def _prompt_clairecjs_download_location(filename: str) -> Path | None:
    """Ask whether a missing helper should live beside PAFPlayer or in a subfolder."""
    if not getattr(sys.stdin, "isatty", lambda: False)():
        return None
    script_dir = Path(__file__).resolve().parent
    print(
        f"\n🧩 Required ClaireCJS helper is missing/outdated: {filename}\n"
        "PAFPlayer can download the official copy from ClaireCJS's GitHub."
    )
    while True:
        try:
            choice = input(
                "Download to [U] clairecjs_utils\\ subfolder (recommended), "
                "[S] same folder as PAFPlayer, or [N] don't download? [U] "
            ).strip().casefold()
        except (EOFError, KeyboardInterrupt):
            return None
        if choice in {"", "u", "utils", "subfolder", "1"}:
            return script_dir / "clairecjs_utils"
        if choice in {"s", "same", "2"}:
            return script_dir
        if choice in {"n", "no", "3", "q", "quit"}:
            return None


def ensure_clairecjs_dependency(module_name: str, *, interactive: bool = True):
    """Locate or optionally recover one ClaireCJS helper from the official GitHub."""
    module = find_clairecjs_dependency(module_name)
    if module is not None:
        return module
    requirement = CLAIRECJS_DEPENDENCIES[module_name]
    filename = str(requirement["filename"])
    if not interactive:
        return None
    destination_dir = _prompt_clairecjs_download_location(filename)
    if destination_dir is None:
        return None
    destination_dir.mkdir(parents=True, exist_ok=True)
    destination = destination_dir / filename
    url = f"{CLAIRECJS_UTILS_GITHUB_RAW_ROOT}/{filename}"
    temporary = destination.with_name(destination.name + ".download")
    try:
        from urllib.request import Request, urlopen
        request = Request(url, headers={"User-Agent": "PAFPlayer-v319-dependency-bootstrap"})
        print(f"⬇ Downloading {filename} from ClaireCJS GitHub…")
        with urlopen(request, timeout=30) as response:
            payload = response.read(2 * 1024 * 1024 + 1)
        if not payload or len(payload) > 2 * 1024 * 1024:
            raise RuntimeError("download was empty or exceeded the 2 MiB helper limit")
        text = payload.decode("utf-8")
        compile(text, str(destination), "exec")
        actual_sha = hashlib.sha256(payload).hexdigest()
        expected_sha = str(requirement.get("release_sha256", "") or "")
        if expected_sha and actual_sha != expected_sha:
            print(
                "⚠ GitHub helper differs from the copy bundled with this PAFPlayer release; "
                "API compatibility will be verified before use."
            )
        temporary.write_bytes(payload)
        downloaded = _load_clairecjs_module_from_path(module_name, temporary)
        if not _clairecjs_dependency_api_ok(module_name, downloaded):
            raise RuntimeError("downloaded helper API is too old for this PAFPlayer release")
        os.replace(temporary, destination)
        module = _load_clairecjs_module_from_path(module_name, destination)
        if not _clairecjs_dependency_api_ok(module_name, module):
            raise RuntimeError("installed helper failed API verification")
        _CLAIRECJS_IMPORTED_MODULES[module_name] = module
        print(f"✓ Installed {filename} → {destination}")
        return module
    except Exception as exc:
        with contextlib.suppress(OSError):
            temporary.unlink()
        print(
            f"⚠ Could not install {filename}: {exc}\n"
            f"  You can manually place it beside play_audio_file.py or in "
            f"clairecjs_utils\\. Source: {url}",
            file=sys.stderr,
        )
        return None


_TK_SECONDARY_THREAD_USED = False


def _suppress_late_tcl_asyncdelete_diagnostic() -> None:
    """Silence Tcl's known post-cleanup C-runtime diagnostic at process teardown.

    PAFPlayer destroys every Tk object on its owner thread and waits for that
    thread.  Some Windows Tcl builds nevertheless emit ``Tcl_AsyncDelete`` only
    *after* Python's atexit phase, when no application code remains to fix or log.
    Redirecting descriptor 2 at the very end suppresses only that late runtime
    finalizer noise; normal stderr and PAFPlayer's error log remain active for the
    entire useful lifetime of the process.
    """
    if os.name != "nt" or not _TK_SECONDARY_THREAD_USED:
        return
    try:
        null_fd = os.open(os.devnull, os.O_WRONLY)
        try:
            os.dup2(null_fd, 2)
            with contextlib.suppress(Exception):
                import msvcrt
                ctypes.windll.kernel32.SetStdHandle(
                    -12,  # STD_ERROR_HANDLE
                    msvcrt.get_osfhandle(2),
                )
        finally:
            if null_fd != 2:
                os.close(null_fd)
    except Exception:
        pass


# Registered early so this runs after later application/library atexit handlers.
atexit.register(_suppress_late_tcl_asyncdelete_diagnostic)

# Use one encoding end-to-end.  Windows Terminal and Python both receive
# genuine Unicode; no CP1252 bridge strings are required.
if os.name == "nt":
    try:
        import ctypes
        ctypes.windll.kernel32.SetConsoleOutputCP(65001)
        # Tk must receive per-monitor DPI changes for a popup moved between a
        # 1080p display and a scaled 4K display.  Prefer the Windows 10 v2
        # context and retain the older Windows 8.1 fallback.
        try:
            ctypes.windll.user32.SetProcessDpiAwarenessContext(ctypes.c_void_p(-4))
        except (AttributeError, OSError):
            with contextlib.suppress(AttributeError, OSError):
                ctypes.windll.shcore.SetProcessDpiAwareness(2)
    except (AttributeError, OSError):
        pass
try:
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
except (AttributeError, ValueError):
    pass

# V300: prefer Claire's newer Segoe UI Emoji font without requiring it to
# replace Windows' protected system copy.  The utility font wins; a portable
# copy beside play_audio_file.py is the secondary choice.  Pillow and the web
# UI use this path explicitly.  On Windows it is also registered FR_PRIVATE so
# Tk/GDI requests for "Segoe UI Emoji" see the process-private font first.
PREFERRED_EMOJI_FONT_UTILITY_PATH = Path(r"C:\util\fonts\seguiemj.ttf")
_PREFERRED_PRIVATE_EMOJI_FONT_PATH: Path | None = None


def preferred_custom_emoji_font_path() -> Path | None:
    candidates = (
        PREFERRED_EMOJI_FONT_UTILITY_PATH,
        Path(__file__).resolve().parent / "seguiemj.ttf",
    )
    for candidate in candidates:
        with contextlib.suppress(Exception):
            if candidate.is_file():
                return candidate
    return None


def _install_preferred_private_emoji_font() -> Path | None:
    if os.name != "nt":
        return None
    candidate = preferred_custom_emoji_font_path()
    if candidate is None:
        return None
    try:
        # FR_PRIVATE: visible only to PAFPlayer.  Windows' font mapper gives a
        # process-private face priority over a public face with the same name.
        added = int(ctypes.windll.gdi32.AddFontResourceExW(str(candidate), 0x10, 0))
        return candidate if added > 0 else None
    except Exception:
        return None


def _remove_preferred_private_emoji_font() -> None:
    candidate = _PREFERRED_PRIVATE_EMOJI_FONT_PATH
    if os.name != "nt" or candidate is None:
        return
    with contextlib.suppress(Exception):
        ctypes.windll.gdi32.RemoveFontResourceExW(str(candidate), 0x10, 0)


_PREFERRED_PRIVATE_EMOJI_FONT_PATH = _install_preferred_private_emoji_font()
atexit.register(_remove_preferred_private_emoji_font)

try:
    _wcwidth = importlib.import_module("wcwidth")
    wcswidth = _wcwidth.wcswidth
except ImportError:
    def wcswidth(text: str) -> int:
        """Small dependency-free terminal-width fallback."""
        width = 0
        joined = False
        for index, character in enumerate(text):
            codepoint = ord(character)
            category = unicodedata.category(character)
            if category.startswith("C") and character not in {"\u200d"}:
                return -1
            if unicodedata.combining(character) or codepoint in {0x200D, 0xFE0E, 0xFE0F}:
                if codepoint == 0x200D:
                    joined = True
                continue
            if joined:
                joined = False
                continue
            next_is_emoji_selector = index + 1 < len(text) and ord(text[index + 1]) == 0xFE0F
            if 0x1F1E6 <= codepoint <= 0x1F1FF:
                width += 1
            elif (
                unicodedata.east_asian_width(character) in {"W", "F"}
                or 0x1F000 <= codepoint <= 0x1FAFF
                or next_is_emoji_selector
            ):
                width += 2
            else:
                width += 1
        return width

_CLAIRE_UTILS_DIR = r"C:\clairecjs_utils"
if _CLAIRE_UTILS_DIR not in sys.path:
    sys.path.insert(0, _CLAIRE_UTILS_DIR)

# Claire helper bootstrap ---------------------------------------------------
# The player works best with these shared Clairevironment helpers.  They may
# live in C:\clairecjs_utils, in site-packages/site-lib as clairecjs_utils.*, or
# flat beside this script.  On Windows, if a helper is entirely missing, the
# player makes one best-effort attempt to download the current GitHub copy next
# to itself.  That makes a standalone play_audio_file.py much easier to carry to
# another machine without turning a cosmetic/helper dependency into a blocker.
AUTO_DOWNLOAD_CLAIRE_LIBRARIES = 1
_CLAIRE_HELPER_RAW_BASE = (
    "https://raw.githubusercontent.com/ClaireCJS/clairecjs_bat/main/"
    "BAT-and-UTIL-files-1/clairecjs_utils"
)
_CLAIRE_HELPERS = (
    "claire_progressbar",
    "claire_terminal_geometry",
    "claire_lastfm",
    "claire_console",
)


def _claire_helper_available(module_name: str) -> bool:
    for qualified in (module_name, f"clairecjs_utils.{module_name}"):
        try:
            if importlib.util.find_spec(qualified) is not None:
                return True
        except (ImportError, ModuleNotFoundError, AttributeError, ValueError):
            pass
    return False


def _bootstrap_download_progress(name: str, downloaded: int, total: int | None) -> None:
    """Tiny dependency-free download bar used before claire_progressbar exists."""
    if total and total > 0:
        fraction = min(1.0, downloaded / total)
        width = 28
        filled = round(width * fraction)
        bar = "█" * filled + "░" * (width - filled)
        suffix = f" {fraction * 100:5.1f}%"
    else:
        width = 28
        pulse = (downloaded // 65536) % width
        bar = "░" * pulse + "█" + "░" * max(0, width - pulse - 1)
        suffix = f" {downloaded / 1024:,.0f} KiB"
    sys.stderr.write(f"\r⬇ {name:<30} [{bar}]{suffix}")
    sys.stderr.flush()


def _download_missing_claire_helper(module_name: str) -> bool:
    """Download one missing Claire helper beside this script, atomically."""
    try:
        import urllib.request
        target_dir = Path(__file__).resolve().parent
        target = target_dir / f"{module_name}.py"
        url = f"{_CLAIRE_HELPER_RAW_BASE}/{module_name}.py"
        request = urllib.request.Request(url, headers={"User-Agent": "play_audio_file/24"})
        with urllib.request.urlopen(request, timeout=20) as response:
            total_header = response.headers.get("Content-Length")
            total = int(total_header) if total_header and total_header.isdigit() else None
            temporary = target.with_suffix(target.suffix + ".download")
            downloaded = 0
            with temporary.open("wb") as output:
                while True:
                    chunk = response.read(65536)
                    if not chunk:
                        break
                    output.write(chunk)
                    downloaded += len(chunk)
                    _bootstrap_download_progress(module_name + ".py", downloaded, total)
            os.replace(temporary, target)
        sys.stderr.write("\r" + " " * 88 + "\r")
        sys.stderr.write(f"✅ Installed Claire helper: {target}\n")
        sys.stderr.flush()
        importlib.invalidate_caches()
        return True
    except Exception as exc:  # pragma: no cover - network/machine dependent
        sys.stderr.write("\r" + " " * 88 + "\r")
        sys.stderr.write(f"⚠ Could not auto-download {module_name}.py: {exc}\n")
        sys.stderr.flush()
        return False


def _bootstrap_claire_helpers() -> None:
    # Avoid turning unit tests into network tests.  Normal Windows playback is
    # where the self-healing bootstrap is useful.
    if os.name != "nt" or not AUTO_DOWNLOAD_CLAIRE_LIBRARIES:
        return
    if any(argument in {"--unit-tests", "-t"} for argument in sys.argv[1:]):
        return
    for helper in _CLAIRE_HELPERS:
        if not _claire_helper_available(helper):
            _download_missing_claire_helper(helper)


def _import_claire_helper(module_name: str):
    """Import a Claire helper from package/site-lib or flat local layout."""
    errors: list[BaseException] = []
    for qualified in (f"clairecjs_utils.{module_name}", module_name):
        try:
            return importlib.import_module(qualified)
        except (ImportError, ModuleNotFoundError) as exc:
            errors.append(exc)
    if os.name == "nt" and AUTO_DOWNLOAD_CLAIRE_LIBRARIES:
        if _download_missing_claire_helper(module_name):
            return importlib.import_module(module_name)
    raise ImportError(f"Claire helper {module_name!r} is unavailable") from (errors[-1] if errors else None)


_bootstrap_claire_helpers()

# claire_progressbar is cosmetic.  Prefer the package form, then a flat copy;
# if both fail, retain the player's no-op fallback so playback still works.
try:
    progress_bar = _import_claire_helper("claire_progressbar").progress_bar  # type: ignore[attr-defined]
except ImportError:  # pragma: no cover
    class _DummyProgressBar:
        def __init__(self, *_, **__):
            pass

        def update(self, *_, **__):
            pass

        def __enter__(self):
            return self

        def __exit__(self, *_, **__):
            return False

    def progress_bar(*_, **__):  # type: ignore
        return _DummyProgressBar()


