def set_karaoke_display_offset_tenths(tenths: int) -> float:
    """Set the track-local karaoke display offset on an exact 0.1-second grid."""
    global KARAOKE_DISPLAY_OFFSET_SECONDS
    KARAOKE_DISPLAY_OFFSET_SECONDS = max(-20.0, min(20.0, int(tenths) / 10.0))
    return KARAOKE_DISPLAY_OFFSET_SECONDS

def adjust_karaoke_display_offset_tenths(delta_tenths: int) -> float:
    """Adjust karaoke timing without accumulating binary-float drift."""
    current_tenths = int(round(float(KARAOKE_DISPLAY_OFFSET_SECONDS) * 10.0))
    return set_karaoke_display_offset_tenths(current_tenths + int(delta_tenths))
