def _matrix_factory(output_channels: int):
    mode = int(output_channels)
    if mode == 5:
        return STEREO_TO_51_COPY_MATRIX
    if mode == 7:
        return STEREO_TO_71_COPY_MATRIX
    if mode == 12:
        return STEREO_TO_ATMOS_COPY_MATRIX
    raise ValueError(f"Unsupported matrix output mode: {output_channels}")

def _normalize_mm_mutes(output_channels: int, value) -> set[str]:
    allowed = {row[0] for row in _matrix_factory(output_channels)}
    if isinstance(value, dict):
        incoming = [name for name, muted in value.items() if muted]
    elif isinstance(value, (list, tuple, set)):
        incoming = value
    else:
        incoming = []
    return {str(name).upper() for name in incoming if str(name).upper() in allowed}


def _normalize_upmix_matrix(output_channels: int, rows) -> tuple[tuple[str, float, float], ...]:
    """Normalize an editable MatrixMixer-style 2-input matrix without changing speaker order."""
    factory = _matrix_factory(output_channels)
    incoming = list(rows or [])
    by_name: dict[str, tuple[float, float]] = {}
    for row in incoming:
        try:
            if isinstance(row, dict):
                name = str(row.get("speaker", "")).upper()
                left = float(row.get("left", 0.0))
                right = float(row.get("right", 0.0))
            else:
                name, left, right = row
                name = str(name).upper()
                left, right = float(left), float(right)
        except (TypeError, ValueError):
            continue
        if math.isfinite(left) and math.isfinite(right):
            by_name[name] = (max(-4.0, min(4.0, left)), max(-4.0, min(4.0, right)))
    result=[]
    for speaker, default_left, default_right in factory:
        left, right = by_name.get(speaker, (default_left, default_right))
        result.append((speaker, round(float(left), 4), round(float(right), 4)))
    return tuple(result)


def _matrix_to_jsonable(matrix) -> list[list[object]]:
    return [[speaker, float(left), float(right)] for speaker, left, right in matrix]


def _safe_winreg_set_value(key, value_name, reserved, value_type, value) -> bool:
    """Crash-proof wrapper around winreg.SetValueEx, including rare SystemError failures."""
    if os.name != "nt":
        return False
    try:
        import winreg
        if value_type in {winreg.REG_DWORD, getattr(winreg, "REG_QWORD", -999)}:
            value = int(value)
        elif value_type in {winreg.REG_SZ, getattr(winreg, "REG_EXPAND_SZ", -999)}:
            value = str(value)
        elif value_type == winreg.REG_BINARY:
            value = bytes(value)
        getattr(winreg, "SetValueEx")(key, str(value_name), int(reserved), int(value_type), value)
        return True
    except Exception:
        return False


def _read_registry_json_string(value_name: str, fallback):
    if os.name != "nt":
        return fallback
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            value, _kind = winreg.QueryValueEx(key, value_name)
        return json.loads(str(value))
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        return fallback


def _write_registry_json_string(value_name: str, value) -> None:
    if os.name != "nt":
        return
    try:
        import winreg
        with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            _safe_winreg_set_value(key, value_name, 0, winreg.REG_SZ, json.dumps(value, ensure_ascii=False, separators=(",", ":")))
    except Exception:
        pass


def _normalize_mm_crossover(value) -> dict[str, object]:
    if not isinstance(value, dict):
        value = {}
    enabled = bool(value.get("enabled", True))
    try:
        hz = float(value.get("hz", MM_MATRIX_DEFAULT_CROSSOVER_HZ))
    except (TypeError, ValueError):
        hz = MM_MATRIX_DEFAULT_CROSSOVER_HZ
    if not math.isfinite(hz):
        hz = MM_MATRIX_DEFAULT_CROSSOVER_HZ
    hz = max(MM_MATRIX_MIN_CROSSOVER_HZ, min(MM_MATRIX_MAX_CROSSOVER_HZ, hz))
    return {"enabled": enabled, "hz": round(hz, 1)}


def _factory_matrix_profile_payload() -> dict[str, object]:
    return {
        "5": _matrix_to_jsonable(STEREO_TO_51_COPY_MATRIX),
        "7": _matrix_to_jsonable(STEREO_TO_71_COPY_MATRIX),
        "12": _matrix_to_jsonable(STEREO_TO_ATMOS_COPY_MATRIX),
        "crossover5": {"enabled": True, "hz": MM_MATRIX_DEFAULT_CROSSOVER_HZ},
        "crossover7": {"enabled": True, "hz": MM_MATRIX_DEFAULT_CROSSOVER_HZ},
        "crossover12": {"enabled": True, "hz": MM_MATRIX_DEFAULT_CROSSOVER_HZ},
        "mutes5": [],
        "mutes7": [],
        "mutes12": [],
    }


def load_matrixmixer_configuration() -> None:
    global _MM_MATRIX_LOADED, _ACTIVE_STEREO_TO_51_COPY_MATRIX, _ACTIVE_STEREO_TO_71_COPY_MATRIX
    global _ACTIVE_STEREO_TO_ATMOS_COPY_MATRIX, _MM_MATRIX_PROFILES, _ACTIVE_MM_CROSSOVERS, _ACTIVE_MM_MUTES
    if _MM_MATRIX_LOADED:
        return
    _MM_MATRIX_LOADED = True
    _ACTIVE_STEREO_TO_51_COPY_MATRIX = _normalize_upmix_matrix(5, _read_registry_json_string(MM_MATRIX_ACTIVE_51_REGISTRY_VALUE, []))
    _ACTIVE_STEREO_TO_71_COPY_MATRIX = _normalize_upmix_matrix(7, _read_registry_json_string(MM_MATRIX_ACTIVE_71_REGISTRY_VALUE, []))
    _ACTIVE_STEREO_TO_ATMOS_COPY_MATRIX = _normalize_upmix_matrix(12, _read_registry_json_string(MM_MATRIX_ACTIVE_ATMOS_REGISTRY_VALUE, []))
    _ACTIVE_MM_CROSSOVERS = {
        5: _normalize_mm_crossover(_read_registry_json_string(MM_MATRIX_CROSSOVER_51_REGISTRY_VALUE, {})),
        7: _normalize_mm_crossover(_read_registry_json_string(MM_MATRIX_CROSSOVER_71_REGISTRY_VALUE, {})),
        12: _normalize_mm_crossover(_read_registry_json_string(MM_MATRIX_CROSSOVER_ATMOS_REGISTRY_VALUE, {})),
    }
    _ACTIVE_MM_MUTES = {
        5: _normalize_mm_mutes(5, _read_registry_json_string(MM_MATRIX_MUTES_51_REGISTRY_VALUE, [])),
        7: _normalize_mm_mutes(7, _read_registry_json_string(MM_MATRIX_MUTES_71_REGISTRY_VALUE, [])),
        12: _normalize_mm_mutes(12, _read_registry_json_string(MM_MATRIX_MUTES_ATMOS_REGISTRY_VALUE, [])),
    }
    raw_profiles = _read_registry_json_string(MM_MATRIX_PROFILE_REGISTRY_VALUE, {})
    clean: dict[str, dict[str, object]] = {}
    if isinstance(raw_profiles, dict):
        for raw_name, payload in raw_profiles.items():
            name = str(raw_name).strip()[:80]
            if not name or not isinstance(payload, dict):
                continue
            clean[name] = {
                "5": _matrix_to_jsonable(_normalize_upmix_matrix(5, payload.get("5", []))),
                "7": _matrix_to_jsonable(_normalize_upmix_matrix(7, payload.get("7", []))),
                "12": _matrix_to_jsonable(_normalize_upmix_matrix(12, payload.get("12", []))),
                "crossover5": _normalize_mm_crossover(payload.get("crossover5", {})),
                "crossover7": _normalize_mm_crossover(payload.get("crossover7", {})),
                "crossover12": _normalize_mm_crossover(payload.get("crossover12", {})),
                "mutes5": sorted(_normalize_mm_mutes(5, payload.get("mutes5", []))),
                "mutes7": sorted(_normalize_mm_mutes(7, payload.get("mutes7", []))),
                "mutes12": sorted(_normalize_mm_mutes(12, payload.get("mutes12", []))),
            }
    # The built-in default profile is intentionally the current factory contract,
    # not a stale user-overwritable snapshot from an older release. Named profiles
    # remain untouched, while “default” always remains a safe reset point.
    clean["default"] = _factory_matrix_profile_payload()
    _MM_MATRIX_PROFILES = clean
    _write_registry_json_string(MM_MATRIX_PROFILE_REGISTRY_VALUE, _MM_MATRIX_PROFILES)


def active_stereo_upmix_matrix(output_channels: int):
    load_matrixmixer_configuration()
    mode = int(output_channels)
    if mode == 5:
        return _ACTIVE_STEREO_TO_51_COPY_MATRIX
    if mode == 7:
        return _ACTIVE_STEREO_TO_71_COPY_MATRIX
    if mode == 12:
        return _ACTIVE_STEREO_TO_ATMOS_COPY_MATRIX
    raise ValueError(f"Unsupported matrix output mode: {output_channels}")


def active_matrixmixer_crossover(output_channels: int) -> dict[str, object]:
    load_matrixmixer_configuration()
    return dict(_ACTIVE_MM_CROSSOVERS[int(output_channels)])


def active_matrixmixer_mutes(output_channels: int) -> set[str]:
    load_matrixmixer_configuration()
    return set(_ACTIVE_MM_MUTES[int(output_channels)])


def matrixmixer_configuration_snapshot() -> dict[str, object]:
    load_matrixmixer_configuration()
    return {
        "matrix5": _matrix_to_jsonable(_ACTIVE_STEREO_TO_51_COPY_MATRIX),
        "matrix7": _matrix_to_jsonable(_ACTIVE_STEREO_TO_71_COPY_MATRIX),
        "matrix12": _matrix_to_jsonable(_ACTIVE_STEREO_TO_ATMOS_COPY_MATRIX),
        "factory5": _matrix_to_jsonable(STEREO_TO_51_COPY_MATRIX),
        "factory7": _matrix_to_jsonable(STEREO_TO_71_COPY_MATRIX),
        "factory12": _matrix_to_jsonable(STEREO_TO_ATMOS_COPY_MATRIX),
        "crossover5": _normalize_mm_crossover(_ACTIVE_MM_CROSSOVERS.get(5, {})),
        "crossover7": _normalize_mm_crossover(_ACTIVE_MM_CROSSOVERS.get(7, {})),
        "crossover12": _normalize_mm_crossover(_ACTIVE_MM_CROSSOVERS.get(12, {})),
        "mutes5": sorted(_normalize_mm_mutes(5, _ACTIVE_MM_MUTES.get(5, set()))),
        "mutes7": sorted(_normalize_mm_mutes(7, _ACTIVE_MM_MUTES.get(7, set()))),
        "mutes12": sorted(_normalize_mm_mutes(12, _ACTIVE_MM_MUTES.get(12, set()))),
        "profiles": sorted(_MM_MATRIX_PROFILES, key=lambda name: (name.casefold() != "default", name.casefold())),
    }


def save_active_matrixmixer_matrices(matrix5=None, matrix7=None, matrix12=None, crossover5=None, crossover7=None, crossover12=None, mutes5=None, mutes7=None, mutes12=None) -> dict[str, object]:
    global _ACTIVE_STEREO_TO_51_COPY_MATRIX, _ACTIVE_STEREO_TO_71_COPY_MATRIX, _ACTIVE_STEREO_TO_ATMOS_COPY_MATRIX
    global _ACTIVE_MM_CROSSOVERS, _ACTIVE_MM_MUTES
    load_matrixmixer_configuration()
    matrix_specs = (
        (5, matrix5, MM_MATRIX_ACTIVE_51_REGISTRY_VALUE),
        (7, matrix7, MM_MATRIX_ACTIVE_71_REGISTRY_VALUE),
        (12, matrix12, MM_MATRIX_ACTIVE_ATMOS_REGISTRY_VALUE),
    )
    for mode, rows, reg in matrix_specs:
        if rows is None:
            continue
        normalized = _normalize_upmix_matrix(mode, rows)
        if mode == 5:
            _ACTIVE_STEREO_TO_51_COPY_MATRIX = normalized
        elif mode == 7:
            _ACTIVE_STEREO_TO_71_COPY_MATRIX = normalized
        else:
            _ACTIVE_STEREO_TO_ATMOS_COPY_MATRIX = normalized
        _write_registry_json_string(reg, _matrix_to_jsonable(normalized))
    for mode, value, reg in (
        (5, crossover5, MM_MATRIX_CROSSOVER_51_REGISTRY_VALUE),
        (7, crossover7, MM_MATRIX_CROSSOVER_71_REGISTRY_VALUE),
        (12, crossover12, MM_MATRIX_CROSSOVER_ATMOS_REGISTRY_VALUE),
    ):
        if value is not None:
            _ACTIVE_MM_CROSSOVERS[mode] = _normalize_mm_crossover(value)
            _write_registry_json_string(reg, _ACTIVE_MM_CROSSOVERS[mode])
    for mode, value, reg in (
        (5, mutes5, MM_MATRIX_MUTES_51_REGISTRY_VALUE),
        (7, mutes7, MM_MATRIX_MUTES_71_REGISTRY_VALUE),
        (12, mutes12, MM_MATRIX_MUTES_ATMOS_REGISTRY_VALUE),
    ):
        if value is not None:
            _ACTIVE_MM_MUTES[mode] = _normalize_mm_mutes(mode, value)
            _write_registry_json_string(reg, sorted(_ACTIVE_MM_MUTES[mode]))
    return matrixmixer_configuration_snapshot()


def save_matrixmixer_profile(name: str, matrix5=None, matrix7=None, matrix12=None, crossover5=None, crossover7=None, crossover12=None, mutes5=None, mutes7=None, mutes12=None) -> dict[str, object]:
    load_matrixmixer_configuration()
    clean = re.sub(r"[\r\n\t]+", " ", str(name or "")).strip()[:80]
    if not clean:
        raise ValueError("profile name is required")
    if any(value is not None for value in (matrix5, matrix7, matrix12, crossover5, crossover7, crossover12, mutes5, mutes7, mutes12)):
        save_active_matrixmixer_matrices(matrix5, matrix7, matrix12, crossover5, crossover7, crossover12, mutes5, mutes7, mutes12)
    _MM_MATRIX_PROFILES[clean] = {
        "5": _matrix_to_jsonable(_ACTIVE_STEREO_TO_51_COPY_MATRIX),
        "7": _matrix_to_jsonable(_ACTIVE_STEREO_TO_71_COPY_MATRIX),
        "12": _matrix_to_jsonable(_ACTIVE_STEREO_TO_ATMOS_COPY_MATRIX),
        "crossover5": dict(_ACTIVE_MM_CROSSOVERS[5]),
        "crossover7": dict(_ACTIVE_MM_CROSSOVERS[7]),
        "crossover12": dict(_ACTIVE_MM_CROSSOVERS[12]),
        "mutes5": sorted(_ACTIVE_MM_MUTES[5]),
        "mutes7": sorted(_ACTIVE_MM_MUTES[7]),
        "mutes12": sorted(_ACTIVE_MM_MUTES[12]),
    }
    _write_registry_json_string(MM_MATRIX_PROFILE_REGISTRY_VALUE, _MM_MATRIX_PROFILES)
    return matrixmixer_configuration_snapshot()


def restore_matrixmixer_profile(name: str) -> dict[str, object]:
    load_matrixmixer_configuration()
    payload = _MM_MATRIX_PROFILES.get(str(name))
    if payload is None:
        raise KeyError(name)
    return save_active_matrixmixer_matrices(
        payload.get("5"), payload.get("7"), payload.get("12"),
        payload.get("crossover5"), payload.get("crossover7"), payload.get("crossover12"),
        payload.get("mutes5"), payload.get("mutes7"), payload.get("mutes12"),
    )


def reset_matrixmixer_section_to_factory(output_channels: int) -> dict[str, object]:
    """Reset exactly one speaker-expansion section; leave every other section untouched."""
    mode = int(output_channels)
    crossover = {"enabled": True, "hz": MM_MATRIX_DEFAULT_CROSSOVER_HZ}
    if mode == 5:
        return save_active_matrixmixer_matrices(matrix5=STEREO_TO_51_COPY_MATRIX, crossover5=crossover, mutes5=[])
    if mode == 7:
        return save_active_matrixmixer_matrices(matrix7=STEREO_TO_71_COPY_MATRIX, crossover7=crossover, mutes7=[])
    if mode == 12:
        return save_active_matrixmixer_matrices(matrix12=STEREO_TO_ATMOS_COPY_MATRIX, crossover12=crossover, mutes12=[])
    raise ValueError(f"Unsupported matrix output mode: {output_channels}")


def reset_matrixmixer_to_factory() -> dict[str, object]:
    """Legacy/internal whole-matrix reset; the V300 UI exposes section resets only."""
    return save_active_matrixmixer_matrices(
        STEREO_TO_51_COPY_MATRIX, STEREO_TO_71_COPY_MATRIX, STEREO_TO_ATMOS_COPY_MATRIX,
        {"enabled": True, "hz": MM_MATRIX_DEFAULT_CROSSOVER_HZ},
        {"enabled": True, "hz": MM_MATRIX_DEFAULT_CROSSOVER_HZ},
        {"enabled": True, "hz": MM_MATRIX_DEFAULT_CROSSOVER_HZ},
        [], [], [],
    )

