def _pillow_cursive_shaping_kwargs() -> dict[str, object]:
    """Enable OpenType line shaping only for the V238 experimental cursive fix.

    Pillow exposes kerning/ligature/contextual-alternate features through libraqm.
    Returning an empty dict keeps older Pillow builds and non-RAQM installs on the
    exact legacy path instead of making lyric rendering depend on an optional DLL.
    """
    if not CURSIVE_FIX_RUNTIME:
        return {}
    try:
        from PIL import features  # type: ignore
        if features.check_feature("raqm"):
            return {"features": ["kern", "liga", "calt"], "language": "en"}
    except Exception:
        pass
    return {}

