# V251: web autoslides configure a local runtime oscillator once; the console
# visualizer samples it directly on each already-scheduled paint.  The browser
# no longer sends dozens of strength updates per second, and long cycles remain
# continuously smooth instead of exposing a quantized list of frames.
ART_COLOR_AUTOSLIDE = {
    "bars": {"enabled": False, "minimum": 0.0, "maximum": 1.0, "interval": 4.0, "started": time.monotonic()},
    "blackness": {"enabled": False, "minimum": 0.0, "maximum": 1.0, "interval": 4.0, "started": time.monotonic()},
}
ART_COLOR_AUTOSLIDES_LOCKED = False
ART_COLOR_AUTOSLIDES_SHARED_STARTED = time.monotonic()

def _art_color_autoslide_triangle(now: float, started: float, interval: float) -> float:
    period = max(0.05, float(interval))
    phase = ((float(now) - float(started)) % period) / period
    return phase * 2.0 if phase < 0.5 else 2.0 - phase * 2.0

def art_color_visualizer_effective_strengths(now: float | None = None) -> tuple[float, float]:
    """Return smooth console-local art strengths without mutating saved slider values."""
    current = time.monotonic() if now is None else float(now)
    result: dict[str, float] = {
        "bars": float(ART_COLOR_VISUALIZER_BAR_STRENGTH),
        "blackness": float(ART_COLOR_VISUALIZER_BLACK_STRENGTH),
    }
    shared_interval = max(0.05, float(ART_COLOR_AUTOSLIDE["bars"].get("interval", 4.0)))
    for name in ("bars", "blackness"):
        cfg = ART_COLOR_AUTOSLIDE[name]
        if not bool(cfg.get("enabled", False)):
            continue
        minimum = max(0.0, min(1.0, float(cfg.get("minimum", 0.0))))
        maximum = max(minimum, min(1.0, float(cfg.get("maximum", 1.0))))
        if ART_COLOR_AUTOSLIDES_LOCKED:
            triangle = _art_color_autoslide_triangle(current, ART_COLOR_AUTOSLIDES_SHARED_STARTED, shared_interval)
        else:
            triangle = _art_color_autoslide_triangle(current, float(cfg.get("started", current)), float(cfg.get("interval", 4.0)))
        result[name] = minimum + (maximum - minimum) * triangle
    return result["bars"], result["blackness"]

