@lru_cache(maxsize=1)
def _emojimax_phrase_items() -> tuple[tuple[str, str], ...]:
    """Return non-single-word substitutions longest-first.

    Emojimaxx is a longest-match system: a specific phrase such as ``hot dog``
    must be consumed before its component words ``hot`` and ``dog``.  Candidate
    syncs can add multi-word/punctuated entries to ``semantic`` too, so include
    those automatically instead of requiring a second hand-maintained phrase list.
    Explicit ``SEMANTIC_PHRASES`` entries win on duplicate keys.
    """
    merged: dict[str, str] = {}
    for raw_phrase, replacement in semantic.items():
        phrase = str(raw_phrase)
        # Ordinary one-word keys are handled by the later whole-word pass.
        # Anything with 2+ lexical pieces (spaces, dots, slashes, etc.) belongs
        # in the protected phrase pass.
        if len(re.findall(r"[\w’']+", phrase, flags=re.UNICODE)) >= 2:
            merged[phrase] = str(replacement)
    merged.update({str(key): str(value) for key, value in SEMANTIC_PHRASES.items()})
    return tuple(sorted(
        merged.items(),
        key=lambda item: (
            len(re.findall(r"[\w’']+", item[0], flags=re.UNICODE)),
            len(item[0]),
        ),
        reverse=True,
    ))


EMOJIMAX_MONOCHROME_COLOR_WORDS = frozenset({
    "go", "red", "green", "blue", "yellow", "orange", "purple", "brown", "black", "white",
    "cyan", "magenta", "pink", "gray", "grey", "stoplight", "traffic light",
})
EMOJIMAX_MONOCHROME_COLOR_GLYPHS = frozenset({
    "🔴", "🟠", "🟡", "🟢", "🔵", "🟣", "🟤", "⚫", "⚪",
    "🟥", "🟧", "🟨", "🟩", "🟦", "🟪", "🟫", "⬛", "⬜",
})

def emojimax_monochrome_safe_replacement(key: str, replacement: object) -> bool:
    """Whether an Emojimax replacement keeps its meaning when emoji color is stripped."""
    if replacement is None:
        return False
    if str(key or "").strip().casefold() in EMOJIMAX_MONOCHROME_COLOR_WORDS:
        return False
    rendered = str(replacement)
    return not any(glyph in rendered for glyph in EMOJIMAX_MONOCHROME_COLOR_GLYPHS)


KARAOKE_STYLE_NAMES = (
    "Plain", "Fraktur", "Fraktur Clean", "Fraktur Framed",
    "Circled", "Circled Clean", "Cursive", "Cursive Clean",
    "Cursive Framed", "Uppercase", "Greek", "Greek Clean",
    "Greek Framed", "Leetspeak", "Leetspeak Clean", "Symbol Mix",
    "Unicode Sans", "Enclosed Letters", "Closest Unicode", "Script", "Megamix",
)
KARAOKE_TREATMENT_NAMES = (
    "Readable Solid", "Line Rainbow", "Word Rainbow",
    "Random Letter Color", "Hashed Word Color", "Megamix1", "Megamix2",
)

def _legacy_karaoke_text(text: str, style: int) -> str:
    """Render one of the original fifty styles by its original number."""
    style = (style - 1) % 50
    family, decoration = divmod(style, 5)
    upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    lower = "abcdefghijklmnopqrstuvwxyz"
    targets = (
        upper + lower,
        "ＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ",
        "𝐀𝐁𝐂𝐃𝐄𝐅𝐆𝐇𝐈𝐉𝐊𝐋𝐌𝐍𝐎𝐏𝐐𝐑𝐒𝐓𝐔𝐕𝐖𝐗𝐘𝐙𝐚𝐛𝐜𝐝𝐞𝐟𝐠𝐡𝐢𝐣𝐤𝐥𝐦𝐧𝐨𝐩𝐪𝐫𝐬𝐭𝐮𝐯𝐰𝐱𝐲𝐳",
        "𝔄𝔅ℭ𝔇𝔈𝔉𝔊ℌℑ𝔍𝔎𝔏𝔐𝔑𝔒𝔓𝔔ℜ𝔖𝔗𝔘𝔙𝔚𝔛𝔜ℨ𝔞𝔟𝔠𝔡𝔢𝔣𝔤𝔥𝔦𝔧𝔨𝔩𝔪𝔫𝔬𝔭𝔮𝔯𝔰𝔱𝔲𝔳𝔴𝔵𝔶𝔷",
        "ⒶⒷⒸⒹⒺⒻⒼⒽⒾⒿⓀⓁⓂⓃⓄⓅⓆⓇⓈⓉⓊⓋⓌⓍⓎⓏⓐⓑⓒⓓⓔⓕⓖⓗⓘⓙⓚⓛⓜⓝⓞⓟⓠⓡⓢⓣⓤⓥⓦⓧⓨⓩ",
        "𝓐𝓑𝓒𝓓𝓔𝓕𝓖𝓗𝓘𝓙𝓚𝓛𝓜𝓝𝓞𝓟𝓠𝓡𝓢𝓣𝓤𝓥𝓦𝓧𝓨𝓩𝓪𝓫𝓬𝓭𝓮𝓯𝓰𝓱𝓲𝓳𝓴𝓵𝓶𝓷𝓸𝓹𝓺𝓻𝓼𝓽𝓾𝓿𝔀𝔁𝔂𝔃",
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz",
    )        
    family %= 10
    if family < len(targets):
        result = text.translate(str.maketrans(upper + lower, targets[family]))
    elif family == 5:
        result = text.upper()
    elif family == 6:
        result = text.title()
    elif family == 7:
        result = text.translate(str.maketrans("AEIOUaeiou", "ΛΞΙΘЦλξιθц"))
    elif family == 8:
        result = text.translate(str.maketrans("AEIOSTaeiost", "431057431057"))
    else:
        result = text.translate(str.maketrans({
            "A": "🅰", "a": "🅰", "B": "🅱", "b": "🅱", "E": "ℰ", "e": "ℰ",
            "I": "ℐ", "i": "ℐ", "O": "⭕", "o": "⭕", "P": "🅿", "p": "🅿",
            "S": "§", "T": "✝", "X": "❌", "a": "🅰", "b": "🅱", "e": "ℰ",
            "i": "ℐ", "o": "⭕", "p": "🅿", "s": "§", "t": "✝", "x": "❌",
            "U": "𝒰", "u": "𝒰",
        }))
    if decoration == 1:
        result = " ".join(result)
    elif decoration == 2:
        result = f"✦ {result} ✦"
    elif decoration == 3:
        result = f"⸎ {result} ⸎"
    elif decoration == 4:
        result = f"🎤 {result} 🎤"
    return result


@lru_cache(maxsize=8192)
def stylize_karaoke_text(text: str, style: int) -> str:
    """Apply a retained or purpose-built karaoke glyph style."""
    global semantic
    index = (style - 1) % len(KARAOKE_STYLE_NAMES)
    if index == 0:
        return text
    index -= 1
    if index < len(KARAOKE_LEGACY_STYLES):
        return _legacy_karaoke_text(text, KARAOKE_LEGACY_STYLES[index])
    mode = index - len(KARAOKE_LEGACY_STYLES)
    if mode == 0:
        table = {
            **{chr(65 + offset): chr(0x1D5D4 + offset) for offset in range(26)},
            **{chr(97 + offset): chr(0x1D5EE + offset) for offset in range(26)},
        }
        return text.translate(str.maketrans(table))
    if mode == 1:
        table = {
            **{chr(65 + offset): chr(0x24B6 + offset) for offset in range(26)},
            **{chr(97 + offset): chr(0x24D0 + offset) for offset in range(26)},
        }
        return text.translate(str.maketrans(table))
    if mode == 2:
        close = {
            "A": "🅰", "a": "🅰", "B": "🅱", "b": "🅱", "E": "ℰ", "e": "ℰ",
            "I": "ℐ", "i": "ℐ", "O": "⭕", "o": "⭕", "P": "🅿", "p": "🅿",
            "S": "§", "T": "✝", "X": "❌", "a": "🅰", "b": "🅱", "e": "ℰ",
            "i": "ℐ", "o": "⭕", "p": "🅿", "s": "§", "t": "✝", "x": "❌",
            "U": "𝒰", "u": "𝒰",
        }
        return text.translate(str.maketrans(close))
    if mode == 3:
        return _legacy_karaoke_text(text, 21)
    pieces = re.split(r"(\s+)", text)
    base_style_count = len(KARAOKE_STYLE_NAMES) - 1
    return "".join(
        piece if not piece.strip() else stylize_karaoke_text(
            piece,
            int(hashlib.sha256(f"{index}:{piece}".encode("utf-8")).hexdigest(), 16)
            % base_style_count + 1,
        )
        for index, piece in enumerate(pieces)
    )



def stylize_web_karaoke_text(text: str, style: int) -> str:
    """Render web-karaoke style numbers by the public KARAOKE_STYLE_NAMES labels.

    The retained console style table has historical numeric aliases; V236 reused
    those aliases directly, so labels such as Uppercase could render a cursive
    legacy family. The browser gets an explicit semantic map instead.
    """
    style = min(len(KARAOKE_STYLE_NAMES), max(1, int(style)))
    name = KARAOKE_STYLE_NAMES[style - 1]
    upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    lower = "abcdefghijklmnopqrstuvwxyz"
    fraktur = "𝔄𝔅ℭ𝔇𝔈𝔉𝔊ℌℑ𝔍𝔎𝔏𝔐𝔑𝔒𝔓𝔔ℜ𝔖𝔗𝔘𝔙𝔚𝔛𝔜ℨ𝔞𝔟𝔠𝔡𝔢𝔣𝔤𝔥𝔦𝔧𝔨𝔩𝔪𝔫𝔬𝔭𝔮𝔯𝔰𝔱𝔲𝔳𝔴𝔵𝔶𝔷"
    circled = "ⒶⒷⒸⒹⒺⒻⒼⒽⒾⒿⓀⓁⓂⓃⓄⓅⓆⓇⓈⓉⓊⓋⓌⓍⓎⓏⓐⓑⓒⓓⓔⓕⓖⓗⓘⓙⓚⓛⓜⓝⓞⓟⓠⓡⓢⓣⓤⓥⓦⓧⓨⓩ"
    script = "𝓐𝓑𝓒𝓓𝓔𝓕𝓖𝓗𝓘𝓙𝓚𝓛𝓜𝓝𝓞𝓟𝓠𝓡𝓢𝓣𝓤𝓥𝓦𝓧𝓨𝓩𝓪𝓫𝓬𝓭𝓮𝓯𝓰𝓱𝓲𝓳𝓴𝓵𝓶𝓷𝓸𝓹𝓺𝓻𝓼𝓽𝓾𝓿𝔀𝔁𝔂𝔃"
    sans = "𝗔𝗕𝗖𝗗𝗘𝗙𝗚𝗛𝗜𝗝𝗞𝗟𝗠𝗡𝗢𝗣𝗤𝗥𝗦𝗧𝗨𝗩𝗪𝗫𝗬𝗭𝗮𝗯𝗰𝗱𝗲𝗳𝗴𝗵𝗶𝗷𝗸𝗹𝗺𝗻𝗼𝗽𝗾𝗿𝘀𝘁𝘂𝘃𝘄𝘅𝘆𝘇"
    def trans(target: str) -> str:
        return text.translate(str.maketrans(upper + lower, target))
    def spaced(value: str) -> str:
        return " ".join(value)
    greek = lambda value: value.translate(str.maketrans("AEIOUaeiou", "ΛΞΙΘЦλξιθц"))
    leet = lambda value: value.translate(str.maketrans("AEIOSTaeiost", "431057431057"))
    symbols = lambda value: value.translate(str.maketrans({
        "A":"🅰","a":"🅰","B":"🅱","b":"🅱","E":"ℰ","e":"ℰ","I":"ℐ","i":"ℐ",
        "O":"⭕","o":"⭕","P":"🅿","p":"🅿","S":"§","s":"§","T":"✝","t":"✝","X":"❌","x":"❌","U":"𝒰","u":"𝒰",
    }))
    if name == "Plain": return text
    if name == "Fraktur": return trans(fraktur)
    if name == "Fraktur Clean": return spaced(trans(fraktur))
    if name == "Fraktur Framed": return f"✦ {trans(fraktur)} ✦"
    if name == "Circled": return trans(circled)
    if name == "Circled Clean": return spaced(trans(circled))
    if name == "Cursive": return trans(script)
    if name == "Cursive Clean": return spaced(trans(script))
    if name == "Cursive Framed": return f"⸎ {trans(script)} ⸎"
    if name == "Uppercase": return text.upper()
    if name == "Greek": return greek(text)
    if name == "Greek Clean": return spaced(greek(text))
    if name == "Greek Framed": return f"⸎ {greek(text)} ⸎"
    if name == "Leetspeak": return leet(text)
    if name == "Leetspeak Clean": return spaced(leet(text))
    if name == "Symbol Mix": return symbols(text)
    if name == "Unicode Sans": return trans(sans)
    if name == "Enclosed Letters": return trans(circled)
    if name == "Closest Unicode": return symbols(text)
    if name == "Script": return trans(script)
    return stylize_karaoke_text(text, len(KARAOKE_STYLE_NAMES))


def emojimax_plain_with_solutions(
    text: str,
    enabled: bool = True,
    *,
    monochrome_safe: bool = False,
) -> tuple[str, list[dict[str, str]]]:
    """Return plain Emojimax text plus ordered replacement→source hover records."""
    source = str(text or "").strip()
    if not enabled or not source:
        return source, []
    protected = source
    phrase_tokens: dict[str, tuple[str, str]] = {}
    for index, (phrase, replacement) in enumerate(_emojimax_phrase_items()):
        if monochrome_safe and not emojimax_monochrome_safe_replacement(phrase, replacement):
            continue
        token = "\ue000" + chr(0xE100 + index) + "\ue001"
        escaped = re.escape(phrase)
        prefix = r"(?<!\w)" if phrase and (phrase[0].isalnum() or phrase[0] == "_") else ""
        suffix = r"(?!\w)" if phrase and (phrase[-1].isalnum() or phrase[-1] == "_") else ""
        replaced = re.sub(prefix + escaped + suffix, token, protected, flags=re.IGNORECASE)
        if replaced != protected:
            phrase_tokens[token] = (replacement, phrase)
            protected = replaced

    wind_nonsubstitution_followers = {
        "up", "down", "left", "right", "clockwise", "counterclockwise",
        "anticlockwise", "north", "south", "east", "west", "northeast",
        "northwest", "southeast", "southwest", "forward", "forwards",
        "backward", "backwards", "in", "out", "around", "round", "tight",
        "tighter", "loose", "loosely",
    }
    pieces: list[str] = []
    solutions: list[dict[str, str]] = []
    token_pattern = re.compile("(" + "|".join(re.escape(token) for token in phrase_tokens) + ")") if phrase_tokens else None

    def emit_literal(chunk: str) -> None:
        if not chunk:
            return
        if token_pattern is None:
            pieces.append(chunk)
            return
        cursor = 0
        for token_match in token_pattern.finditer(chunk):
            pieces.append(chunk[cursor:token_match.start()])
            replacement, phrase = phrase_tokens[token_match.group(0)]
            pieces.append(replacement)
            solutions.append({"display": replacement, "solution": phrase})
            cursor = token_match.end()
        pieces.append(chunk[cursor:])

    cursor = 0
    for match in re.finditer(r"\b[\w’']+\b", protected):
        emit_literal(protected[cursor:match.start()])
        word = match.group(0)
        key = word.casefold()
        replacement = semantic.get(key)
        if monochrome_safe and replacement is not None and not emojimax_monochrome_safe_replacement(key, replacement):
            replacement = None
        if key == "wind":
            follower = re.match(r"\s+([\w'-]+)", protected[match.end():])
            if follower and follower.group(1).casefold() in wind_nonsubstitution_followers:
                replacement = None
        if replacement is None:
            pieces.append(word)
        else:
            pieces.append(replacement)
            solutions.append({"display": replacement, "solution": word})
        cursor = match.end()
    emit_literal(protected[cursor:])

    result = re.sub(r"(?:⬆️|⬇️) (?=\S)", lambda match: match.group(0).rstrip(), "".join(pieces))
    return result.rstrip(), solutions


def stylize_web_karaoke_with_emojimax(text: str, style: int, enabled: bool) -> str:
    base = (
        stylize_karaoke_with_emojimax(text, 1, True, 1.0, force_emoji_when_enabled=True)
        if enabled else str(text or "").strip()
    )
    return stylize_web_karaoke_text(base, style)

def stylize_karaoke_with_emojimax(
    text: str,
    style: int,
    enabled: bool,
    opacity: float = 1.0,
    *,
    force_emoji_when_enabled: bool = False,
    fade_threshold_percent: float | None = None,
    monochrome_safe: bool = False,
    windows_terminal_compat: bool = False,
) -> str:
    """Apply cached Emojimaxx; monochrome popup mode may reject color-dependent substitutions."""
    clean_text = str(text).strip()
    threshold = HIDE_EMOJI_WHEN_FADE_IS_UNDER_X_PERCENT if fade_threshold_percent is None else float(fade_threshold_percent)
    emoji_visible = bool(enabled and (force_emoji_when_enabled or max(0.0, min(1.0, opacity)) * 100.0 >= threshold))
    if any(argument in {"--unit-tests", "-t"} for argument in sys.argv[1:]):
        return _stylize_karaoke_with_emojimax_uncached.__wrapped__(clean_text, int(style), emoji_visible, bool(monochrome_safe), bool(windows_terminal_compat))
    return _stylize_karaoke_with_emojimax_uncached(clean_text, int(style), emoji_visible, bool(monochrome_safe), bool(windows_terminal_compat))


@lru_cache(maxsize=4096)
@lru_cache(maxsize=8192)
def _stylize_karaoke_with_emojimax_uncached(
    text: str,
    style: int,
    emoji_visible: bool,
    monochrome_safe: bool = False,
    windows_terminal_compat: bool = False,
) -> str:
    """Apply semantic emoji using whole words/phrases only, optionally color-agnostic."""
    text = text.strip()
    if not emoji_visible:
        return stylize_karaoke_text(text, style)
    protected = text
    phrase_tokens: dict[str, str] = {}
    for index, (phrase, replacement) in enumerate(_emojimax_phrase_items()):
        if monochrome_safe and not emojimax_monochrome_safe_replacement(phrase, replacement):
            continue
        token = "\ue000" + chr(0xE100 + index) + "\ue001"
        escaped = re.escape(phrase)
        prefix = r"(?<!\w)" if phrase and (phrase[0].isalnum() or phrase[0] == "_") else ""
        suffix = r"(?!\w)" if phrase and (phrase[-1].isalnum() or phrase[-1] == "_") else ""
        replaced = re.sub(prefix + escaped + suffix, token, protected, flags=re.IGNORECASE)
        if replaced != protected:
            phrase_tokens[token] = windows_terminal_emojimax_replacement(replacement) if windows_terminal_compat else replacement
            protected = replaced
    wind_nonsubstitution_followers = {
        "up", "down", "left", "right", "clockwise", "counterclockwise",
        "anticlockwise", "north", "south", "east", "west", "northeast",
        "northwest", "southeast", "southwest", "forward", "forwards",
        "backward", "backwards", "in", "out", "around", "round", "tight",
        "tighter", "loose", "loosely",
    }
    pieces: list[str] = []
    cursor = 0
    for match in re.finditer(r"\b[\w’']+\b", protected):
        pieces.append(stylize_karaoke_text(protected[cursor:match.start()], style))
        word = match.group(0); key = word.casefold(); replacement = semantic.get(key)
        if monochrome_safe and replacement is not None and not emojimax_monochrome_safe_replacement(key, replacement):
            replacement = None
        if key == "wind":
            follower = re.match(r"\s+([\w'-]+)", protected[match.end():])
            if follower and follower.group(1).casefold() in wind_nonsubstitution_followers:
                replacement = None
        if replacement is None:
            pieces.append(stylize_karaoke_text(word, style))
        else:
            pieces.append(windows_terminal_emojimax_replacement(replacement) if windows_terminal_compat else replacement)
        cursor = match.end()
    pieces.append(stylize_karaoke_text(protected[cursor:], style))
    result = "".join(pieces)
    for token, replacement in phrase_tokens.items():
        result = result.replace(stylize_karaoke_text(token, style), replacement).replace(token, replacement)
    result = re.sub(r"(?:⬆️|⬇️) (?=\S)", lambda match: match.group(0).rstrip(), result)
    return result.rstrip()



def _choice_marks_fallback_path() -> Path:
    base = Path(os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()) / "PAFPlayer"
    return base / "choice-marks.json"


def _load_choice_marks_fallback() -> dict[str, object]:
    if os.name != "nt":
        return {}
    try:
        data = json.loads(_choice_marks_fallback_path().read_text(encoding="utf-8"))
        return dict(data) if isinstance(data, dict) else {}
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return {}


def _save_choice_marks_fallback(data: dict[str, object]) -> None:
    if os.name != "nt":
        return
    try:
        target = _choice_marks_fallback_path()
        target.parent.mkdir(parents=True, exist_ok=True)
        temporary = target.with_suffix(target.suffix + ".tmp")
        temporary.write_text(json.dumps(data, ensure_ascii=False, sort_keys=True), encoding="utf-8")
        os.replace(temporary, target)
    except OSError:
        pass


def registry_favorites(name: str) -> list[int]:
    if os.name != "nt":
        return []
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            value, _kind = winreg.QueryValueEx(key, name)
        return [int(item.strip()) for item in str(value).split(",") if re.fullmatch(r"[+-]?\d+", item.strip())]
    except OSError:
        raw = _load_choice_marks_fallback().get("favorites", {})
        if isinstance(raw, dict):
            values = raw.get(str(name), [])
            if isinstance(values, list):
                return [int(value) for value in values if isinstance(value, int)]
        return []


def save_registry_favorites(name: str, values: list[int]) -> None:
    if os.name != "nt":
        return
    clean = sorted(set(int(value) for value in values))
    try:
        import winreg
        with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            _safe_winreg_set_value(key, name, 0, winreg.REG_SZ, ",".join(map(str, clean)))
    except OSError:
        pass
    mirror = _load_choice_marks_fallback()
    favorites = mirror.setdefault("favorites", {})
    if isinstance(favorites, dict):
        favorites[str(name)] = clean
    _save_choice_marks_fallback(mirror)


