def load_player_settings() -> dict[str, int]:
    settings = dict(PLAYER_SETTING_DEFAULTS)
    if os.name != "nt":
        return settings
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            for name in settings:
                try:
                    value, _kind = winreg.QueryValueEx(key, name)
                    settings[name] = int(value)
                except (OSError, TypeError, ValueError):
                    pass
    except OSError:
        pass
    settings["VisualizerMode"] = min(len(VISUALIZER_MODE_NAMES), max(1, settings["VisualizerMode"]))
    settings["PersistenceMode"] = min(len(PERSISTENCE_MODE_NAMES), max(1, settings["PersistenceMode"]))
    settings["VisualizerGranularity"] = min(len(VISUALIZER_GRANULARITY_NAMES), max(1, settings["VisualizerGranularity"]))
    settings["VisualizerInputSource"] = min(len(LIVE_VISUALIZER_INPUT_NAMES), max(1, int(settings.get("VisualizerInputSource", DEFAULT_VISUALIZER_INPUT_SOURCE))))
    settings["ProcessingStyle"] = min(len(PROCESSING_STYLE_NAMES), max(1, settings.get("ProcessingStyle", PROCESSING_STYLE_NAMES.index("Signal Aurora") + 1)))
    settings["ColorStyle"] = min(len(PALETTE_NAMES), max(1, settings["ColorStyle"]))
    settings["ColorReverse"] = int(bool(settings["ColorReverse"]))
    settings["FrequencyWarp"] = int(bool(settings.get("FrequencyWarp", DEFAULT_FREQUENCY_WARP_ENABLED)))
    settings["KaraokeStyle"] = min(len(KARAOKE_STYLE_NAMES), max(1, settings["KaraokeStyle"]))
    settings["KaraokeTreatment"] = min(len(KARAOKE_TREATMENT_NAMES), max(1, settings["KaraokeTreatment"]))
    settings["DecensorConsoleKaraoke"] = int(bool(settings.get("DecensorConsoleKaraoke", 0)))
    settings["DecensorArtworkLyrics"] = int(bool(settings.get("DecensorArtworkLyrics", 0)))
    settings["DecensorFloatingLyrics"] = int(bool(settings.get("DecensorFloatingLyrics", 0)))
    settings["ConsoleKaraokeEnabled"] = int(bool(settings.get("ConsoleKaraokeEnabled", 1)))
    for _alert_setting, _default in (
        ("AlertNoReplayGain", 1), ("AlertMissingArtist", 1),
        ("AlertMissingTitle", 1), ("AlertMissingKaraoke", 0),
        ("AlertMissingLyrics", 0), ("AlertMissingArtwork", 0),
        ("AlertUnknownYear", 0), ("AlertUnknownGenre", 0),
        ("AlertEmbeddedLyricsMismatch", 1),
    ):
        settings[_alert_setting] = int(bool(settings.get(_alert_setting, _default)))
    settings["ProgressStyle"] = min(len(PROGRESS_STYLE_NAMES), max(1, settings["ProgressStyle"]))
    settings["ProgressBarEnabled"] = int(bool(settings.get("ProgressBarEnabled", 1)))
    settings["ProgressBeatReactive"] = int(bool(settings.get("ProgressBeatReactive", 1)))
    settings["ProgressBeatDetector"] = min(len(PROGRESS_BEAT_DETECTOR_NAMES), max(1, int(settings.get("ProgressBeatDetector", 1))))
    settings["ProgressBeatTreatment"] = min(len(PROGRESS_BEAT_TREATMENT_NAMES), max(1, int(settings.get("ProgressBeatTreatment", 3))))
    settings["CursiveFix"] = int(bool(settings.get("CursiveFix", 0)))
    settings["DrcsArtMicrotiles"] = int(bool(settings.get("DrcsArtMicrotiles", 0)))
    settings["DrcsArtBarMicrotiles"] = int(bool(settings.get("DrcsArtBarMicrotiles", 0)))
    settings["BarFadeStyle"] = min(len(FADE_STYLE_NAMES), max(1, settings.get("BarFadeStyle", 1)))
    settings["OutputChannels"] = settings["OutputChannels"] if settings["OutputChannels"] in {2, 5, 7, 12} else 2
    settings["OutputRate"] = settings.get("OutputRate", HDMI_PCM_OUTPUT_RATE) if settings.get("OutputRate", HDMI_PCM_OUTPUT_RATE) in OUTPUT_SAMPLE_RATES else HDMI_PCM_OUTPUT_RATE
    settings["OutputBitDepth"] = settings.get("OutputBitDepth", DEFAULT_OUTPUT_BIT_DEPTH) if settings.get("OutputBitDepth", DEFAULT_OUTPUT_BIT_DEPTH) in OUTPUT_BIT_DEPTHS else DEFAULT_OUTPUT_BIT_DEPTH
    settings["OutputDevice"] = max(-1, int(settings.get("OutputDevice", DEFAULT_OUTPUT_DEVICE_INDEX)))
    settings["OutputDevicesMask"] = max(1, int(settings.get("OutputDevicesMask", DEFAULT_OUTPUT_DEVICES_MASK)))
    settings["MMInspiredRenderer"] = int(bool(settings.get("MMInspiredRenderer", 0)))
    settings["Balance"] = min(100, max(-100, settings["Balance"]))
    settings["Volume"] = min(400, max(0, settings["Volume"]))
    settings["SpeedIndex"] = min(len(PLAYBACK_SPEEDS) - 1, max(0, settings["SpeedIndex"]))
    settings["HudDetails"] = int(bool(settings.get("HudDetails", 0)))
    settings["PlaybackPaused"] = int(bool(settings.get("PlaybackPaused", 0)))
    settings["KaraokeVisualizerExpansion"] = int(bool(settings.get("KaraokeVisualizerExpansion", 0)))
    settings["VisualizerRows"] = min(48, max(4, settings.get("VisualizerRows", DRCS_VISUALIZER_ROWS)))
    settings["TruncateTopVisualizerLines"] = min(8, max(0, settings.get("TruncateTopVisualizerLines", 2)))
    return settings


def save_player_settings(settings: dict[str, int]) -> None:
    if os.name != "nt":
        return
    import winreg
    with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
        for name, value in settings.items():
            _safe_winreg_set_value(key, name, 0, winreg.REG_DWORD, int(value))



USER_DEFAULT_PREFIX = "UserDefault_"


def save_user_default(name: str, value: int) -> None:
    """Persist one F1/default-marker value with a durable JSON mirror."""
    if os.name != "nt":
        return
    numeric = int(value)
    try:
        import winreg
        with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            # REG_DWORD cannot represent -1 portably through every Python/winreg
            # build; the mirror below therefore also preserves System Default.
            _safe_winreg_set_value(key, USER_DEFAULT_PREFIX + name, 0, winreg.REG_DWORD, numeric)
    except OSError:
        pass
    mirror = _load_choice_marks_fallback()
    defaults = mirror.setdefault("defaults", {})
    if isinstance(defaults, dict):
        defaults[str(name)] = numeric
    _save_choice_marks_fallback(mirror)


def load_user_defaults() -> dict[str, int]:
    """Overlay factory defaults with registry values, then durable mirror fallbacks."""
    values: dict[str, int] = {}
    if os.name != "nt":
        return values
    fallback = _load_choice_marks_fallback().get("defaults", {})
    if not isinstance(fallback, dict):
        fallback = {}
    registry_key = None
    try:
        import winreg
        registry_key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file")
    except OSError:
        registry_key = None
    try:
        for name in PLAYER_SETTING_DEFAULTS:
            loaded = False
            if registry_key is not None:
                try:
                    value, _kind = winreg.QueryValueEx(registry_key, USER_DEFAULT_PREFIX + name)
                    values[name] = int(value)
                    loaded = True
                except (OSError, TypeError, ValueError):
                    pass
            if not loaded and name in fallback:
                try:
                    values[name] = int(fallback[name])
                except (TypeError, ValueError):
                    pass
    finally:
        if registry_key is not None:
            with contextlib.suppress(Exception):
                registry_key.Close()
    return values


def effective_player_defaults() -> dict[str, int]:
    result = dict(PLAYER_SETTING_DEFAULTS)
    result.update(load_user_defaults())
    # Reuse the ordinary validation/clamping semantics without modifying the
    # registry: this explicit clamp mirrors load_player_settings for F1.
    result["VisualizerMode"] = min(len(VISUALIZER_MODE_NAMES), max(1, int(result["VisualizerMode"])))
    result["PersistenceMode"] = min(len(PERSISTENCE_MODE_NAMES), max(1, int(result["PersistenceMode"])))
    result["VisualizerGranularity"] = min(len(VISUALIZER_GRANULARITY_NAMES), max(1, int(result["VisualizerGranularity"])))
    result["VisualizerInputSource"] = min(len(LIVE_VISUALIZER_INPUT_NAMES), max(1, int(result.get("VisualizerInputSource", DEFAULT_VISUALIZER_INPUT_SOURCE))))
    result["ProcessingStyle"] = min(len(PROCESSING_STYLE_NAMES), max(1, int(result["ProcessingStyle"])))
    result["ColorStyle"] = min(len(PALETTE_NAMES), max(1, int(result["ColorStyle"])))
    result["BarFadeStyle"] = min(len(FADE_STYLE_NAMES), max(1, int(result.get("BarFadeStyle", 1))))
    result["ColorReverse"] = int(bool(result.get("ColorReverse", 0)))
    result["FrequencyWarp"] = int(bool(result.get("FrequencyWarp", 0)))
    result["HudDetails"] = int(bool(result.get("HudDetails", 0)))
    result["PlaybackPaused"] = int(bool(result.get("PlaybackPaused", 0)))
    return result


def playlist_resume_value_name(playlist_path: Path) -> str:
    """Return a stable registry value name for one playlist."""
    identity = str(playlist_path.absolute()).casefold().encode("utf-8")
    return "PlaylistResume_" + hashlib.sha256(identity).hexdigest()[:24]


LAST_PLAYLIST_RESUME_VALUE = "PlaylistResume_Last"


def _decode_playlist_resume(raw: object) -> tuple[Path, float] | None:
    try:
        payload = json.loads(str(raw))
        return Path(payload["track"]), max(0.0, float(payload["position"]))
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        return None


def load_playlist_resume(playlist_path: Path) -> tuple[Path, float] | None:
    """Load the most recently interrupted playlist track, across playlists.

    The old per-playlist value is retained as a compatibility fallback, but the
    global bookmark wins: starting a newly generated playlist should continue
    the song that was actually playing when the player was last closed, if that
    song is still present in the new playlist.
    """
    if os.name != "nt":
        return None
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            for value_name in (LAST_PLAYLIST_RESUME_VALUE, playlist_resume_value_name(playlist_path)):
                try:
                    raw, _kind = winreg.QueryValueEx(key, value_name)
                except OSError:
                    continue
                decoded = _decode_playlist_resume(raw)
                if decoded is not None:
                    return decoded
    except OSError:
        pass
    return None


def save_playlist_resume(playlist_path: Path, track: Path, position: float) -> None:
    """Persist both the playlist bookmark and the global last-played bookmark."""
    if os.name != "nt":
        return
    import winreg
    payload = json.dumps({"track": str(track.absolute()), "position": max(0.0, position)})
    with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
        _safe_winreg_set_value(key, playlist_resume_value_name(playlist_path), 0, winreg.REG_SZ, payload)
        _safe_winreg_set_value(key, LAST_PLAYLIST_RESUME_VALUE, 0, winreg.REG_SZ, payload)


def clear_playlist_resume(playlist_path: Path) -> None:
    """Remove a completed playlist bookmark."""
    if os.name != "nt":
        return
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file", 0, winreg.KEY_SET_VALUE) as key:
            for value_name in (playlist_resume_value_name(playlist_path), LAST_PLAYLIST_RESUME_VALUE):
                with contextlib.suppress(OSError):
                    winreg.DeleteValue(key, value_name)
    except OSError:
        pass


def toggle_registry_favorite(name: str, value: int) -> bool:
    values = registry_favorites(name)
    added = value not in values
    values.remove(value) if not added else values.append(value)
    save_registry_favorites(name, values)
    return added


def next_registry_favorite(name: str, current: int) -> int:
    values = registry_favorites(name)
    if not values:
        return current
    return values[(values.index(current) + 1) % len(values)] if current in values else values[0]


def first_registry_favorite(name: str, current: int) -> int:
    """Return the first saved favorite, or leave the current value unchanged."""
    values = registry_favorites(name)
    return values[0] if values else current


def load_favorite_visualizer_mode() -> int:
    """Load the favored DRCS mode from the current user's registry."""
    default_mode = VISUALIZER_TREATMENT_NAMES.index("Compressed") * len(VISUALIZER_TYPE_NAMES) + 1
    if os.name != "nt":
        return default_mode
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            value, _kind = winreg.QueryValueEx(key, "VisualizerMode")
        return min(len(VISUALIZER_MODE_NAMES), max(1, int(value)))
    except (OSError, TypeError, ValueError):
        return default_mode


def save_favorite_visualizer_mode(mode: int) -> None:
    """Persist the favored DRCS mode without replacing a config file."""
    if os.name != "nt":
        return
    import winreg
    with winreg.CreateKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
        _safe_winreg_set_value(key, "VisualizerMode", 0, winreg.REG_DWORD, int(mode))

SEEK_SECONDS = {
    SEEK_BACK_5: -5.0,
    SEEK_FORWARD_5: 5.0,
    SEEK_BACK_10: -10.0,
    SEEK_FORWARD_10: 10.0,
    SEEK_BACK_15: -15.0,
    SEEK_FORWARD_15: 15.0,
    SEEK_BACK_60: -60.0,
    SEEK_FORWARD_60: 60.0,
    SEEK_BACK_80: -80.0,
    SEEK_FORWARD_80: 80.0,
}

VOLUME_STEPS = {
    VOLUME_UP_5: 5,
    VOLUME_DOWN_5: -5,
    VOLUME_UP_20: 20,
    VOLUME_DOWN_20: -20,
}


def validate_file(file_path: str | os.PathLike[str]) -> Path:
    """Return a resolved, nonempty regular-file path or raise clearly."""
    path = Path(file_path).expanduser().resolve()
    if not path.exists():
        raise FileNotFoundError(
            f"The specified file does not exist: {path}"
        )
    if not path.is_file():
        raise IsADirectoryError(
            f"The specified path is a directory, not a file: {path}"
        )
    if path.stat().st_size == 0:
        raise ValueError(f"The specified file is empty: {path}")
    return path


def natural_path_key(path: Path) -> tuple[object, ...]:
    """Sort paths naturally and case-insensitively, including numeric names."""
    return tuple(
        int(part) if part.isdigit() else part.casefold()
        for part in re.split(r"(\d+)", str(path))
    )


def lexical_path_key(path: Path | str | os.PathLike[str]) -> str:
    """Return a normalized path identity without touching the filesystem.

    ``Path.resolve()`` can cause real filesystem work on Windows.  Playlist
    queues may contain tens of thousands of entries, so comparisons used only
    for identity/order must stay purely lexical.
    """
    return os.path.normcase(os.path.abspath(os.path.normpath(os.fspath(path))))


def same_audio_file_identity(
    left: Path | str | os.PathLike[str],
    right: Path | str | os.PathLike[str],
) -> bool:
    """Return True when two playlist paths identify the same physical audio file.

    Motivation: persistent shuffle caches can outlive path-representation changes
    (mapped drive vs UNC path, junction/symlink spelling, older cache formats, etc.).
    Pure lexical comparison then treats two names for one file as distinct and can
    replay the just-resumed track on the first `>` press.  Keep the hot path cheap:
    lexical equality wins immediately, and the filesystem-level ``samefile`` probe
    is attempted only when the basenames match.  That gives resume/navigation real
    file identity without reintroducing mass Path.resolve/stat work across a huge
    playlist.
    """
    if lexical_path_key(left) == lexical_path_key(right):
        return True
    try:
        left_path = Path(left)
        right_path = Path(right)
        if left_path.name.casefold() != right_path.name.casefold():
            return False
        return os.path.samefile(left_path, right_path)
    except (OSError, ValueError, TypeError):
        return False


def lexical_absolute_path(path: Path | str | os.PathLike[str]) -> Path:
    r"""Return an absolute normalized path without resolving junctions, symlinks, or mapped aliases.

    Motivation: PAFPlayer deliberately wants to preserve a user-friendly alias such
    as ``C:\mp3`` even when Windows ultimately points that tree at another drive.
    ``Path.resolve()`` can erase that spelling and reintroduce duplicate-looking
    catalog entries. ``abspath(normpath())`` makes the path absolute while keeping
    the alias representation intact.
    """
    return Path(os.path.abspath(os.path.normpath(os.fspath(path))))


def catalog_basename(path: Path | str | os.PathLike[str]) -> str:
    r"""Return a casefolded filename for either native or Windows-spelled paths.

    Motivation: tests and imported catalog text can contain literal ``C:\...``
    spellings even when PAFPlayer code is inspected on a non-Windows host.
    ``Path.name`` on POSIX treats backslashes as ordinary characters, so use
    ``PureWindowsPath`` whenever the spelling is clearly Windows-like.
    """
    raw = os.fspath(path)
    if re.match(r"^\s*[A-Za-z]:[\\/]", raw) or "\\" in raw:
        return PureWindowsPath(raw).name.casefold()
    return Path(raw).name.casefold()


def catalog_drive_letter(path: Path | str | os.PathLike[str]) -> str:
    """Extract a Windows-style drive letter even when tests run on non-Windows hosts."""
    raw = os.fspath(path)
    match = re.match(r"^\s*([A-Za-z]):[\\/]", raw)
    return match.group(1).upper() if match else ""


def catalog_alias_preference_key(path: Path | str | os.PathLike[str]) -> tuple[int, int, str]:
    r"""Rank physical aliases so C: wins, then shorter/readable spellings win deterministically.

    Motivation: Claire's ``C:\mp3`` tree is an intentional alias and should be the
    display/insertion spelling when the same existing audio is also reachable as
    ``T:\mp3``. The preference is representation-only: the candidate still has
    to exist and be proven the same physical file before any duplicate is removed.
    """
    raw = os.fspath(path)
    return (0 if catalog_drive_letter(path) == "C" else 1, len(raw), raw.casefold())


def deduplicate_audio_catalog_paths(values: Iterable[Path]) -> list[Path]:
    r"""Collapse duplicate physical audio aliases while preserving only existing files.

    Motivation: master lists can contain both an aliased ``C:\mp3\...`` path and
    its physical/mapped ``T:\mp3\...`` spelling.  Every displayed INS result must
    still exist.  A full pairwise ``samefile`` comparison would scale badly, so
    PAFPlayer first uses the filesystem's device/file-index identity from ``stat``
    as an O(n) physical key. A final same-basename ``samefile`` safety pass then
    catches mapped/subst/junction aliases whose two drive spellings report
    different device keys. Among aliases of one real file, C: wins; otherwise
    the shortest deterministic spelling wins.
    """
    preferred_by_physical: dict[tuple[object, ...], Path] = {}
    fallback_groups: dict[str, list[Path]] = {}

    for raw in values:
        path = lexical_absolute_path(raw)
        if path.suffix.casefold() not in AUDIO_EXTENSIONS or not path.is_file():
            continue
        try:
            stat = path.stat()
        except OSError:
            continue

        inode = int(getattr(stat, "st_ino", 0) or 0)
        device = int(getattr(stat, "st_dev", 0) or 0)
        if inode:
            key = ("stat", device, inode)
            existing = preferred_by_physical.get(key)
            if (
                existing is None
                or catalog_alias_preference_key(path) < catalog_alias_preference_key(existing)
            ):
                preferred_by_physical[key] = path
        else:
            fallback_groups.setdefault(catalog_basename(path), []).append(path)

    chosen = list(preferred_by_physical.values())
    for group in fallback_groups.values():
        chosen.extend(group)

    # A mapped/subst/junction alias can occasionally report a different st_dev
    # even though Windows samefile() proves the two names are one physical file.
    # Run a second, cheap basename-grouped identity pass over the already-small
    # stat representatives so C:\mp3 vs T:\mp3 is guaranteed to collapse.
    by_basename: dict[str, list[Path]] = {}
    for candidate in chosen:
        by_basename.setdefault(catalog_basename(candidate), []).append(candidate)

    final: list[Path] = []
    for group in by_basename.values():
        representatives: list[Path] = []
        for candidate in sorted(group, key=catalog_alias_preference_key):
            duplicate_index: int | None = None
            for index, existing in enumerate(representatives):
                if same_audio_file_identity(candidate, existing):
                    duplicate_index = index
                    break
            if duplicate_index is None:
                representatives.append(candidate)
            elif catalog_alias_preference_key(candidate) < catalog_alias_preference_key(
                representatives[duplicate_index]
            ):
                representatives[duplicate_index] = candidate
        final.extend(representatives)

    final.sort(key=natural_path_key)
    return final



def audio_files_in(directory: Path) -> list[Path]:
    """Return supported audio files directly inside one directory."""
    try:
        files = [
            path for path in directory.iterdir()
            if path.is_file() and path.suffix.casefold() in AUDIO_EXTENSIONS
        ]
    except OSError:
        return []
    return sorted(files, key=natural_path_key)


def random_audio_file(directory: Path) -> Path:
    """Choose one audio file from a directory without walking descendants."""
    choices = audio_files_in(directory.resolve())
    if not choices:
        raise FileNotFoundError(f"No audio files were found in: {directory}")
    return random.choice(choices)


def random_audio_file_recursive(directory: Path) -> Path:
    """Random-walk downward one directory at a time, then choose a leaf file."""
    current = directory.resolve()
    while True:
        try:
            children = [path for path in current.iterdir() if path.is_dir()]
        except OSError as exc:
            raise OSError(f"Could not inspect random directory {current}: {exc}") from exc
        if not children:
            return random_audio_file(current)
        current = random.choice(children)


def append_track_to_playlist_file(playlist_path: Path, track: Path) -> None:
    """Persist one audio path in M3U/M3U8/PLS/XSPF without touching the audio file.

    Motivation: INS is a playlist edit, never a filesystem move/copy/delete. The
    disk representation should remain valid for every playlist type PAFPlayer
    already consumes. M3U variants append an absolute path, PLS adds a numbered
    File/Title/Length record while updating NumberOfEntries, and XSPF inserts a
    URI track block before ``</trackList>``.
    """
    playlist = Path(playlist_path)
    audio = lexical_absolute_path(track)
    suffix = playlist.suffix.casefold()
    if suffix in {".m3u", ".m3u8"}:
        needs_newline = False
        if playlist.exists() and playlist.stat().st_size:
            try:
                with playlist.open("rb") as check:
                    check.seek(-1, os.SEEK_END)
                    needs_newline = check.read(1) not in {b"\n", b"\r"}
            except OSError:
                pass
        with playlist.open("a", encoding="utf-8", newline="\n") as handle:
            if needs_newline:
                handle.write("\n")
            handle.write(str(audio) + "\n")
        return

    original = playlist.read_text(encoding="utf-8-sig", errors="replace") if playlist.exists() else ""
    if suffix == ".pls":
        lines = original.splitlines()
        indices = []
        for line in lines:
            match = re.match(r"\s*File(\d+)\s*=", line, flags=re.I)
            if match:
                indices.append(int(match.group(1)))
        index = max(indices, default=0) + 1
        insert_at = next(
            (i for i, line in enumerate(lines) if re.match(r"\s*NumberOfEntries\s*=", line, flags=re.I)),
            len(lines),
        )
        lines[insert_at:insert_at] = [
            f"File{index}={audio}",
            f"Title{index}={audio.stem}",
            f"Length{index}=-1",
        ]
        found_count = False
        for i, line in enumerate(lines):
            if re.match(r"\s*NumberOfEntries\s*=", line, flags=re.I):
                lines[i] = f"NumberOfEntries={index}"
                found_count = True
                break
        if not found_count:
            lines.append(f"NumberOfEntries={index}")
        newline = "\r\n" if "\r\n" in original else "\n"
        playlist.write_text(newline.join(lines) + newline, encoding="utf-8")
        return

    if suffix == ".xspf":
        import html
        uri = audio.as_uri()
        block = (
            "    <track><location>" + html.escape(uri)
            + "</location><title>" + html.escape(audio.stem)
            + "</title></track>\n"
        )
        if "</trackList>" not in original:
            raise ValueError("XSPF playlist has no </trackList> element")
        playlist.write_text(original.replace("</trackList>", block + "  </trackList>", 1), encoding="utf-8")
        return
    raise ValueError(f"Unsupported playlist type for insertion: {playlist.suffix}")


class AudioCatalogIndex:
    """Keep an audio-only INS search index refreshed in a daemon thread.

    Motivation: searching Claire's whole library on every keystroke would stall
    the player. The preferred source is C:\\mp3\\lists\\everything.m3u; if absent,
    C:\\mp3\\filelist.txt is used. The worker watches source size/mtime every few
    seconds, reloads in the background, filters stale/non-audio paths, and exposes
    a lock-protected snapshot to the interactive picker.
    """
    def __init__(
        self,
        primary: Path = AUDIO_CATALOG_PRIMARY,
        fallback: Path = AUDIO_CATALOG_FALLBACK,
        refresh_seconds: float = AUDIO_CATALOG_REFRESH_SECONDS,
        library_root: Path = AUDIO_CATALOG_LIBRARY_ROOT,
    ) -> None:
        self.primary = Path(primary)
        self.fallback = Path(fallback)
        self.library_root = Path(library_root)
        self.refresh_seconds = max(2.0, float(refresh_seconds))
        self._lock = threading.RLock()
        self._entries: list[Path] = []
        self._search_records: tuple[tuple[Path, str, str, tuple[object, ...]], ...] = ()
        self._search_cache: dict[tuple[str, ...], tuple[int, tuple[Path, ...]]] = {}
        self._index_generation = 0
        self._source: Path | None = None
        self._signature: tuple[str, int, int] | None = None
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None
        self._query_scan_thread: threading.Thread | None = None
        self._query_scan_generation = 0
        self._query_scan_words: tuple[str, ...] = ()

    def start(self) -> None:
        if self._thread is not None and self._thread.is_alive():
            return
        self._thread = threading.Thread(target=self._worker, name="audio-catalog-refresh", daemon=True)
        self._thread.start()

    def close(self) -> None:
        self._stop.set()

    def _choose_source(self) -> Path | None:
        return self.primary if self.primary.is_file() else (self.fallback if self.fallback.is_file() else None)

    def _source_signature(self, source: Path | None) -> tuple[str, int, int] | None:
        if source is None:
            return None
        try:
            stat = source.stat()
            return (str(source).casefold(), int(stat.st_size), int(stat.st_mtime_ns))
        except OSError:
            return None

    def _read_source(self, source: Path) -> list[Path]:
        values: list[Path] = []
        if source.suffix.casefold() in PLAYLIST_EXTENSIONS:
            try:
                values = load_playlist(source, show_progress=False)
            except Exception:
                values = []
        else:
            try:
                raw_lines = source.read_text(encoding="utf-8-sig", errors="replace").splitlines()
            except OSError:
                raw_lines = []
            for raw in raw_lines:
                value = raw.strip().strip('"')
                if not value or value.startswith(("#", ";")):
                    continue
                candidate = Path(value)
                if not candidate.is_absolute():
                    candidate = source.parent / candidate
                if candidate.suffix.casefold() in AUDIO_EXTENSIONS and candidate.is_file():
                    values.append(lexical_absolute_path(candidate))
        return deduplicate_audio_catalog_paths(values)

    def refresh_now(self) -> None:
        source = self._choose_source()
        signature = self._source_signature(source)
        if signature == self._signature:
            return
        entries = self._read_source(source) if source is not None else []
        with self._lock:
            self._publish_entries_locked(entries)
            self._source = source
            self._signature = signature

    def _publish_entries_locked(self, entries: Iterable[Path]) -> None:
        """Publish one immutable lexical search index and invalidate query results.

        All filesystem existence/identity work happens before this method. INS
        keystrokes therefore scan only pre-casefolded strings and never call
        ``stat()``, ``samefile()``, or rebuild the physical-deduplication map.
        """
        published = list(entries)
        self._entries = published
        self._search_records = tuple(
            (path, str(path).casefold(), catalog_basename(path), natural_path_key(path))
            for path in published
        )
        self._index_generation += 1
        self._search_cache.clear()

    def _worker(self) -> None:
        while not self._stop.is_set():
            try:
                self.refresh_now()
            except Exception as exc:
                append_pafplayer_exception("audio catalog background refresh", exc)
            self._stop.wait(self.refresh_seconds)

    def snapshot(self) -> tuple[list[Path], Path | None]:
        self.start()
        with self._lock:
            return list(self._entries), self._source

    def _start_query_reconciliation(self, words: tuple[str, ...]) -> None:
        """Start/retarget one live filesystem scan for the current INS words.

        Motivation: the indexed master list is the fast answer, but it may lag
        behind the filesystem.  Rather than rewriting Claire's authoritative
        master files or launching a whole-library scan for every keystroke, one
        daemon worker is generation-cancelled/retargeted as the query changes.
        It walks the configured music root, keeps only audio paths containing all
        current words in any order, and merges newly discovered matches into the
        in-memory catalog.  Playback and typing never wait for this reconciliation.
        """
        # A one-character query can match most of a large music tree.  The
        # authoritative catalog already supplies immediate results, so wait for
        # at least three typed characters before starting the optional stale-list
        # reconciliation walk.
        if sum(len(word) for word in words) < 3 or not self.library_root.is_dir():
            return
        with self._lock:
            if words == self._query_scan_words and self._query_scan_thread is not None and self._query_scan_thread.is_alive():
                return
            self._query_scan_generation += 1
            generation = self._query_scan_generation
            self._query_scan_words = words

        def worker() -> None:
            discovered: list[Path] = []
            for root, _dirs, files in os.walk(self.library_root):
                with self._lock:
                    if generation != self._query_scan_generation or self._stop.is_set():
                        return
                root_path = Path(root)
                for filename in files:
                    candidate = root_path / filename
                    if candidate.suffix.casefold() not in AUDIO_EXTENSIONS:
                        continue
                    haystack = str(candidate).casefold()
                    if all(word in haystack for word in words):
                        discovered.append(lexical_absolute_path(candidate))
                if len(discovered) >= 256:
                    self._merge_reconciled(discovered)
                    discovered.clear()
            if discovered:
                self._merge_reconciled(discovered)

        thread = threading.Thread(
            target=worker,
            name="audio-catalog-query-reconcile",
            daemon=True,
        )
        with self._lock:
            self._query_scan_thread = thread
        thread.start()

    def _merge_reconciled(self, discovered: list[Path]) -> None:
        """Merge live-scan discoveries without holding the search lock during I/O."""
        cleaned = deduplicate_audio_catalog_paths(discovered)
        if not cleaned:
            return
        with self._lock:
            merged = list(self._entries)
            known = {lexical_path_key(path) for path in merged}
            changed = False
            for path in cleaned:
                key = lexical_path_key(path)
                if key in known:
                    continue
                known.add(key)
                merged.append(path)
                changed = True
            if changed:
                merged.sort(key=natural_path_key)
                self._publish_entries_locked(merged)

    def search(self, query: str) -> list[Path]:
        """Return existing, physically unique matches without stat'ing the whole library per keystroke.

        Motivation: the catalog is physically validated/deduplicated when it is
        loaded or reconciled. Re-running any stat pass on a typed character would
        defeat the in-memory index. Word filtering, ranking and cached repeats are
        therefore purely lexical until a background publisher replaces the index.
        """
        words = tuple(word.casefold() for word in re.findall(r"\S+", str(query)) if word.strip())
        self.start()
        with self._lock:
            generation = self._index_generation
            records = self._search_records
            cached = self._search_cache.get(words)
            if cached is not None and cached[0] == generation:
                return list(cached[1])
        if not words:
            result = tuple(record[0] for record in records[:5000])
            with self._lock:
                if generation == self._index_generation:
                    self._search_cache[words] = (generation, result)
            return list(result)
        self._start_query_reconciliation(words)                                     # Immediate results come from the immutable in-memory index; a daemon scan can add stale-list misses later.
        matches: list[tuple[int, int, tuple[object, ...], Path]] = []
        for path, haystack, filename, natural_key in records:
            if not all(word in haystack for word in words):
                continue
            filename_hits = sum(1 for word in words if word in filename)
            matches.append((-filename_hits, len(haystack), natural_key, path))
        matches.sort(key=lambda item: (item[0], item[1], item[2]))
        result = tuple(item[3] for item in matches)
        with self._lock:
            if generation == self._index_generation:
                if len(self._search_cache) >= 128:
                    self._search_cache.pop(next(iter(self._search_cache)))
                self._search_cache[words] = (generation, result)
        return list(result)


def traditional_windows_folder_picker(
    *,
    title: str = "Choose your music collection",
    initial_dir: Path | None = None,
) -> Path | None:
    """Open a conventional Windows directory picker for first-run music-root setup."""
    if os.name != "nt":
        return None
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk()
        root.withdraw()
        selected = filedialog.askdirectory(
            title=title,
            initialdir=str(initial_dir) if initial_dir and initial_dir.is_dir() else "C:\\",
            mustexist=True,
        )
        root.destroy()
    except Exception:
        return None
    if not selected:
        return None
    path = lexical_absolute_path(selected)
    return path if path.is_dir() else None


def windows_directory_junction_command(link: Path, target: Path) -> list[str]:
    r"""Build the exact cmd.exe mklink/J invocation used for Claire-style aliases.

    Motivation: PAFPlayer intentionally standardizes library access through
    ``C:\mp3`` and ``C:\music`` junctions rather than teaching every subsystem a
    variable root.  Keeping command construction separate makes the destructive
    boundary obvious and unit-testable; only missing link paths are ever created.
    """
    return [
        "cmd.exe",
        "/d",
        "/c",
        "mklink",
        "/J",
        str(link),
        str(target),
    ]


def create_windows_directory_junction(link: Path, target: Path) -> None:
    """Create one missing Windows directory junction and verify it became usable."""
    if os.name != "nt":
        raise OSError("directory junctions are Windows-only")
    link = Path(link)
    target = Path(target)
    if os.path.lexists(str(link)):
        if link.is_dir():
            return
        raise FileExistsError(f"{link} already exists and is not a directory")
    if not target.is_dir():
        raise FileNotFoundError(f"junction target does not exist: {target}")

    creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    result = subprocess.run(
        windows_directory_junction_command(link, target),
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        encoding="utf-8",
        errors="replace",
        creationflags=creationflags,
    )
    if result.returncode != 0 or not link.is_dir():
        detail = (result.stdout or "").strip()
        raise OSError(
            f"could not create junction {link} -> {target}"
            + (f": {detail}" if detail else "")
        )


def ensure_standard_music_collection_aliases(
    *,
    input_func=input,
    picker_func=traditional_windows_folder_picker,
) -> bool:
    r"""First-run bootstrap for the fixed C:\mp3 / C:\music library aliases.

    Motivation: a large amount of PAFPlayer/Claire ecosystem tooling deliberately
    assumes ``C:\mp3``.  If that alias is absent on Windows, silently continuing
    creates confusing downstream failures.  V88 asks for the real collection
    once, accepts either a typed path or ``F`` for a folder picker, creates
    ``C:\mp3`` and ``C:\music`` junctions to that existing collection, then
    ensures ``C:\mp3\lists`` exists.  Existing paths are never replaced.

    Returning False means setup was explicitly cancelled or failed, so normal
    playback initialization can stop instead of operating against a missing
    standard root.
    """
    if os.name != "nt":
        return True

    mp3_alias = Path(r"C:\mp3")
    music_alias = Path(r"C:\music")
    if mp3_alias.is_dir():
        return True
    if os.path.lexists(str(mp3_alias)):
        print(f"💥 C:\\mp3 exists but is not a usable directory: {mp3_alias}", file=sys.stderr)
        return False

    print("🎵 C:\\mp3 does not exist. PAFPlayer needs the standard music-library alias.")
    print("   Type the existing collection folder, or type F to choose it in a Windows folder picker.")
    print("   Press Enter on a blank line to cancel.")

    target: Path | None = None
    while target is None:
        try:
            answer = str(input_func("Music collection: ")).strip().strip('"')
        except (EOFError, KeyboardInterrupt):
            return False
        if not answer:
            return False
        if answer.casefold() == "f":
            target = picker_func(
                title="Choose the music collection that C:\\mp3 should point to",
                initial_dir=Path("C:\\"),
            )
            if target is None:
                print("⚠ No folder selected. Type another path, F, or blank to cancel.")
                continue
        else:
            expanded = os.path.expandvars(os.path.expanduser(answer))
            candidate = lexical_absolute_path(expanded)
            if not candidate.is_dir():
                print(f"⚠ That folder does not exist: {candidate}")
                continue
            target = candidate

    try:
        create_windows_directory_junction(mp3_alias, target)
        (mp3_alias / "lists").mkdir(parents=True, exist_ok=True)

        if not os.path.lexists(str(music_alias)):
            create_windows_directory_junction(music_alias, target)
        elif not music_alias.is_dir():
            print(
                "⚠ C:\\music already exists but is not a directory; leaving it untouched.",
                file=sys.stderr,
            )
        else:
            try:
                same_music_target = os.path.samefile(str(music_alias), str(target))
            except OSError:
                same_music_target = False
            if not same_music_target:
                print(
                    f"⚠ C:\\music already exists and points somewhere else; leaving it untouched: {music_alias}",
                    file=sys.stderr,
                )

        print(f"🔗 C:\\mp3  -> {target}")
        if music_alias.is_dir():
            print(f"🔗 C:\\music available at {music_alias}")
        print("📂 Ensured C:\\mp3\\lists")
        return mp3_alias.is_dir() and (mp3_alias / "lists").is_dir()
    except Exception as exc:
        print(f"💥 Could not initialize C:\\mp3 aliases: {exc}", file=sys.stderr)
        return False


def traditional_windows_playlist_file_picker(
    initial_dir: Path | None = None,
) -> Path | None:
    """Open a Windows file picker restricted to PAFPlayer playlist formats.

    Motivation: Ctrl+O is conventional "Open" behavior. Choosing a playlist
    through a native picker is safer than splicing an unrelated playlist's
    queue/cache/history workers into the current visit.
    """
    if os.name != "nt":
        return None
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk()
        root.withdraw()
        patterns = " ".join(f"*{ext}" for ext in sorted(PLAYLIST_EXTENSIONS))
        selected = filedialog.askopenfilename(
            title="Open playlist in PAFPlayer",
            initialdir=str(initial_dir) if initial_dir else r"C:\mp3\lists",
            filetypes=[("Playlists", patterns), ("All files", "*.*")],
        )
        root.destroy()
    except Exception:
        return None
    if not selected:
        return None
    path = lexical_absolute_path(selected)
    return path if path.is_file() and path.suffix.casefold() in PLAYLIST_EXTENSIONS else None


def relaunch_pafplayer_with_playlist(playlist_path: Path) -> int:
    """Replace this cleanly-shut-down session with a new playlist session.

    Motivation: playlist initialization owns history-biased shuffle workers,
    resume bookmarks, cache writers, runtime tombstones, and navigation history.
    A clean self-exec keeps those states isolated instead of risking
    cross-playlist corruption. The console stays the same.
    """
    playlist = lexical_absolute_path(playlist_path)
    if not playlist.is_file() or playlist.suffix.casefold() not in PLAYLIST_EXTENSIONS:
        return 1
    command = [sys.executable, str(Path(__file__).resolve()), str(playlist)]
    print(f"📂 Opening playlist: {playlist}", flush=True)
    try:
        os.execv(sys.executable, command)
    except OSError as exc:
        print(f"💥 Could not open playlist {playlist}: {exc}", file=sys.stderr)
        return 1
    return 0


def traditional_windows_audio_file_picker(initial_dir: Path | None = None) -> tuple[Path, ...] | None:
    """Open a multi-select Windows picker restricted to PAFPlayer audio files."""
    if os.name != "nt":
        return None
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk()
        root.withdraw()
        patterns = " ".join(f"*{ext}" for ext in sorted(AUDIO_EXTENSIONS))
        selected = filedialog.askopenfilenames(
            title="Add audio file(s) to current PAFPlayer playlist",
            initialdir=str(initial_dir) if initial_dir else r"C:\mp3",
            filetypes=[("Audio files", patterns), ("All files", "*.*")],
        )
        root.destroy()
    except Exception:
        return None
    if not selected:
        return None
    paths = tuple(
        Path(value) for value in selected
        if Path(value).is_file() and Path(value).suffix.casefold() in AUDIO_EXTENSIONS
    )
    return paths or None


def interactive_audio_catalog_picker(
    catalog: AudioCatalogIndex,
    *,
    render_callback=None,
    pump_callback=None,
    display_rows: int | None = None,
    sleeper_fn=time.sleep,
    initial_quit_q_presses: int = 0,
    quit_callback=None,
) -> Path | None:
    """Keyboard-first INS picker whose input wait never stalls playback painting.

    ``render_callback`` lets the player own cursor placement and confine the
    picker to HUD rows above the visualizer.  The standalone fallback retains the
    historical full-screen display. ``pump_callback`` services the visualizer
    while no key is waiting and may return ``False`` to abort cleanly.
    """
    if os.name != "nt":
        return None
    import msvcrt
    query = ""
    selected = 0
    page_top = 0
    consecutive_quit_q_presses = max(0, int(initial_quit_q_presses))
    while True:
        matches = catalog.search(query)
        if selected >= len(matches):
            selected = max(0, len(matches) - 1)
        terminal = shutil.get_terminal_size((120, 30))
        total_rows = max(4, int(display_rows or terminal.lines))
        rows = max(1, total_rows - 3)
        if selected < page_top:
            page_top = selected
        if selected >= page_top + rows:
            page_top = selected - rows + 1
        _entries, source = catalog.snapshot()
        rendered = [
            "\033[1;5;38;2;255;220;95m➕ Add to playlist — type words; Enter adds; Esc cancels; Shift+INS = Windows file picker\033[0m",
            f"\033[2;38;2;145;175;205mCatalog: {source or '(loading / unavailable)'}\033[0m",
            f"\033[1;5;38;2;140;225;255mWords any order: {query}█\033[0m",
        ]
        if not matches:
            rendered.append("\033[2;38;2;175;185;200m  (no matching audio files)\033[0m")
        for index, path in enumerate(matches[page_top:page_top + rows], page_top):
            marker = "➤" if index == selected else " "
            ansi = "\033[1;7;38;2;255;255;255m" if index == selected else "\033[38;2;175;205;225m"
            rendered.append(ansi + truncate_to_cells(f"{marker} {path}", max(10, terminal.columns - 1), "…") + "\033[0m")
        if render_callback is None:
            write_console("\033[2J\033[H" + "\n".join(rendered))
        else:
            render_callback(rendered[:total_rows])

        while not msvcrt.kbhit():
            if pump_callback is not None:
                try:
                    if pump_callback() is False:
                        return None
                except Exception as exc:
                    append_pafplayer_exception("INS prompt pump", exc)
            sleeper_fn(0.01)
        key = msvcrt.getwch()
        shift = _windows_key_down(0x10)
        ctrl = _windows_key_down(0x11)
        alt = _windows_key_down(0x12)
        if key == "\x11" or (key.isprintable() and key.casefold() == "q" and (ctrl or alt)):
            if quit_callback is not None:
                with contextlib.suppress(Exception):
                    quit_callback()
            return None
        if not (key.isprintable() and key.casefold() == "q"):
            consecutive_quit_q_presses = 0
        if key == "\x1b":
            return None
        if key in {"\r", "\n"}:
            return matches[selected] if matches else None
        if key in {"\b", "\x7f"}:
            query = query[:-1]
            selected = page_top = 0
            continue
        if key == "\t":
            if matches:
                selected = (selected - 1) % len(matches) if shift else (selected + 1) % len(matches)
                query = str(matches[selected])
                page_top = max(0, selected - rows // 2)
            continue
        if key in {"\x00", "\xe0"}:
            ext = msvcrt.getwch()
            if ext == "H" and matches:
                selected = max(0, selected - 1)
            elif ext == "P" and matches:
                selected = min(len(matches) - 1, selected + 1)
            elif ext == "I" and matches:
                selected = max(0, selected - rows)
            elif ext == "Q" and matches:
                selected = min(len(matches) - 1, selected + rows)
            elif ext == "R" and shift:
                picked = traditional_windows_audio_file_picker()
                if picked:
                    return picked[0]
            continue
        if key.isprintable():
            if key.casefold() == "q" and consecutive_quit_q_presses:
                consecutive_quit_q_presses, should_quit = catalog_picker_q_sequence_step(
                    consecutive_quit_q_presses, key
                )
                if should_quit:
                    if quit_callback is not None:
                        with contextlib.suppress(Exception):
                            quit_callback()
                    return None
                # The second Q remains real search text.  If the next key is not
                # Q the sequence resets and the user simply searches for q...
                query += key
                selected = page_top = 0
                continue
            query += key
            selected = page_top = 0


_PLAYLIST_BROWSER_LABEL_CACHE: dict[str, str] = {}
_PLAYLIST_BROWSER_HISTORY_PENDING: set[str] = set()
_PLAYLIST_BROWSER_HISTORY_LOCK = threading.Lock()
_PLAYLIST_BROWSER_HISTORY_QUEUE: queue.Queue[Path] = queue.Queue()
_PLAYLIST_BROWSER_HISTORY_WORKER_STARTED = False


def format_playlist_browser_last_played(played_at: float | None) -> str:
    """Format the requested compact right-column date as YY-MM-DD."""
    try:
        value = float(played_at or 0.0)
    except (TypeError, ValueError):
        value = 0.0
    if value <= 0.0:
        return "Never"
    try:
        return datetime.fromtimestamp(value).strftime("%y-%m-%d")
    except (OSError, OverflowError, ValueError):
        return "?"


def _ensure_playlist_browser_history_worker() -> None:
    """Resolve visible playlist history serially off the console/UI thread."""
    global _PLAYLIST_BROWSER_HISTORY_WORKER_STARTED
    with _PLAYLIST_BROWSER_HISTORY_LOCK:
        if _PLAYLIST_BROWSER_HISTORY_WORKER_STARTED:
            return
        _PLAYLIST_BROWSER_HISTORY_WORKER_STARTED = True

    def worker() -> None:
        while True:
            track = Path(_PLAYLIST_BROWSER_HISTORY_QUEUE.get())
            runtime_key = lexical_path_key(track)
            try:
                resolved = playlist_history_last_played_sync_candidate(track)
                if resolved is None and not _PLAYLIST_FULL_HISTORY_BACKFILL_READY.is_set():
                    _PLAYLIST_FULL_HISTORY_BACKFILL_READY.wait()
                    resolved = playlist_history_last_played_sync_candidate(track)
                # playlist_history_last_played_sync_candidate stores a definitive
                # zero itself once the authoritative history backfill is ready.
            except Exception:
                pass
            finally:
                with _PLAYLIST_BROWSER_HISTORY_LOCK:
                    _PLAYLIST_BROWSER_HISTORY_PENDING.discard(runtime_key)
                _PLAYLIST_BROWSER_HISTORY_QUEUE.task_done()
                # Playlist browsing must never become a disk/metadata hammer while
                # music and the visualizer are running.
                time.sleep(0.01)

    threading.Thread(
        target=worker, name="playlist-browser-history", daemon=True
    ).start()


def _playlist_browser_request_history(track: Path) -> None:
    runtime_key = lexical_path_key(Path(track))
    if runtime_key in _PLAYLIST_HISTORY_LAST_PLAYED_CACHE:
        return
    with _PLAYLIST_BROWSER_HISTORY_LOCK:
        if runtime_key in _PLAYLIST_BROWSER_HISTORY_PENDING:
            return
        _PLAYLIST_BROWSER_HISTORY_PENDING.add(runtime_key)
    _ensure_playlist_browser_history_worker()
    _PLAYLIST_BROWSER_HISTORY_QUEUE.put(Path(track))


def playlist_browser_last_played_cell(track: Path) -> str:
    """Return a fixed-width date/never/unknown cell without blocking browsing."""
    runtime_key = lexical_path_key(Path(track))
    if runtime_key in _PLAYLIST_HISTORY_LAST_PLAYED_CACHE:
        return format_playlist_browser_last_played(_PLAYLIST_HISTORY_LAST_PLAYED_CACHE[runtime_key])
    _playlist_browser_request_history(Path(track))
    return "········"


def _playlist_browser_display_path(path: Path, available_cells: int) -> tuple[str, str]:
    """Choose path/filename text lazily, probing metadata only when it cannot fit.

    First remove the visually redundant ``C:\\MP3\\`` library prefix.  Only if
    that still does not fit do we pay for metadata, cached by lexical path, and
    display ``Act - Title`` instead of repeatedly probing on every repaint.
    """
    full = str(path)
    trimmed = re.sub(r"(?i)^c:\\mp3\\", "", full)
    chosen = trimmed if terminal_cell_width(trimmed) < terminal_cell_width(full) else full
    filename = Path(chosen).name if "\\" not in chosen else PureWindowsPath(chosen).name
    prefix = chosen[:-len(filename)] if filename and chosen.endswith(filename) else chosen
    if terminal_cell_width(chosen) <= max(8, int(available_cells)):
        return prefix, filename
    key = lexical_path_key(Path(path))
    label = _PLAYLIST_BROWSER_LABEL_CACHE.get(key)
    if label is None:
        try:
            tags = probe_audio_tags(Path(path))
            act = str(tags.get("Artist") or tags.get("Album Artist") or "").strip()
            title = str(tags.get("Song") or tags.get("Title") or Path(path).stem).strip()
            label = " - ".join(value for value in (act, title) if value) or Path(path).name
        except Exception:
            label = Path(path).name
        _PLAYLIST_BROWSER_LABEL_CACHE[key] = label
    return "", label


def playlist_browser_row_ansi(
    path: Path,
    index: int,
    *,
    selected: bool,
    current: bool,
    width: int,
    focused: bool = False,
) -> str:
    """Render one playlist row with a fixed right-hand Last-played column."""
    hue = (0.56 + (int(index) * 0.06180339887498949)) % 1.0
    saturation = 0.54
    path_rgb = tuple(round(component * 255) for component in colorsys.hsv_to_rgb(hue, saturation * 0.55, 0.30))
    name_rgb = tuple(round(component * 255) for component in colorsys.hsv_to_rgb(hue, min(1.0, saturation * 1.08), 1.0))
    # ⭐ means truly selected; ➤ is only the keyboard focus; ▶ is playing now.
    marker = ("⭐" if selected else "➤" if focused else " ") + ("▶" if current else " ")
    number = f"{int(index) + 1:>7,} "
    last_played = playlist_browser_last_played_cell(Path(path))
    right_plain = f" │ {last_played:>8}"
    prefix_width = terminal_cell_width(marker + " " + number)
    available = max(8, int(width) - prefix_width - terminal_cell_width(right_plain))
    prefix, filename = _playlist_browser_display_path(Path(path), available)
    path_ansi = (
        f"\033[2;38;2;{path_rgb[0]};{path_rgb[1]};{path_rgb[2]}m" + prefix
        + f"\033[1;38;2;{name_rgb[0]};{name_rgb[1]};{name_rgb[2]}m" + filename
    )
    path_ansi = truncate_ansi_to_cells(path_ansi, available)
    selection_ansi = "\033[7m" if selected else ("\033[48;2;30;38;48m" if focused else "")
    return (
        selection_ansi
        + ("\033[1m" if selected or focused else "")
        + "\033[38;2;225;225;235m" + marker + " " + number
        + path_ansi
        + "\033[2;38;2;150;175;190m │ "
        + f"{last_played:>8}"
        + "\033[0m"
    )


def build_playlist_browser_snapshot(
    previous: Iterable[Path],
    active_order: Iterable[Path],
    current: Path,
    *,
    include_current_if_missing: bool = True,
) -> tuple[list[Path], int]:
    """Build previous/current/future browser rows without mass filesystem I/O.

    Motivation: V86's first implementation called ``is_file()`` for every future
    entry, which turns a 35,000-song PgUp/PgDn browser into tens of thousands of
    synchronous metadata reads.  The live playlist/queue is already an in-memory
    snapshot.  This helper performs only lexical set/list work in the common case;
    physical ``samefile`` fallback is used only if the current track cannot be
    found by its exact lexical spelling.  The single highlighted choice is
    existence-checked later when Enter is pressed.
    """
    previous_list = list(previous)
    order = list(active_order)
    current = Path(current)

    # Playlist entries are already absolute/lexically normalized when loaded, so
    # this browser hot path does not need abspath(normpath()) 35,000 times.
    # normcase alone is enough for the common exact-spelling lookup; samefile
    # remains the alias fallback below.
    fast_key = lambda path: os.path.normcase(os.fspath(path))
    previous_keys = {fast_key(path) for path in previous_list}
    current_key = fast_key(current)

    start_index = next(
        (
            index
            for index, path in enumerate(order)
            if fast_key(path) == current_key
        ),
        -1,
    )
    if start_index < 0:
        start_index = next(
            (
                index
                for index, path in enumerate(order)
                if same_audio_file_identity(path, current)
            ),
            -1,
        )

    ordered_future = (
        order[start_index + 1:] + order[:start_index]
        if start_index >= 0
        else order
    )
    future: list[Path] = []
    seen_future: set[str] = set()
    for path in ordered_future:
        key = fast_key(path)
        if key == current_key or key in previous_keys or key in seen_future:
            continue
        seen_future.add(key)
        future.append(path)

    if start_index < 0 and not include_current_if_missing:
        # A track explicitly removed while it is still playing is no longer a
        # playlist member. The playlist browser must not re-inject it merely to
        # obtain a ▶ current marker; returning -1 cleanly means “playing outside
        # this playlist” while the visible rows remain true playlist membership.
        return previous_list + future, -1
    snapshot = previous_list + [current] + future
    return snapshot, len(previous_list)


def render_audio_tags_overlay_page(
    audio_path: Path,
    source_rows: list[tuple[str, str, str]],
    page_index: int,
) -> tuple[int, int]:
    """Render one full-screen Alt+3 page without reading or blocking input."""
    terminal = shutil.get_terminal_size((120, 30))
    width = max(40, terminal.columns - 1)
    body_capacity = max(1, terminal.lines - 3)
    rendered: list[str] = []
    if not source_rows:
        rendered.append("\033[2;38;2;165;175;185m(no metadata tags found)\033[0m")
    else:
        for row_index, (source, key, value) in enumerate(source_rows):
            hue = (0.51 + row_index * 0.037) % 1.0
            key_rgb = tuple(
                round(component * 255)
                for component in colorsys.hsv_to_rgb(hue, 0.45, 0.90)
            )
            value_rgb = tuple(
                round(component * 255)
                for component in colorsys.hsv_to_rgb(hue, 0.24, 0.76)
            )
            display_key = truncate_to_cells(
                key,
                max(12, width // 2 - terminal_cell_width(source) - 2),
                "...",
            )
            prefix_plain = f"{source}:{display_key}: "
            available_value = max(12, width - terminal_cell_width(prefix_plain))
            preview = truncate_to_cells(value or "", available_value, "...")
            rendered.append(
                f"\033[2;38;2;145;155;175m{source}:\033[0m"
                f"\033[1;38;2;{key_rgb[0]};{key_rgb[1]};{key_rgb[2]}m{display_key}:\033[0m "
                f"\033[38;2;{value_rgb[0]};{value_rgb[1]};{value_rgb[2]}m{preview}\033[0m"
            )
    pages = [
        rendered[index:index + body_capacity]
        for index in range(0, len(rendered), body_capacity)
    ] or [[]]
    page_index = max(0, min(int(page_index), len(pages) - 1))
    title = f"🏷️ All tags — {Path(audio_path).name}"
    output = [
        "\033[2J\033[H\033[?25l",
        "\033[1;38;2;130;220;255m" + truncate_to_cells(title, width, "…") + "\033[0m",
        f"\033[2;38;2;190;190;205mPage {page_index + 1}/{len(pages)}  "
        "PgUp/PgDn/Home/End  Alt+3/Esc/Q close  •  playback/track controls stay live\033[0m",
        *[truncate_ansi_to_cells(line, width) for line in pages[page_index]],
    ]
    write_console("\n".join(output))
    return page_index, len(pages)


def interactive_audio_tags_overlay(audio_path: Path) -> None:
    """Display readable, priority-ordered metadata in a paged modal browser.

    Motivation: Alt+3 is a diagnostic/curiosity view, not ordinary HUD metadata.
    FFplay should continue uninterrupted while the console temporarily shows every
    available tag.  Every tag occupies exactly one terminal row: multiline and
    oversized raw payloads end in ``...`` instead of flooding the screen.
    Pagination is based on current terminal height; PgUp/PgDn/Home/End navigate
    pages, and Esc/Q return to playback rather than quitting PAFPlayer.
    """
    if os.name != "nt":
        return
    import msvcrt

    source_rows = complete_audio_tag_rows(Path(audio_path))
    page_index = 0

    while True:
        terminal = shutil.get_terminal_size((120, 30))
        width = max(40, terminal.columns - 1)
        body_capacity = max(1, terminal.lines - 3)

        rendered: list[str] = []
        if not source_rows:
            rendered.append("\033[2;38;2;165;175;185m(no metadata tags found)\033[0m")
        else:
            for row_index, (source, key, value) in enumerate(source_rows):
                hue = (0.51 + row_index * 0.037) % 1.0
                key_rgb = tuple(
                    round(component * 255)
                    for component in colorsys.hsv_to_rgb(hue, 0.45, 0.90)
                )
                value_rgb = tuple(
                    round(component * 255)
                    for component in colorsys.hsv_to_rgb(hue, 0.24, 0.76)
                )
                display_key = truncate_to_cells(
                    key,
                    max(12, width // 2 - terminal_cell_width(source) - 2),
                    "...",
                )
                prefix_plain = f"{source}:{display_key}: "
                available_value = max(12, width - terminal_cell_width(prefix_plain))
                preview = truncate_to_cells(value or "", available_value, "...")
                rendered.append(
                    f"\033[2;38;2;145;155;175m{source}:\033[0m"
                    f"\033[1;38;2;{key_rgb[0]};{key_rgb[1]};{key_rgb[2]}m{display_key}:\033[0m "
                    f"\033[38;2;{value_rgb[0]};{value_rgb[1]};{value_rgb[2]}m{preview}\033[0m"
                )

        pages = [
            rendered[index:index + body_capacity]
            for index in range(0, len(rendered), body_capacity)
        ] or [[]]
        page_index = max(0, min(page_index, len(pages) - 1))

        write_console("\033[2J\033[H")
        title = f"🏷️ All tags — {Path(audio_path).name}"
        print("\033[1;38;2;130;220;255m" + truncate_to_cells(title, width, "…") + "\033[0m")
        print(
            f"\033[2;38;2;190;190;205m"
            f"Page {page_index + 1}/{len(pages)}  PgUp/PgDn/Home/End  Esc/Q close"
            f"\033[0m"
        )
        for line in pages[page_index]:
            print(truncate_ansi_to_cells(line, width))

        key = msvcrt.getwch()
        if key == "\x1b" or key.casefold() == "q":
            return
        if key in {"\x00", "\xe0"}:
            ext = msvcrt.getwch()
            if ext in {"I", "H"}:
                page_index = max(0, page_index - 1)
            elif ext in {"Q", "P"}:
                page_index = min(len(pages) - 1, page_index + 1)
            elif ext == "G":
                page_index = 0
            elif ext == "O":
                page_index = len(pages) - 1
            continue
        if key == " ":
            page_index = min(len(pages) - 1, page_index + 1)


def _playlist_browser_prompt_page(total_pages: int) -> int | None:
    """Prompt for a 1-based page number without leaving the full-screen browser."""
    if os.name != "nt":
        return None
    import msvcrt
    total_pages = max(1, int(total_pages))
    digits = ""
    while True:
        terminal = shutil.get_terminal_size((120, 30))
        write_console(move_to(max(1, terminal.lines - 1)) + "\033[2K")
        write_console(f"Go to page (1-{total_pages}): {digits}")
        key = msvcrt.getwch()
        if key == "\x1b":
            return None
        if key in {"\r", "\n"}:
            if not digits:
                return None
            value = int(digits)
            return min(total_pages, max(1, value)) - 1
        if key == "\b":
            digits = digits[:-1]
            continue
        if key.isdigit() and len(digits) < max(1, len(str(total_pages))):
            digits += key


def interactive_playlist_browser(
    paths: list[Path],
    current_index: int,
    *,
    initial_direction: int,
    queue_callback=None,
) -> Path | None:
    """Browse/queue a playlist with Windows-file-picker-style selection semantics.

    Enter queues the focused/selected rows; Shift+Enter performs the old immediate
    jump. Space toggles one row. Shift+Up/Down extends a contiguous selection.
    Home/End (including Ctrl variants) go to the first/last page; G prompts for a
    page number. The browser stays open after queueing so it can be used as a real
    queue-building surface rather than a one-shot chooser.
    """
    if os.name != "nt" or not paths:
        return None
    import msvcrt

    cursor = max(0, min(len(paths) - 1, current_index + (-1 if initial_direction < 0 else 1)))
    selected_rows: set[int] = set()
    selection_anchor = cursor
    notice = ""

    def selected_for_queue() -> list[int]:
        return sorted(selected_rows) if selected_rows else [cursor]

    while True:
        terminal = shutil.get_terminal_size((120, 30))
        rows = max(3, terminal.lines - 5)
        total_pages = max(1, math.ceil(len(paths) / rows))
        page_index = min(total_pages - 1, cursor // rows)
        top = page_index * rows
        write_console("\033[2J\033[H")
        print("📜 Playlist | Enter queue • Shift+Q enqueue next • Shift+Enter jump • Space select • Shift+↑/↓ extend")
        print(
            f"Page {page_index + 1:,}/{total_pages:,}  •  song {cursor + 1:,}/{len(paths):,}  •  "
            "PgUp/PgDn • Home/End • G page • Esc close"
            + (f"  •  {notice}" if notice else "")
        )
        browser_width = max(10, terminal.columns - 1)
        date_header = " │ Last play"
        track_header_width = max(8, browser_width - terminal_cell_width(date_header))
        print(
            "\033[2;38;2;145;155;170m"
            + truncate_to_cells("Track", track_header_width).ljust(track_header_width)
            + date_header
            + "\033[0m"
        )
        for index, path in enumerate(paths[top:top + rows], top):
            print(
                playlist_browser_row_ansi(
                    path,
                    index,
                    selected=(index in selected_rows),
                    focused=(index == cursor),
                    current=(index == current_index),
                    width=browser_width,
                )
            )
        notice = ""
        key = msvcrt.getwch()
        shift = _windows_key_down(0x10)
        ctrl = _windows_key_down(0x11)
        if key == "\x1b":
            return None
        if key in {"q", "Q"} and shift:
            indices = selected_for_queue()
            candidates = [paths[index] for index in indices if paths[index].is_file()]
            if queue_callback is None:
                notice = "queue unavailable"
            elif not candidates:
                notice = "nothing queueable selected"
            else:
                try:
                    queued = int(queue_callback(candidates) or 0)
                    notice = f"enqueued {queued} track{'s' if queued != 1 else ''} next"
                    selected_rows.clear(); selection_anchor = cursor
                except Exception as exc:
                    notice = f"queue failed: {exc}"
            continue
        if key in {"g", "G"}:
            target_page = _playlist_browser_prompt_page(total_pages)
            if target_page is not None:
                cursor = min(len(paths) - 1, target_page * rows)
                selected_rows.clear()
                selection_anchor = cursor
            continue
        if key == " ":
            if cursor in selected_rows:
                selected_rows.remove(cursor)
            else:
                selected_rows.add(cursor)
            selection_anchor = cursor
            continue
        if key in {"\r", "\n"}:
            if shift:
                candidate = paths[cursor]
                if candidate.is_file():
                    return candidate
                notice = "selected file is missing"
                continue
            indices = selected_for_queue()
            candidates = [paths[index] for index in indices if paths[index].is_file()]
            if not candidates:
                notice = "nothing queueable selected"
                continue
            if queue_callback is None:
                notice = "queue unavailable"
                continue
            try:
                queued = int(queue_callback(candidates) or 0)
            except Exception as exc:
                notice = f"queue failed: {exc}"
            else:
                notice = f"queued {queued} track{'s' if queued != 1 else ''} next"
                selected_rows.clear()
                selection_anchor = cursor
            continue
        if key in {"\x00", "\xe0"}:
            ext = msvcrt.getwch()
            if ext in {"H", "P"}:  # Up / Down
                old_cursor = cursor
                cursor = max(0, cursor - 1) if ext == "H" else min(len(paths) - 1, cursor + 1)
                if shift:
                    lo, hi = sorted((selection_anchor, cursor))
                    selected_rows = set(range(lo, hi + 1))
                else:
                    selected_rows.clear()
                    selection_anchor = cursor
            elif ext == "I":  # PgUp
                cursor = max(0, cursor - rows)
                selected_rows.clear(); selection_anchor = cursor
            elif ext == "Q":  # PgDn
                cursor = min(len(paths) - 1, cursor + rows)
                selected_rows.clear(); selection_anchor = cursor
            elif ext == "G":  # Home, Ctrl+Home behaves the same here by design
                cursor = 0
                selected_rows.clear(); selection_anchor = cursor
            elif ext == "O":  # End, Ctrl+End likewise
                cursor = len(paths) - 1
                selected_rows.clear(); selection_anchor = cursor
            continue


def load_playlist(playlist_path: Path, *, show_progress: bool = True, progress_callback=None) -> list[Path]:
    """Load local audio entries from M3U/M3U8, PLS, or XSPF playlists."""
    playlist = playlist_path.expanduser().resolve()
    if not playlist.is_file():
        raise FileNotFoundError(f"Playlist does not exist: {playlist}")
    text = playlist.read_text(encoding="utf-8-sig", errors="replace")
    suffix = playlist.suffix.casefold()
    entries: list[str]
    if suffix == ".pls":
        entries = [
            value.strip()
            for line in text.splitlines()
            for key, separator, value in [line.partition("=")]
            if separator and key.casefold().startswith("file") and value.strip()
        ]
    elif suffix == ".xspf":
        entries = re.findall(r"<location>(.*?)</location>", text, flags=re.I | re.S)
        from urllib.parse import unquote, urlparse
        entries = [
            unquote(urlparse(value.strip()).path.lstrip("/"))
            if value.strip().casefold().startswith("file:") else value.strip()
            for value in entries
        ]
    else:
        entries = [
            line.strip() for line in text.splitlines()
            if line.strip() and not line.lstrip().startswith("#")
        ]
    resolved: list[Path] = []
    total_entries = len(entries)
    # On huge playlists, stat'ing every path can mean tens of thousands of
    # random filesystem metadata reads.  Parse/normalize paths lexically and
    # validate only the track that is actually selected for playback.
    eager_existence_checks = total_entries <= PLAYLIST_EAGER_EXISTENCE_CHECK_LIMIT
    last_reported_percent = -5
    if progress_callback is not None:
        progress_callback(0)
        last_reported_percent = 0
    with progress_bar(
        total=total_entries,
        description="🎶 Loading playlist",
        unit="entry",
        enabled=bool(show_progress and getattr(sys.stderr, "isatty", lambda: False)()),
    ) as playlist_progress:
        for entry_index, entry in enumerate(entries, 1):
            if not re.match(r"^[a-z][a-z0-9+.-]*://", entry, flags=re.I):
                candidate = Path(entry)
                if not candidate.is_absolute():
                    candidate = playlist.parent / candidate
                candidate = Path(os.path.abspath(os.path.normpath(str(candidate))))
                if candidate.suffix.casefold() in AUDIO_EXTENSIONS and (
                    not eager_existence_checks or candidate.is_file()
                ):
                    resolved.append(candidate)
            if playlist_progress is not None:
                playlist_progress.update(1)
            if progress_callback is not None and total_entries > 0:
                percent = min(100, (entry_index * 100) // total_entries)
                report = min(100, (percent // 5) * 5)
                if report >= last_reported_percent + 5:
                    progress_callback(report)
                    last_reported_percent = report
    if progress_callback is not None and last_reported_percent < 100:
        progress_callback(100)
    if not resolved:
        raise ValueError(f"Playlist contains no usable local audio files: {playlist}")
    return resolved


def _playlist_line_candidate(playlist: Path, line: str, *, require_file: bool = True) -> Path | None:
    """Resolve one line-oriented playlist entry without reading the whole list."""
    text = line.strip().lstrip("\ufeff")
    if not text:
        return None
    suffix = playlist.suffix.casefold()
    if suffix == ".pls":
        key, separator, value = text.partition("=")
        if not separator or not key.casefold().startswith("file"):
            return None
        text = value.strip()
    elif suffix == ".xspf":
        match = re.search(r"<location>(.*?)</location>", text, flags=re.I | re.S)
        if not match:
            return None
        text = match.group(1).strip()
        from urllib.parse import unquote, urlparse
        if text.casefold().startswith("file:"):
            text = unquote(urlparse(text).path.lstrip("/"))
    elif text.startswith("#"):
        return None
    if re.match(r"^[a-z][a-z0-9+.-]*://", text, flags=re.I):
        return None
    candidate = Path(text)
    if not candidate.is_absolute():
        candidate = playlist.parent / candidate
    try:
        candidate = candidate.resolve(strict=False)
    except OSError:
        candidate = candidate.absolute()
    if candidate.suffix.casefold() not in AUDIO_EXTENSIONS:
        return None
    if require_file and not candidate.is_file():
        return None
    return candidate



def _playlist_entry_matches_track(playlist: Path, raw_entry: str, track: Path) -> bool:
    """Resolve one raw playlist entry and compare it with the current audio file.

    Motivation: the learned-removal hotkey must remove the same physical track
    from disk even when a playlist stores a relative path, alternate slash style,
    or equivalent spelling.  Reusing PAFPlayer's ordinary line candidate
    resolver keeps this edit consistent with playlist loading rather than doing
    fragile string equality against the displayed filename.
    """

    candidate = _playlist_line_candidate(playlist, raw_entry, require_file=False)
    return bool(candidate is not None and same_audio_file_identity(candidate, track))


def remove_track_from_playlist_file(playlist_path: Path, track: Path) -> int:
    """Remove every occurrence of one track from a supported playlist file.

    Motivation: pressing ``R`` during the short post-``learned`` window is an
    explicit playlist-edit command, not an audio-file delete.  The edit must be
    durable on disk and preserve as much human formatting as practical.  M3U/
    M3U8 lines and comments are retained verbatim except matching path lines;
    PLS removes the matching numbered record and renumbers remaining numbered
    keys while updating NumberOfEntries; XSPF removes matching ``<track>`` blocks
    while leaving the rest of the XML text untouched.  The caller separately
    updates the in-memory queue so playback can continue without reloading.
    """

    playlist = Path(playlist_path).expanduser().resolve()
    target = Path(track).expanduser().resolve(strict=False)
    if not playlist.is_file():
        raise FileNotFoundError(f"Playlist does not exist: {playlist}")

    original = playlist.read_text(encoding="utf-8-sig", errors="replace")
    suffix = playlist.suffix.casefold()
    removed = 0

    if suffix in {".m3u", ".m3u8"}:
        kept: list[str] = []
        for line in original.splitlines(keepends=True):
            content = line.rstrip("\r\n")
            if content.strip() and not content.lstrip().startswith("#") and _playlist_entry_matches_track(playlist, content, target):
                removed += 1
                continue
            kept.append(line)
        if removed:
            playlist.write_text("".join(kept), encoding="utf-8", newline="")
        return removed

    if suffix == ".pls":
        lines = original.splitlines()
        removed_indices: set[int] = set()
        for line in lines:
            key, sep, value = line.partition("=")
            match = re.fullmatch(r"\s*File(\d+)\s*", key, flags=re.I) if sep else None
            if match and _playlist_entry_matches_track(playlist, line, target):
                removed_indices.add(int(match.group(1)))
        if not removed_indices:
            return 0

        removed = len(removed_indices)
        remaining_old_indices = sorted({
            int(match.group(2))
            for line in lines
            for match in [re.match(r"(\s*)(?:File|Title|Length)(\d+)\s*=", line, flags=re.I)]
            if match and int(match.group(2)) not in removed_indices
        })
        remap = {old: new for new, old in enumerate(remaining_old_indices, 1)}
        rewritten: list[str] = []
        for line in lines:
            match = re.match(r"(\s*)(File|Title|Length)(\d+)(\s*=.*)$", line, flags=re.I)
            if match:
                old_index = int(match.group(3))
                if old_index in removed_indices:
                    continue
                new_index = remap.get(old_index, old_index)
                line = f"{match.group(1)}{match.group(2)}{new_index}{match.group(4)}"
            elif re.match(r"\s*NumberOfEntries\s*=", line, flags=re.I):
                prefix = line.split("=", 1)[0]
                line = f"{prefix}={len(remaining_old_indices)}"
            rewritten.append(line)
        newline = "\r\n" if "\r\n" in original else "\n"
        playlist.write_text(newline.join(rewritten) + (newline if original.endswith(("\n", "\r")) else ""), encoding="utf-8")
        return removed

    if suffix == ".xspf":
        track_pattern = re.compile(r"<track\b[^>]*>.*?</track>", flags=re.I | re.S)

        def maybe_remove(match: re.Match[str]) -> str:
            nonlocal removed
            block = match.group(0)
            location = re.search(r"<location>(.*?)</location>", block, flags=re.I | re.S)
            if location is None:
                return block
            pseudo_line = f"<location>{location.group(1)}</location>"
            if _playlist_entry_matches_track(playlist, pseudo_line, target):
                removed += 1
                return ""
            return block

        rewritten = track_pattern.sub(maybe_remove, original)
        if removed:
            playlist.write_text(rewritten, encoding="utf-8")
        return removed

    raise ValueError(f"Unsupported playlist type for removal: {playlist.suffix}")


def find_track_in_playlist_fast(playlist_path: Path, track: Path) -> Path | None:
    """Check a saved track with random-access text lookup, not a full parse."""
    playlist = playlist_path.expanduser().resolve()
    target = track.expanduser().resolve(strict=False)
    suffix = playlist.suffix.casefold()
    try:
        if suffix == ".xspf":
            # XML locations may be URL-escaped, so use the ordinary location
            # extraction here. XSPF is uncommon; M3U/PLS take the mmap fast path.
            text = playlist.read_text(encoding="utf-8-sig", errors="replace")
            for line in re.findall(r"<location>.*?</location>", text, flags=re.I | re.S):
                candidate = _playlist_line_candidate(playlist, line, require_file=False)
                if candidate is not None and candidate == target:
                    return target if target.is_file() else None
            return None

        import mmap
        needle = target.name.encode("utf-8", errors="ignore")
        if not needle or playlist.stat().st_size <= 0:
            return None
        with playlist.open("rb") as handle, mmap.mmap(handle.fileno(), 0, access=mmap.ACCESS_READ) as mapped:
            position = mapped.find(needle)
            while position >= 0:
                line_start = mapped.rfind(b"\n", 0, position) + 1
                line_end = mapped.find(b"\n", position)
                if line_end < 0:
                    line_end = len(mapped)
                line = mapped[line_start:line_end].decode("utf-8", errors="replace")
                candidate = _playlist_line_candidate(playlist, line, require_file=False)
                if candidate is not None and candidate == target:
                    return target if target.is_file() else None
                position = mapped.find(needle, position + max(1, len(needle)))
    except (OSError, ValueError):
        return None
    return None


def quick_random_playlist_track(playlist_path: Path, *, attempts: int = 64) -> Path:
    """Pick a usable playlist entry by random file seeks whenever practical.

    M3U/M3U8 and PLS are line-oriented, so a large list does not need to be
    parsed from the beginning just to start playback. XSPF is sampled in chunks
    around random byte offsets. A full load is only the fallback.
    """
    playlist = playlist_path.expanduser().resolve()
    size = playlist.stat().st_size
    if size <= 0:
        raise ValueError(f"Playlist is empty: {playlist}")
    suffix = playlist.suffix.casefold()
    with playlist.open("rb") as handle:
        for _ in range(max(1, attempts)):
            offset = random.randrange(size)
            handle.seek(offset)
            if offset:
                handle.readline()  # discard the partial line containing the seek point
            if suffix == ".xspf":
                blob = handle.read(min(65536, max(4096, size)))
                text = blob.decode("utf-8", errors="replace")
                locations = re.findall(r"<location>.*?</location>", text, flags=re.I | re.S)
                random.shuffle(locations)
                candidate_lines = locations
            else:
                candidate_lines = [
                    handle.readline().decode("utf-8", errors="replace")
                    for _line_number in range(24)
                ]
            for line in candidate_lines:
                candidate = _playlist_line_candidate(playlist, line)
                if candidate is not None:
                    return candidate
    # Small, unusual, or pathologically formatted playlists can fall back to
    # the ordinary parser; normal large M3U/PLS startup never gets here.
    return random.choice(load_playlist(playlist, show_progress=False))


def playlist_history_database_path() -> Path:
    r"""Return the one live Windows history DB: C:\bat\play_audio_file-play-history.sqlite3.

    V303 ends the historical hyphen/underscore fork. Normal Windows playback
    always uses the canonical hyphen spelling. PLAY_AUDIO_FILE_HISTORY_DB is
    retained only for unit tests and non-Windows development sandboxes.
    """
    canonical = Path(r"C:\bat\play_audio_file-play-history.sqlite3")
    if os.name == "nt" and not any(argument in {"--unit-tests", "-t"} for argument in sys.argv[1:]):
        return canonical
    override = os.environ.get("PLAY_AUDIO_FILE_HISTORY_DB")
    if override:
        return Path(override)
    if os.name == "nt":
        return canonical
    return Path(__file__).resolve().with_name("play_audio_file-play-history.sqlite3")


_PLAYLIST_HISTORY_COMPANION_MERGE_LOCK = threading.RLock()


def playlist_history_companion_database_paths(active_path: Path | None = None) -> list[Path]:
    """Return sibling DBs using either historical play-history filename spelling."""
    active = Path(active_path) if active_path is not None else playlist_history_database_path()
    names = ("play_audio_file-play-history.sqlite3", "play_audio_file-play_history.sqlite3")
    result: list[Path] = []
    active_key = str(active.absolute()).casefold()
    for name in names:
        candidate = active.with_name(name)
        if str(candidate.absolute()).casefold() != active_key and candidate.is_file():
            result.append(candidate)
    return result


def _playlist_history_database_signature(path: Path) -> str:
    """Include WAL state so a live companion DB is remerged after new writes."""
    pieces: list[str] = []
    for candidate in (Path(path), Path(str(path) + "-wal"), Path(str(path) + "-shm")):
        try:
            stat = candidate.stat()
            pieces.append(f"{candidate.name}:{stat.st_size}:{stat.st_mtime_ns}")
        except OSError:
            pieces.append(f"{candidate.name}:missing")
    return "|".join(pieces)


def merge_playlist_history_companion_databases(
    database: sqlite3.Connection,
    *,
    active_path: Path | None = None,
) -> int:
    """Merge the accidental history-filename fork into the active database.

    Both ``play_audio_file-play-history.sqlite3`` and
    ``play_audio_file-play_history.sqlite3`` have existed in real installs.
    Treat them as one logical history.  Newest timestamps win and a WAL-aware
    signature makes subsequent opens cheap.
    """
    active = Path(active_path) if active_path is not None else playlist_history_database_path()
    merged_rows = 0
    with _PLAYLIST_HISTORY_COMPANION_MERGE_LOCK:
        for companion in playlist_history_companion_database_paths(active):
            signature = _playlist_history_database_signature(companion)
            key_hash = hashlib.sha1(str(companion.absolute()).casefold().encode("utf-8", "replace")).hexdigest()[:16]
            meta_key = f"merged_companion_{key_hash}"
            previous = database.execute(
                "SELECT value FROM playlist_history_meta WHERE key=?", (meta_key,)
            ).fetchone()
            if previous is not None and str(previous[0]) == signature:
                continue
            try:
                source = sqlite3.connect(f"file:{companion}?mode=ro", uri=True)
            except sqlite3.Error:
                continue
            try:
                tables = {str(row[0]) for row in source.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'"
                ).fetchall()}
                legacy_rows: list[tuple[str, int, str, float]] = []
                identities: dict[tuple[str, str], tuple[str, str, int, str, float]] = {}

                def remember_identity(artist, title, duration, filename, played_at) -> None:
                    artist_display = re.sub(r"\s+", " ", history_punctuation_fold(str(artist or ""))).strip()
                    title_display = re.sub(r"\s+", " ", history_punctuation_fold(str(title or ""))).strip()
                    artist_key = normalize_playlist_history_text(artist_display)
                    title_key = normalize_playlist_history_text(title_display)
                    if not artist_key or not title_key:
                        return
                    try:
                        duration_value = max(0, int(duration or 0))
                        when = float(played_at)
                    except (TypeError, ValueError):
                        return
                    filename_key = playlist_history_filename_key(str(filename or "")) if filename else ""
                    key = (artist_key, title_key)
                    old = identities.get(key)
                    if old is None or when >= old[4]:
                        if old is not None:
                            if duration_value <= 0:
                                duration_value = old[2]
                            if not filename_key:
                                filename_key = old[3]
                        identities[key] = (artist_display, title_display, duration_value, filename_key, when)
                    elif old is not None:
                        identities[key] = (
                            old[0], old[1],
                            duration_value if old[2] <= 0 < duration_value else old[2],
                            filename_key if not old[3] and filename_key else old[3],
                            old[4],
                        )

                if "played_history_identities_recent" in tables:
                    for artist, title, duration, filename, played_at in source.execute(
                        "SELECT artist,title,duration_seconds,filename,played_at FROM played_history_identities_recent"
                    ):
                        remember_identity(artist, title, duration, filename, played_at)

                if "played_tracks_recent" in tables:
                    for filename, duration, tag, played_at in source.execute(
                        "SELECT filename,duration_seconds,tag,played_at FROM played_tracks_recent"
                    ):
                        filename_key = playlist_history_filename_key(str(filename or ""))
                        try:
                            duration_value = int(duration)
                            when = float(played_at)
                        except (TypeError, ValueError):
                            continue
                        tag_text = str(tag or "")
                        if filename_key and duration_value > 0 and tag_text and tag_text != "\x1f":
                            legacy_rows.append((filename_key, duration_value, tag_text, when))
                        artist, separator, title = tag_text.partition("\x1f")
                        if separator:
                            remember_identity(artist, title, duration_value, filename_key, when)

                if "played_tracks" in tables:
                    columns = {str(row[1]) for row in source.execute("PRAGMA table_info(played_tracks)").fetchall()}
                    if {"filename", "artist", "song", "played_at"}.issubset(columns):
                        for filename, artist, title, played_at in source.execute(
                            "SELECT filename,artist,song,played_at FROM played_tracks"
                        ):
                            remember_identity(artist, title, 0, filename, played_at)

                if legacy_rows:
                    database.executemany(
                        """INSERT INTO played_tracks_recent(filename,duration_seconds,tag,played_at)
                           VALUES(?,?,?,?)
                           ON CONFLICT(filename,duration_seconds,tag)
                           DO UPDATE SET played_at=MAX(played_tracks_recent.played_at,excluded.played_at)""",
                        legacy_rows,
                    )
                    merged_rows += len(legacy_rows)
                if identities:
                    database.executemany(
                        """INSERT INTO played_history_identities_recent(
                               artist_key,title_key,artist,title,duration_seconds,filename,played_at
                           ) VALUES(?,?,?,?,?,?,?)
                           ON CONFLICT(artist_key,title_key) DO UPDATE SET
                               artist=CASE WHEN excluded.played_at>=played_history_identities_recent.played_at THEN excluded.artist ELSE played_history_identities_recent.artist END,
                               title=CASE WHEN excluded.played_at>=played_history_identities_recent.played_at THEN excluded.title ELSE played_history_identities_recent.title END,
                               duration_seconds=CASE WHEN excluded.duration_seconds>0 THEN excluded.duration_seconds ELSE played_history_identities_recent.duration_seconds END,
                               filename=CASE WHEN excluded.filename<>'' THEN excluded.filename ELSE played_history_identities_recent.filename END,
                               played_at=MAX(played_history_identities_recent.played_at,excluded.played_at)""",
                        [(ak, tk, a, t, d, f, w) for (ak, tk), (a, t, d, f, w) in identities.items()],
                    )
                    merged_rows += len(identities)

                if "playlist_track_visits_recent" in tables:
                    visits = []
                    for path_key, visited_at in source.execute(
                        "SELECT path_key,visited_at FROM playlist_track_visits_recent"
                    ):
                        try:
                            visits.append((str(path_key), float(visited_at)))
                        except (TypeError, ValueError):
                            continue
                    if visits:
                        database.executemany(
                            """INSERT INTO playlist_track_visits_recent(path_key,visited_at) VALUES(?,?)
                               ON CONFLICT(path_key) DO UPDATE SET
                               visited_at=MAX(playlist_track_visits_recent.visited_at,excluded.visited_at)""",
                            visits,
                        )
                database.execute(
                    "INSERT INTO playlist_history_meta(key,value) VALUES(?,?) "
                    "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                    (meta_key, signature),
                )
            except sqlite3.Error as exc:
                append_pafplayer_exception(f"merge companion history {companion}", exc)
            finally:
                source.close()
    return merged_rows


def _history_companion_is_fully_merged(database: sqlite3.Connection, companion: Path) -> tuple[bool, str]:
    """Verify every usable companion history/identity row exists in the active DB."""
    try:
        source = sqlite3.connect(f"file:{Path(companion)}?mode=ro", uri=True)
    except sqlite3.Error as exc:
        return False, f"cannot reopen companion: {exc}"
    try:
        if str(source.execute("PRAGMA quick_check").fetchone()[0]).casefold() != "ok":
            return False, "companion quick_check failed"
        if str(database.execute("PRAGMA quick_check").fetchone()[0]).casefold() != "ok":
            return False, "canonical quick_check failed"
        tables = {str(row[0]) for row in source.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        if "played_tracks_recent" in tables:
            active_rows = {
                (str(f), int(d), str(t)): float(w)
                for f, d, t, w in database.execute(
                    "SELECT filename,duration_seconds,tag,played_at FROM played_tracks_recent"
                )
            }
            missing = 0
            for filename, duration, tag, played_at in source.execute(
                "SELECT filename,duration_seconds,tag,played_at FROM played_tracks_recent"
            ):
                try:
                    key = (playlist_history_filename_key(str(filename or "")), int(duration), str(tag or ""))
                    when = float(played_at)
                except (TypeError, ValueError):
                    continue
                if not key[0] or key[1] <= 0 or not key[2] or key[2] == "\x1f":
                    continue
                if active_rows.get(key, float("-inf")) + 1e-6 < when:
                    missing += 1
            if missing:
                return False, f"{missing} played_tracks_recent rows still missing"
        if "played_history_identities_recent" in tables:
            active_identities = {
                (str(ak), str(tk)): float(w)
                for ak, tk, w in database.execute(
                    "SELECT artist_key,title_key,played_at FROM played_history_identities_recent"
                )
            }
            missing = 0
            for artist, title, played_at in source.execute(
                "SELECT artist,title,played_at FROM played_history_identities_recent"
            ):
                ak = normalize_playlist_history_text(str(artist or ""))
                tk = normalize_playlist_history_text(str(title or ""))
                if not ak or not tk:
                    continue
                try:
                    when = float(played_at)
                except (TypeError, ValueError):
                    continue
                if active_identities.get((ak, tk), float("-inf")) + 1e-6 < when:
                    missing += 1
            if missing:
                return False, f"{missing} Artist/Song identities still missing"
        return True, "ok"
    except sqlite3.Error as exc:
        return False, str(exc)
    finally:
        source.close()


def archive_noncanonical_history_database_after_verified_merge(
    database: sqlite3.Connection, active_path: Path
) -> Path | None:
    r"""Rename C:\bat's underscore DB only after a verified V303 merge.

    The archive deliberately no longer ends in .sqlite3, so later PAFPlayer
    starts cannot mistake it for another live history database.
    """
    if os.name != "nt":
        return None
    canonical = Path(r"C:\bat\play_audio_file-play-history.sqlite3")
    if str(Path(active_path)).casefold() != str(canonical).casefold():
        return None
    companion = canonical.with_name("play_audio_file-play_history.sqlite3")
    if not companion.is_file():
        return None
    ok, reason = _history_companion_is_fully_merged(database, companion)
    if not ok:
        append_pafplayer_trace("history.repair.archive-skipped", path=companion, reason=reason)
        return None
    database.commit()
    stamp = time.strftime("%Y%m%d-%H%M%S")
    archive = companion.with_name(
        f"play_audio_file-play_history.MERGED-INTO-CANONICAL-v303-{stamp}.bak"
    )
    serial = 1
    while archive.exists():
        archive = companion.with_name(
            f"play_audio_file-play_history.MERGED-INTO-CANONICAL-v303-{stamp}-{serial}.bak"
        )
        serial += 1
    try:
        os.replace(companion, archive)
        for suffix in ("-wal", "-shm"):
            old = Path(str(companion) + suffix)
            if old.exists():
                with contextlib.suppress(OSError):
                    os.replace(old, Path(str(archive) + suffix))
    except OSError as exc:
        append_pafplayer_exception(f"archive noncanonical history {companion}", exc)
        return None
    database.execute(
        "INSERT INTO playlist_history_meta(key,value) VALUES('v303_archived_noncanonical',?) "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
        (str(archive),),
    )
    database.commit()
    append_pafplayer_trace("history.repair.archived", from_path=companion, to_path=archive)
    return archive


# Full paths are never written to earned-history SQLite. Persistent history uses
# a cheap normalized filename key first, then duration + normalized Artist/Title
# to disambiguate filename collisions. V314 may retain full paths only in the
# disposable temp metadata cache, guarded by exact file size + modification time.
_AUDIO_STREAM_LAYOUT_CACHE: dict[str, tuple[int, int, int | None, str | None]] = {}
_AUDIO_METADATA_CACHE: dict[str, tuple[int, int, float | None, dict[str, str]]] = {}
# V88: complete ffprobe tag payload for Alt+3.  This is populated by the same
# metadata probe so opening the tag browser normally costs no second ffprobe.
_AUDIO_RAW_TAG_CACHE: dict[str, tuple[int, int, dict[str, str]]] = {}
# ReplayGain stays out of the ordinary display-tag dictionary on purpose.  This
# parallel cache is populated by the same ffprobe payload that feeds Artist/Song/
# Album, so playback can use RG without paying for a second ffprobe.  The final
# boolean records whether Mutagen fallback has already been attempted for this
# exact size/mtime generation of the file.
_AUDIO_REPLAYGAIN_TAG_CACHE: dict[str, tuple[int, int, dict[str, str], bool]] = {}
REPLAYGAIN_TAG_KEYS = (
    "replaygain_track_gain",
    "replaygain_track_peak",
    "replaygain_album_gain",
    "replaygain_album_peak",
)
_PLAYLIST_HISTORY_IDENTITY_CACHE: dict[str, tuple[int, int, tuple[str, int, str]]] = {}
# V314: the shuffle's small ambiguous/missing subset survives process restarts
# in a temp JSON metadata cache. It is deliberately separate from the earned-
# history SQLite database; full paths never become earned-history identities.
_PLAYLIST_SHUFFLE_METADATA_CACHE: dict[str, tuple[int, int, float | None, dict[str, str]]] = {}
_PLAYLIST_SHUFFLE_METADATA_CACHE_PATH: Path | None = None
_PLAYLIST_SHUFFLE_METADATA_CACHE_DIRTY = False
_PLAYLIST_SHUFFLE_METADATA_CACHE_LOCK = threading.RLock()
_PLAYLIST_HISTORY_LAST_PLAYED_CACHE: dict[str, float] = {}
_PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE: dict[str, float] = {}
_PLAYLIST_FULL_HISTORY_BACKFILL_LOCK = threading.Lock()
_PLAYLIST_FULL_HISTORY_BACKFILL_STARTED = False
# V301: a missing Artist/Song row is not definitive while the potentially huge
# Last.fm CSV backfill is still running.  Start in the "ready" state so unit
# callers that never schedule a CSV import retain the historical synchronous
# behavior; schedule_playlist_history_full_identity_backfill() clears it only
# while a real import/signature check is in flight.
_PLAYLIST_FULL_HISTORY_BACKFILL_READY = threading.Event()
_PLAYLIST_FULL_HISTORY_BACKFILL_READY.set()
# A shuffle visit is deliberately broader than an earned play.  The ordinary
# local history normally requires one-third and Last.fm normally requires >50%
# genuinely heard (a continuous full play of a <=30-second stream supersedes
# both percentage rules), but a file
# becomes ineligible for near-term shuffle repetition as soon as PAFPlayer
# launches it.  Keep that second concept in its own cache/table so sampling and
# skipping a track cannot make it immediately eligible again.
_PLAYLIST_RECENT_VISIT_CACHE: dict[str, float] = {}

# Playback-start SQL policy (V67):
# Never make a predictable next track wait on SQLite. Playlist-wide history reads
# already happen in the background shuffle worker while the current song is
# playing. This filename-bucket cache supports the same rule for targeted
# prefetches: query only filename rows in a daemon worker, then let startup match
# duration/tag entirely in memory. A startup cache miss is allowed to mean
# "unknown/never" rather than issuing a synchronous SELECT.
_PLAYLIST_HISTORY_PREFETCH_ROWS: dict[str, list[tuple[int, str, float]]] = {}
_PLAYLIST_HISTORY_PREFETCH_LOCK = threading.Lock()
_PLAYLIST_HISTORY_PREFETCH_INFLIGHT: set[str] = set()


_HISTORY_PUNCT_TRANSLATION = str.maketrans({
    "\u2018": "'", "\u2019": "'", "\u201a": "'", "\u201b": "'", "\u02bc": "'", "\uff07": "'",
    "\u201c": '"', "\u201d": '"', "\u201e": '"', "\u201f": '"', "\u00ab": '"', "\u00bb": '"', "\uff02": '"',
    "\u2010": "-", "\u2011": "-", "\u2012": "-", "\u2013": "-", "\u2014": "-", "\u2212": "-",
})


def history_punctuation_fold(value: str) -> str:
    """Fold typography-only differences while preserving meaningful punctuation."""
    return unicodedata.normalize("NFKC", str(value or "")).translate(_HISTORY_PUNCT_TRANSLATION)


def normalize_playlist_history_text(value: str) -> str:
    """Canonical case/quote-insensitive identity component."""
    normalized = history_punctuation_fold(value)
    return re.sub(r"\s+", " ", normalized).strip().casefold()


def history_search_match(pattern: str, matcher: re.Pattern[str], value: str) -> bool:
    """Match history text without case or typography differences.

    Plain searches (the overwhelmingly common ``--last-played metallica`` form)
    use Unicode ``casefold`` on both sides, which is stronger and more predictable
    than ``re.IGNORECASE`` alone.  Real regular expressions retain their syntax and
    use Python's case-insensitive regex engine after smart/straight punctuation
    folding.  This avoids corrupting regex escapes such as ``\\D`` by casefolding
    the regex source itself.
    """
    folded_pattern = history_punctuation_fold(str(pattern or ""))
    folded_value = history_punctuation_fold(str(value or ""))
    if not any(character in folded_pattern for character in r".^$*+?{}[]\|()"):
        return folded_pattern.casefold() in folded_value.casefold()
    return matcher.search(folded_value) is not None


def normalize_playlist_history_stored_tag(tag: str) -> str:
    artist, separator, title = str(tag or "").partition("\x1f")
    if not separator:
        return normalize_playlist_history_text(tag)
    return "\x1f".join((normalize_playlist_history_text(artist), normalize_playlist_history_text(title)))


def playlist_history_tag_is_usable(tag: str | None) -> bool:
    """True only when history contains both a real Artist and Song identity."""
    artist, separator, title = normalize_playlist_history_stored_tag(str(tag or "")).partition("\x1f")
    return bool(separator and artist and title)


def playlist_history_resolve_filename_candidates(
    candidates: list[tuple[int, str, float]] | tuple[tuple[int, str, float], ...],
    *,
    duration_seconds: float | int | None = None,
    tags: dict[str, str] | None = None,
) -> float | None:
    """Resolve basename history without ever stealing another Artist+Song's play."""
    if not candidates:
        return None
    try:
        numeric = float(duration_seconds) if duration_seconds is not None else 0.0
        duration = max(1, int(round(numeric))) if math.isfinite(numeric) and numeric > 0 else 0
    except (TypeError, ValueError):
        duration = 0
    current_tag = playlist_history_tag_key(tags or {}) if tags else ""
    canonical_current = normalize_playlist_history_stored_tag(current_tag)
    current_tag_usable = playlist_history_tag_is_usable(canonical_current)
    if current_tag_usable:
        tag_matches = [
            float(when) for _stored_duration, stored_tag, when in candidates
            if playlist_history_tag_is_usable(stored_tag)
            and normalize_playlist_history_stored_tag(stored_tag) == canonical_current
        ]
        if tag_matches:
            return max(tag_matches)
        duration_matches = [
            float(when) for stored_duration, stored_tag, when in candidates
            if not playlist_history_tag_is_usable(stored_tag)
            and duration > 1 and int(stored_duration) > 1
            and abs(int(stored_duration) - duration) <= 2
        ]
        return max(duration_matches, default=None)
    duration_matches = [
        float(when) for stored_duration, stored_tag, when in candidates
        if not playlist_history_tag_is_usable(stored_tag)
        and duration > 1 and int(stored_duration) > 1
        and abs(int(stored_duration) - duration) <= 2
    ]
    return max(duration_matches, default=None)


def playlist_history_filename_key(value: str | os.PathLike[str] | Path) -> str:
    """Return the cheap basename-only history key.

    No directory is retained. The audio extension and a conventional leading
    numeric track prefix (``08_``, ``7-``, ``03.`` and similar) are stripped so
    a library move or format conversion does not defeat the filename fast path.
    """
    if isinstance(value, Path):
        name = value.name
    else:
        raw = str(value or "")
        # Last.fm logs contain Windows paths even when tests run elsewhere.
        name = PureWindowsPath(raw).name if "\\" in raw else Path(raw).name
    stem = PureWindowsPath(name).stem
    stem = re.sub(r"^(?:\s*\d{1,3}\s*[-_. ]+\s*)+", "", stem)
    return normalize_playlist_history_text(stem)


def playlist_history_tag_key(tags: dict[str, str]) -> str:
    """Return the normalized Artist+Song identity used after filename."""
    artist = normalize_playlist_history_text(tags.get("Artist", ""))
    song = normalize_playlist_history_text(tags.get("Song", ""))
    return "\x1f".join((artist, song))


def probe_audio_history_identity(track: Path) -> tuple[str, int, str]:
    """Read basename key, duration and Artist/Title using one metadata probe."""
    duration, tags = probe_audio_metadata(track)
    try:
        numeric = float(duration) if duration is not None else 0.0
        duration_seconds = max(1, int(round(numeric))) if math.isfinite(numeric) and numeric > 0 else 0
    except (TypeError, ValueError):
        duration_seconds = 0
    return playlist_history_filename_key(track), duration_seconds, playlist_history_tag_key(tags)


def cache_playlist_history_identity(
    track: Path,
    duration_seconds: float | int | None,
    tags: dict[str, str],
) -> tuple[str, int, str]:
    """Cache an exact identity from metadata the player already obtained."""
    try:
        numeric = float(duration_seconds) if duration_seconds is not None else 0.0
        rounded_duration = max(1, int(round(numeric))) if math.isfinite(numeric) and numeric > 0 else 0
    except (TypeError, ValueError):
        rounded_duration = 0
    identity = (
        playlist_history_filename_key(track),
        rounded_duration,
        playlist_history_tag_key(tags),
    )
    try:
        stat = track.stat()
        cache_key = str(track.resolve()).casefold()
        _PLAYLIST_HISTORY_IDENTITY_CACHE[cache_key] = (stat.st_size, stat.st_mtime_ns, identity)
    except OSError:
        pass
    return identity


def playlist_shuffle_metadata_cache_path() -> Path:
    """Return the persistent, non-authoritative shuffle metadata cache path."""
    override = os.environ.get("PLAY_AUDIO_FILE_SHUFFLE_METADATA_CACHE")
    if override:
        return Path(override)
    return Path(tempfile.gettempdir()) / "play_audio_file" / "shuffle_metadata_cache.json"


def _load_playlist_shuffle_metadata_cache() -> None:
    """Load the size/mtime-validated metadata cache once per selected path."""
    global _PLAYLIST_SHUFFLE_METADATA_CACHE_PATH
    path = playlist_shuffle_metadata_cache_path()
    with _PLAYLIST_SHUFFLE_METADATA_CACHE_LOCK:
        if _PLAYLIST_SHUFFLE_METADATA_CACHE_PATH == path:
            return
        _PLAYLIST_SHUFFLE_METADATA_CACHE_PATH = path
        _PLAYLIST_SHUFFLE_METADATA_CACHE.clear()
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
            if int(payload.get("version", 0)) != 1:
                return
            raw_entries = payload.get("entries", {})
            if not isinstance(raw_entries, dict):
                return
            for cache_key, raw in raw_entries.items():
                if not isinstance(raw, list) or len(raw) != 4 or not isinstance(raw[3], dict):
                    continue
                size, mtime_ns, duration, tags = raw
                _PLAYLIST_SHUFFLE_METADATA_CACHE[str(cache_key)] = (
                    int(size), int(mtime_ns),
                    (None if duration is None else float(duration)),
                    {str(key): str(value) for key, value in tags.items()},
                )
        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            # A cache miss/corrupt temp file is harmless; ffprobe remains the
            # source of truth and the next successful save replaces it.
            _PLAYLIST_SHUFFLE_METADATA_CACHE.clear()


def save_playlist_shuffle_metadata_cache() -> None:
    """Atomically persist metadata learned by the background shuffle worker."""
    global _PLAYLIST_SHUFFLE_METADATA_CACHE_DIRTY
    _load_playlist_shuffle_metadata_cache()
    with _PLAYLIST_SHUFFLE_METADATA_CACHE_LOCK:
        if not _PLAYLIST_SHUFFLE_METADATA_CACHE_DIRTY:
            return
        path = playlist_shuffle_metadata_cache_path()
        entries = {
            cache_key: [size, mtime_ns, duration, tags]
            for cache_key, (size, mtime_ns, duration, tags) in _PLAYLIST_SHUFFLE_METADATA_CACHE.items()
        }
        payload = {"version": 1, "entries": entries}
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            temporary = path.with_name(f"{path.name}.{os.getpid()}.tmp")
            temporary.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
            os.replace(temporary, path)
            _PLAYLIST_SHUFFLE_METADATA_CACHE_DIRTY = False
        except OSError:
            return


def playlist_shuffle_cached_metadata(track: Path) -> tuple[float | None, dict[str, str]]:
    """Return full resolver metadata from RAM/temp cache, probing only on a miss."""
    global _PLAYLIST_SHUFFLE_METADATA_CACHE_DIRTY
    location = _audio_metadata_cache_location(Path(track))
    if location is None:
        return probe_audio_metadata(Path(track))
    cache_key, size, mtime_ns = location
    memory = _AUDIO_METADATA_CACHE.get(cache_key)
    if memory is not None and memory[0] == size and memory[1] == mtime_ns:
        return memory[2], dict(memory[3])
    _load_playlist_shuffle_metadata_cache()
    with _PLAYLIST_SHUFFLE_METADATA_CACHE_LOCK:
        cached = _PLAYLIST_SHUFFLE_METADATA_CACHE.get(cache_key)
    if cached is not None and cached[0] == size and cached[1] == mtime_ns:
        return cached[2], dict(cached[3])
    duration, tags = probe_audio_metadata(Path(track))
    with _PLAYLIST_SHUFFLE_METADATA_CACHE_LOCK:
        _PLAYLIST_SHUFFLE_METADATA_CACHE[cache_key] = (
            size, mtime_ns, duration, dict(tags or {}),
        )
        _PLAYLIST_SHUFFLE_METADATA_CACHE_DIRTY = True
    return duration, dict(tags or {})


def playlist_history_identity(track: Path) -> tuple[str, int, str]:
    """Return (filename_key, duration_seconds, normalized Artist+Title tag).

    The filename key is basename-only, with extension and a leading numeric
    track prefix removed. Full paths are used only as in-process cache keys and
    are never persisted.
    """
    try:
        stat = track.stat()
        cache_key = str(track.resolve()).casefold()
        cached = _PLAYLIST_HISTORY_IDENTITY_CACHE.get(cache_key)
        if cached is not None and cached[0] == stat.st_size and cached[1] == stat.st_mtime_ns:
            return cached[2]
    except OSError:
        stat = None
        cache_key = str(track.absolute()).casefold()

    identity = probe_audio_history_identity(track)
    if stat is not None:
        _PLAYLIST_HISTORY_IDENTITY_CACHE[cache_key] = (stat.st_size, stat.st_mtime_ns, identity)
    return identity


def _create_playlist_history_table(database: sqlite3.Connection) -> None:
    database.execute(
        """CREATE TABLE played_tracks_recent (
            filename TEXT NOT NULL,
            duration_seconds INTEGER NOT NULL,
            tag TEXT NOT NULL,
            played_at REAL NOT NULL,
            PRIMARY KEY (filename, duration_seconds, tag)
        ) WITHOUT ROWID"""
    )


def _ensure_playlist_full_identity_table(database: sqlite3.Connection) -> None:
    """Maintain one canonical latest row per Artist/Song, independent of duration.

    V239/V240 accidentally made duration part of the full-history primary key.
    That split remasters, retags and duration drift into separate identities. V248
    re-runs the canonicalization once so any stale case/typography-split keys left
    by an older generic build collapse to one Artist+Song key; the newest display
    spelling and best available duration/filename metadata are retained.
    """
    database.execute(
        "CREATE TABLE IF NOT EXISTS playlist_history_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)"
    )
    row = database.execute(
        "SELECT sql FROM sqlite_master WHERE type='table' AND name='played_history_identities_recent'"
    ).fetchone()
    version_row = database.execute(
        "SELECT value FROM playlist_history_meta WHERE key='full_identity_normalization'"
    ).fetchone()
    needs_migration = row is not None and (version_row is None or str(version_row[0]) != "248")
    if row is None:
        database.execute(
            """CREATE TABLE played_history_identities_recent (
                artist_key TEXT NOT NULL,
                title_key TEXT NOT NULL,
                artist TEXT NOT NULL,
                title TEXT NOT NULL,
                duration_seconds INTEGER NOT NULL,
                filename TEXT NOT NULL,
                played_at REAL NOT NULL,
                PRIMARY KEY (artist_key, title_key)
            ) WITHOUT ROWID"""
        )
    elif needs_migration:
        rows = database.execute(
            "SELECT artist, title, duration_seconds, filename, played_at FROM played_history_identities_recent"
        ).fetchall()
        latest: dict[tuple[str, str], tuple[str, str, int, str, float]] = {}
        for artist, title, duration_seconds, filename, played_at in rows:
            artist_display = re.sub(r"\s+", " ", history_punctuation_fold(str(artist or ""))).strip()
            title_display = re.sub(r"\s+", " ", history_punctuation_fold(str(title or ""))).strip()
            artist_key = normalize_playlist_history_text(artist_display)
            title_key = normalize_playlist_history_text(title_display)
            if not artist_key or not title_key:
                continue
            try:
                duration = max(0, int(duration_seconds or 0)); when = float(played_at)
            except (TypeError, ValueError):
                continue
            filename_key = playlist_history_filename_key(str(filename or "")) if filename else ""
            key = (artist_key, title_key)
            previous = latest.get(key)
            if previous is None or when >= previous[4]:
                if previous is not None:
                    if duration <= 0: duration = previous[2]
                    if not filename_key: filename_key = previous[3]
                latest[key] = (artist_display, title_display, duration, filename_key, when)
            elif previous is not None:
                # Older rows can still contribute missing metadata without changing
                # the latest timestamp or display capitalization.
                if previous[2] <= 0 and duration > 0:
                    latest[key] = (previous[0], previous[1], duration, previous[3], previous[4])
                if not previous[3] and filename_key:
                    cur = latest[key]; latest[key] = (cur[0], cur[1], cur[2], filename_key, cur[4])
        database.execute("DROP TABLE IF EXISTS played_history_identities_recent_v248")
        database.execute(
            """CREATE TABLE played_history_identities_recent_v248 (
                artist_key TEXT NOT NULL, title_key TEXT NOT NULL, artist TEXT NOT NULL, title TEXT NOT NULL,
                duration_seconds INTEGER NOT NULL, filename TEXT NOT NULL, played_at REAL NOT NULL,
                PRIMARY KEY (artist_key, title_key)
            ) WITHOUT ROWID"""
        )
        if latest:
            database.executemany(
                "INSERT INTO played_history_identities_recent_v248 VALUES (?, ?, ?, ?, ?, ?, ?)",
                [(ak, tk, a, t, d, f, w) for (ak, tk), (a, t, d, f, w) in latest.items()],
            )
        database.execute("DROP TABLE played_history_identities_recent")
        database.execute("ALTER TABLE played_history_identities_recent_v248 RENAME TO played_history_identities_recent")
    database.execute(
        "INSERT INTO playlist_history_meta(key,value) VALUES('full_identity_normalization','248') "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value"
    )
    database.execute(
        "CREATE INDEX IF NOT EXISTS played_history_identities_recent_time_idx ON played_history_identities_recent(played_at)"
    )


def _ensure_playlist_visit_table(database: sqlite3.Connection) -> None:
    """Create the path-keyed launch ledger used only by shuffle avoidance."""
    database.execute(
        """CREATE TABLE IF NOT EXISTS playlist_track_visits_recent (
            path_key TEXT PRIMARY KEY NOT NULL,
            visited_at REAL NOT NULL
        ) WITHOUT ROWID"""
    )
    database.execute(
        "CREATE INDEX IF NOT EXISTS playlist_track_visits_recent_time_idx "
        "ON playlist_track_visits_recent(visited_at)"
    )


def _playlist_history_migrate_schema(database: sqlite3.Connection) -> None:
    """Migrate older history schemas to filename-first composite identity."""
    row = database.execute(
        "SELECT sql FROM sqlite_master WHERE type='table' AND name='played_tracks_recent'"
    ).fetchone()
    if row is None:
        _create_playlist_history_table(database)
        return

    columns = [
        str(info[1])
        for info in database.execute("PRAGMA table_info(played_tracks_recent)").fetchall()
    ]
    expected = ["filename", "duration_seconds", "tag", "played_at"]
    if columns == expected:
        return

    if {"filename", "duration_seconds", "tag", "played_at"}.issubset(columns):
        rows = database.execute(
            "SELECT filename, duration_seconds, tag, played_at FROM played_tracks_recent"
        ).fetchall()
        database.execute("DROP TABLE IF EXISTS played_tracks_recent_new")
        database.execute(
            """CREATE TABLE played_tracks_recent_new (
                filename TEXT NOT NULL,
                duration_seconds INTEGER NOT NULL,
                tag TEXT NOT NULL,
                played_at REAL NOT NULL,
                PRIMARY KEY (filename, duration_seconds, tag)
            ) WITHOUT ROWID"""
        )
        normalized: dict[tuple[str, int, str], float] = {}
        for filename, duration_seconds, tag, played_at in rows:
            filename_key = playlist_history_filename_key(str(filename))
            try:
                duration = int(duration_seconds)
                when = float(played_at)
            except (TypeError, ValueError):
                continue
            if not filename_key or duration <= 0 or not tag or str(tag) == "\x1f":
                continue
            key = (filename_key, duration, str(tag))
            normalized[key] = max(normalized.get(key, float("-inf")), when)
        database.executemany(
            "INSERT INTO played_tracks_recent_new(filename, duration_seconds, tag, played_at) VALUES (?, ?, ?, ?)",
            [(filename, duration, tag, when) for (filename, duration, tag), when in normalized.items()],
        )
        database.execute("DROP TABLE played_tracks_recent")
        database.execute("ALTER TABLE played_tracks_recent_new RENAME TO played_tracks_recent")
        return

    # The short-lived duration+tag-only schema cannot be losslessly converted
    # because it intentionally discarded filenames. Preserve it as a backup,
    # then start the filename-indexed table cleanly; re-importing Last.fm logs
    # will repopulate every play for which the logs contain filename evidence.
    suffix = int(time.time())
    backup = f"played_tracks_recent_backup_{suffix}"
    database.execute(f'ALTER TABLE played_tracks_recent RENAME TO "{backup}"')
    _create_playlist_history_table(database)


def _playlist_history_backfill_legacy_identities(database: sqlite3.Connection) -> int:
    """One-time conversion of this DB's own legacy rows into Artist/Song identities."""
    version = database.execute(
        "SELECT value FROM playlist_history_meta WHERE key='legacy_identity_backfill'"
    ).fetchone()
    if version is not None and str(version[0]) == "303":
        return 0
    tables = {str(row[0]) for row in database.execute(
        "SELECT name FROM sqlite_master WHERE type='table'"
    ).fetchall()}
    identities: dict[tuple[str, str], tuple[str, str, int, str, float]] = {}

    def remember(artist, title, duration, filename, played_at) -> None:
        artist_display = re.sub(r"\s+", " ", history_punctuation_fold(str(artist or ""))).strip()
        title_display = re.sub(r"\s+", " ", history_punctuation_fold(str(title or ""))).strip()
        artist_key = normalize_playlist_history_text(artist_display)
        title_key = normalize_playlist_history_text(title_display)
        if not artist_key or not title_key:
            return
        try:
            duration_value = max(0, int(duration or 0))
            when = float(played_at)
        except (TypeError, ValueError):
            return
        filename_key = playlist_history_filename_key(str(filename or "")) if filename else ""
        key = (artist_key, title_key)
        old = identities.get(key)
        if old is None or when >= old[4]:
            if old is not None:
                if duration_value <= 0:
                    duration_value = old[2]
                if not filename_key:
                    filename_key = old[3]
            identities[key] = (artist_display, title_display, duration_value, filename_key, when)
        elif old is not None:
            identities[key] = (
                old[0], old[1],
                duration_value if old[2] <= 0 < duration_value else old[2],
                filename_key if not old[3] and filename_key else old[3],
                old[4],
            )

    if "played_tracks_recent" in tables:
        for filename, duration, tag, played_at in database.execute(
            "SELECT filename,duration_seconds,tag,played_at FROM played_tracks_recent"
        ).fetchall():
            artist, separator, title = str(tag or "").partition("\x1f")
            if separator:
                remember(artist, title, duration, filename, played_at)
    if "played_tracks" in tables:
        columns = {str(row[1]) for row in database.execute("PRAGMA table_info(played_tracks)").fetchall()}
        if {"filename", "artist", "song", "played_at"}.issubset(columns):
            for filename, artist, title, played_at in database.execute(
                "SELECT filename,artist,song,played_at FROM played_tracks"
            ).fetchall():
                remember(artist, title, 0, filename, played_at)

    if identities:
        database.executemany(
            """INSERT INTO played_history_identities_recent(
                   artist_key,title_key,artist,title,duration_seconds,filename,played_at
               ) VALUES(?,?,?,?,?,?,?)
               ON CONFLICT(artist_key,title_key) DO UPDATE SET
                   artist=CASE WHEN excluded.played_at>=played_history_identities_recent.played_at THEN excluded.artist ELSE played_history_identities_recent.artist END,
                   title=CASE WHEN excluded.played_at>=played_history_identities_recent.played_at THEN excluded.title ELSE played_history_identities_recent.title END,
                   duration_seconds=CASE WHEN excluded.duration_seconds>0 THEN excluded.duration_seconds ELSE played_history_identities_recent.duration_seconds END,
                   filename=CASE WHEN excluded.filename<>'' THEN excluded.filename ELSE played_history_identities_recent.filename END,
                   played_at=MAX(played_history_identities_recent.played_at,excluded.played_at)""",
            [(ak, tk, a, t, d, f, w) for (ak, tk), (a, t, d, f, w) in identities.items()],
        )
    database.execute(
        "INSERT INTO playlist_history_meta(key,value) VALUES('legacy_identity_backfill','303') "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value"
    )
    return len(identities)


class _ClosingPlaylistHistoryConnection(sqlite3.Connection):
    """Commit/rollback like sqlite3.Connection, then release the file handle."""

    def __exit__(self, exc_type, exc_value, traceback) -> bool:
        try:
            return bool(super().__exit__(exc_type, exc_value, traceback))
        finally:
            self.close()


def playlist_history_connection() -> sqlite3.Connection:
    """Open history and transparently reunify the accidental filename fork.

    V303 serializes the one-time repair within this process. Playlist startup can
    therefore kick it to a daemon without racing the history-scoring worker or
    risking two threads trying to archive the underscore companion simultaneously.
    """
    active_path = playlist_history_database_path()
    database = sqlite3.connect(active_path, factory=_ClosingPlaylistHistoryConnection)
    database.execute("PRAGMA journal_mode=WAL")
    database.execute("PRAGMA synchronous=NORMAL")
    with _PLAYLIST_HISTORY_COMPANION_MERGE_LOCK:
        _playlist_history_migrate_schema(database)
        _ensure_playlist_full_identity_table(database)
        _ensure_playlist_visit_table(database)
        # V303 repair order is intentional: reunify the filename fork first, THEN
        # rebuild identities from the complete union. Older releases set the one-time
        # backfill marker before merging and could strand decades of Last.fm rows.
        merged_rows = merge_playlist_history_companion_databases(database, active_path=active_path)
        rebuilt_identities = _playlist_history_backfill_legacy_identities(database)
        database.commit()
        archived = archive_noncanonical_history_database_after_verified_merge(database, active_path)
        if merged_rows or rebuilt_identities or archived is not None:
            with contextlib.suppress(Exception):
                append_pafplayer_trace(
                    "history.repair.v303", path=active_path, merged_rows=merged_rows,
                    rebuilt_identities=rebuilt_identities, archived=archived or "",
                    identities=database.execute("SELECT COUNT(*) FROM played_history_identities_recent").fetchone()[0],
                    tracks=database.execute("SELECT COUNT(*) FROM played_tracks_recent").fetchone()[0],
                )
        # filename is the left-most column of the WITHOUT ROWID primary-key B-tree,
        # so both filename-only candidate lookups and exact three-part lookups use
        # the table itself; no redundant secondary index is needed.
        database.execute("DROP INDEX IF EXISTS played_tracks_recent_tag_duration_idx")
        database.execute("DROP INDEX IF EXISTS played_tracks_recent_filename_played_idx")
    return database


def load_recent_playlist_visits(
    *,
    now: float | None = None,
    recent_seconds: float = SHUFFLE_RECENT_AVOID_SECONDS,
) -> dict[str, float]:
    """Load the optional legacy launch ledger when 3-hour avoidance is enabled.

    V307 disables this policy by default.  When disabled, do no SQLite work and
    clear any in-process visit state so normal shuffle traversal is governed only
    by the prepared history order rather than an elapsed-time rejection window.
    """
    if not SHUFFLE_RECENT_AVOID_ENABLED:
        _PLAYLIST_RECENT_VISIT_CACHE.clear()
        return {}
    reference = time.time() if now is None else float(now)
    cutoff = reference - max(0.0, float(recent_seconds))
    try:
        with playlist_history_connection() as database:
            rows = database.execute(
                "SELECT path_key, visited_at FROM playlist_track_visits_recent "
                "WHERE visited_at>=?",
                (cutoff,),
            ).fetchall()
            database.execute(
                "DELETE FROM playlist_track_visits_recent WHERE visited_at<?",
                (cutoff,),
            )
    except (OSError, sqlite3.Error, TypeError, ValueError):
        rows = []
    loaded = {
        str(path_key): float(visited_at)
        for path_key, visited_at in rows
        if str(path_key)
    }
    _PLAYLIST_RECENT_VISIT_CACHE.clear()
    _PLAYLIST_RECENT_VISIT_CACHE.update(loaded)
    return dict(loaded)


def playlist_shuffle_mark_visit(
    track: Path,
    *,
    visited_at: float | None = None,
) -> bool:
    """Persist a launch only when the optional legacy recent-avoid policy is on."""
    if not SHUFFLE_RECENT_AVOID_ENABLED:
        return False
    path_key = lexical_path_key(Path(track))
    when = time.time() if visited_at is None else float(visited_at)
    _PLAYLIST_RECENT_VISIT_CACHE[path_key] = when
    try:
        with playlist_history_connection() as database:
            database.execute(
                """INSERT INTO playlist_track_visits_recent(path_key, visited_at)
                   VALUES (?, ?)
                   ON CONFLICT(path_key)
                   DO UPDATE SET visited_at=MAX(
                       playlist_track_visits_recent.visited_at,
                       excluded.visited_at
                   )""",
                (path_key, when),
            )
        append_pafplayer_trace("shuffle.visit", track=track, visited_at=when, persisted=True)
        return True
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        # The in-process invariant remains valid even if persistence is
        # temporarily unavailable.
        append_pafplayer_exception("persist shuffle visit", exc)
        append_pafplayer_trace("shuffle.visit", track=track, visited_at=when, persisted=False)
        return False


def playlist_history_mark_identity_played(
    filename: str,
    duration_seconds: int,
    tag: str,
    played_at: float | None = None,
    *,
    database: sqlite3.Connection | None = None,
) -> None:
    """Upsert one exact identity, retaining only its most recent play time."""
    filename_key = playlist_history_filename_key(filename)
    if not filename_key or duration_seconds <= 0 or not tag or tag == "\x1f":
        return
    when = time.time() if played_at is None else float(played_at)
    owns_database = database is None
    db = database or playlist_history_connection()
    try:
        db.execute(
            """INSERT INTO played_tracks_recent(filename, duration_seconds, tag, played_at)
               VALUES (?, ?, ?, ?)
               ON CONFLICT(filename, duration_seconds, tag)
               DO UPDATE SET played_at=MAX(played_tracks_recent.played_at, excluded.played_at)""",
            (filename_key, int(duration_seconds), str(tag), when),
        )
        if owns_database:
            db.commit()
    finally:
        if owns_database:
            db.close()


def playlist_history_mark_artist_title_played(
    artist: str,
    title: str,
    duration_seconds: int | float | None,
    played_at: float | None = None,
    *,
    filename: str = "",
    database: sqlite3.Connection | None = None,
) -> None:
    """Upsert one complete Artist/Song identity independently of playlist membership."""
    artist_display = re.sub(r"\s+", " ", str(artist or "")).strip()
    title_display = re.sub(r"\s+", " ", str(title or "")).strip()
    artist_key = normalize_playlist_history_text(artist_display)
    title_key = normalize_playlist_history_text(title_display)
    if not artist_key or not title_key:
        return
    try:
        duration = max(0, int(round(float(duration_seconds or 0))))
    except (TypeError, ValueError):
        duration = 0
    when = time.time() if played_at is None else float(played_at)
    filename_key = playlist_history_filename_key(filename) if filename else ""
    owns_database = database is None
    db = database or playlist_history_connection()
    try:
        db.execute(
            """INSERT INTO played_history_identities_recent(
                   artist_key, title_key, artist, title, duration_seconds, filename, played_at
               ) VALUES (?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(artist_key, title_key)
               DO UPDATE SET
                   artist=CASE WHEN excluded.played_at>=played_history_identities_recent.played_at THEN excluded.artist ELSE played_history_identities_recent.artist END,
                   title=CASE WHEN excluded.played_at>=played_history_identities_recent.played_at THEN excluded.title ELSE played_history_identities_recent.title END,
                   duration_seconds=CASE WHEN excluded.duration_seconds>0 THEN excluded.duration_seconds ELSE played_history_identities_recent.duration_seconds END,
                   filename=CASE WHEN excluded.filename<>'' THEN excluded.filename ELSE played_history_identities_recent.filename END,
                   played_at=MAX(played_history_identities_recent.played_at, excluded.played_at)""",
            (artist_key, title_key, artist_display, title_display, duration, filename_key, when),
        )
        cache_key = "\x1f".join((artist_key, title_key))
        _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE[cache_key] = max(
            _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE.get(cache_key, 0.0), when
        )
        if owns_database:
            db.commit()
    finally:
        if owns_database:
            db.close()


def playlist_history_csv_candidates() -> list[Path]:
    """Return likely generated Last.fm CSV locations without inventing duplicates."""
    candidates = [Path(__file__).resolve().with_name("lastfm_play_history.csv")]
    if os.name == "nt":
        candidates.append(Path(r"C:\bat\lastfm_play_history.csv"))
    unique: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate).casefold()
        if key not in seen:
            seen.add(key)
            unique.append(candidate)
    return unique


def playlist_history_existing_csv_path() -> Path | None:
    """Prefer the newest available generated Last.fm CSV."""
    existing: list[tuple[int, Path]] = []
    for candidate in playlist_history_csv_candidates():
        try:
            if candidate.is_file():
                existing.append((candidate.stat().st_mtime_ns, candidate))
        except OSError:
            continue
    return max(existing, default=(0, None), key=lambda item: item[0])[1]


def playlist_history_backfill_full_identities_from_csv(
    database: sqlite3.Connection,
    csv_path: Path | None = None,
) -> int:
    """Backfill canonical Artist/Song identities from the generated Last.fm CSV.

    V241 uses the same import as a real playback fallback, not merely as a
    diagnostic data source. Case and typographic quote differences collapse into
    one canonical Artist/Song identity; the newest scrobble wins.
    """
    csv_path = Path(csv_path) if csv_path is not None else playlist_history_existing_csv_path()
    if csv_path is None or not csv_path.is_file():
        return 0
    latest: dict[tuple[str, str], tuple[str, str, int, str, float]] = {}
    try:
        with csv_path.open("r", newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            fields = set(reader.fieldnames or ())
            if not {"start", "artist", "title"}.issubset(fields):
                return 0
            for row in reader:
                artist = re.sub(r"\s+", " ", history_punctuation_fold(str(row.get("artist") or ""))).strip()
                title = re.sub(r"\s+", " ", history_punctuation_fold(str(row.get("title") or ""))).strip()
                artist_key = normalize_playlist_history_text(artist)
                title_key = normalize_playlist_history_text(title)
                if not artist_key or not title_key:
                    continue
                try:
                    duration = max(0, int(round(float(row.get("duration_seconds") or 0))))
                    when = datetime.fromisoformat(str(row.get("start") or "").replace("Z", "+00:00")).timestamp()
                except (TypeError, ValueError, OverflowError, OSError):
                    continue
                key = (artist_key, title_key)
                previous = latest.get(key)
                if previous is None or when > previous[4]:
                    latest[key] = (artist, title, duration, "", when)
    except (OSError, csv.Error):
        return 0
    if latest:
        database.executemany(
            """INSERT INTO played_history_identities_recent(
                   artist_key, title_key, artist, title, duration_seconds, filename, played_at
               ) VALUES (?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(artist_key, title_key)
               DO UPDATE SET
                   artist=CASE WHEN excluded.played_at>=played_history_identities_recent.played_at THEN excluded.artist ELSE played_history_identities_recent.artist END,
                   title=CASE WHEN excluded.played_at>=played_history_identities_recent.played_at THEN excluded.title ELSE played_history_identities_recent.title END,
                   duration_seconds=CASE WHEN excluded.duration_seconds>0 THEN excluded.duration_seconds ELSE played_history_identities_recent.duration_seconds END,
                   played_at=MAX(played_history_identities_recent.played_at, excluded.played_at)""",
            [
                (artist_key, title_key, artist, title, duration, filename, when)
                for (artist_key, title_key), (artist, title, duration, filename, when) in latest.items()
            ],
        )
    return len(latest)


def schedule_playlist_history_full_identity_backfill() -> bool:
    """Refresh imported Artist/Song history without letting in-flight misses become Never.

    V301 deliberately forces one fresh identity reconciliation because older builds
    could cache a false zero while this daemon was still importing the large Last.fm
    scrape.  Playback stays non-blocking; only the *meaning* of a miss changes from
    definitive Never to unknown until this event says the source is ready.
    """
    global _PLAYLIST_FULL_HISTORY_BACKFILL_STARTED
    csv_path = playlist_history_existing_csv_path()
    if csv_path is None:
        _PLAYLIST_FULL_HISTORY_BACKFILL_READY.set()
        return False
    with _PLAYLIST_FULL_HISTORY_BACKFILL_LOCK:
        if _PLAYLIST_FULL_HISTORY_BACKFILL_STARTED:
            return False
        _PLAYLIST_FULL_HISTORY_BACKFILL_STARTED = True
        _PLAYLIST_FULL_HISTORY_BACKFILL_READY.clear()

    def worker() -> None:
        imported = 0
        try:
            stat = csv_path.stat()
            signature = f"301:{csv_path.resolve()}:{stat.st_size}:{stat.st_mtime_ns}"
            with playlist_history_connection() as database:
                existing = database.execute(
                    "SELECT value FROM playlist_history_meta WHERE key='csv_full_identity_signature'"
                ).fetchone()
                if existing is None or str(existing[0]) != signature:
                    imported = playlist_history_backfill_full_identities_from_csv(database, csv_path)
                    database.execute(
                        "INSERT INTO playlist_history_meta(key,value) VALUES('csv_full_identity_signature',?) "
                        "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                        (signature,),
                    )
                    database.commit()
                total_identities = int(database.execute("SELECT COUNT(*) FROM played_history_identities_recent").fetchone()[0])
            append_pafplayer_trace(
                "history.lastfm.backfill.ready", csv=str(csv_path), imported=int(imported),
                total_identities=total_identities, signature=signature
            )
        except (OSError, sqlite3.Error, csv.Error, TypeError, ValueError) as exc:
            append_pafplayer_exception("background Last.fm history identity import", exc)
        finally:
            # Zeros created before the reconciliation are not authoritative.
            _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE.clear()
            _PLAYLIST_HISTORY_LAST_PLAYED_CACHE.clear()
            _PLAYLIST_FULL_HISTORY_BACKFILL_READY.set()

    threading.Thread(
        target=worker,
        name="lastfm-history-identity-backfill",
        daemon=True,
    ).start()
    return True


def format_last_heard_age(seconds: float) -> str:
    """Format an elapsed age compactly for legacy/internal play-history callers."""
    seconds = max(0.0, float(seconds))
    minutes = seconds / 60.0
    if minutes < 60.0:
        return f"{max(1, round(minutes))}min"
    hours = minutes / 60.0
    if hours < 24.0:
        rounded = round(hours * 4.0) / 4.0
        return f"{rounded:g}hr"
    days = hours / 24.0
    if days < 7.0:
        rounded = round(days * 2.0) / 2.0
        return f"{rounded:g}d"
    if days < 28.0:
        rounded = round(days / 7.0 * 2.0) / 2.0
        return f"{rounded:g}w"
    if days < 365.25:
        months = max(1, round(days / 30.4375))
        return f"{months}mo" if months == 1 else f"{months}mos"
    years = days / 365.25
    rounded = round(years, 1)
    return f"{rounded:g}yr"


def format_last_heard_calendar(played_at: float, *, now_timestamp: float | None = None) -> str:
    """Format a prior-play timestamp in the compact Last play HUD vocabulary.

    Motivation: this field is a glanceable playback datum, not prose.  Recent
    ages therefore use ``1min`` / ``17min`` / ``1.7h`` and never include the word
    ``ago``.  Older values keep the weekday/calendar forms established earlier.
    """
    try:
        played_at = float(played_at)
    except (TypeError, ValueError):
        return ""
    if played_at <= 0:
        return ""
    now_value = time.time() if now_timestamp is None else float(now_timestamp)
    elapsed = max(0.0, now_value - played_at)
    elapsed_minutes = elapsed / 60.0
    if elapsed_minutes < 60.0:
        minutes = max(1, round(elapsed_minutes))
        return f"{minutes}min"
    elapsed_hours = elapsed / 3600.0
    if elapsed_hours < 60.0:
        return f"{elapsed_hours:.1f}h"
    played = time.localtime(played_at)
    current = time.localtime(now_value)
    if elapsed < 7.0 * 86400.0:
        return time.strftime("%A", played)
    month = time.strftime("%b", played)
    day = str(int(time.strftime("%d", played)))
    if played.tm_year == current.tm_year:
        return f"{month} {day}"
    return f"{month} {day} ’{played.tm_year % 100:02d}"


def display_last_played_regex(pattern: str) -> int:
    """Page every matching stored history identity, not merely active-playlist tracks."""
    try:
        matcher = re.compile(history_punctuation_fold(str(pattern)), re.IGNORECASE)
    except re.error as exc:
        print(f"ERROR: invalid history regex: {exc}", file=sys.stderr)
        return 2
    try:
        with playlist_history_connection() as database:
            # Existing v238 installations may already have the complete generated CSV
            # while their filename-first SQLite table contains only locally-identifiable
            # scrobbles. Backfill the new complete table only for this explicit audit.
            playlist_history_backfill_full_identities_from_csv(database)
            full_rows = database.execute(
                "SELECT artist, title, duration_seconds, filename, played_at "
                "FROM played_history_identities_recent"
            ).fetchall()
            legacy_rows = database.execute(
                "SELECT filename, duration_seconds, tag, played_at FROM played_tracks_recent"
            ).fetchall()
    except (OSError, sqlite3.Error) as exc:
        print(f"ERROR: could not query playlist history database: {exc}", file=sys.stderr)
        return 1

    matches: dict[tuple[str, str], tuple[float, str]] = {}
    for artist, title, duration_seconds, filename, played_at in full_rows:
        artist_text = str(artist or "")
        title_text = str(title or "")
        filename_text = str(filename or "")
        if not (
            history_search_match(pattern, matcher, artist_text)
            or history_search_match(pattern, matcher, title_text)
            or (filename_text and history_search_match(pattern, matcher, filename_text))
        ):
            continue
        try:
            timestamp = float(played_at)
            duration = max(0, int(duration_seconds))
        except (TypeError, ValueError):
            continue
        key = (
            normalize_playlist_history_text(artist_text),
            normalize_playlist_history_text(title_text),
        )
        label = f"{artist_text} — {title_text}"
        previous = matches.get(key)
        if previous is None or timestamp > previous[0]:
            matches[key] = (timestamp, label)

    # Preserve legacy filename matching and fold those rows into the same identity
    # map. These literal variables also document the old compatibility search path.
    for filename, duration_seconds, tag, played_at in legacy_rows:
        filename_text = str(filename or "")
        tag_text = str(tag or "").replace("\x1f", " ")
        if not (history_search_match(pattern, matcher, filename_text) or history_search_match(pattern, matcher, tag_text)):
            continue
        raw_tag = str(tag or "")
        artist_text, _separator, title_text = raw_tag.partition("\x1f")
        try:
            timestamp = float(played_at)
            duration = max(0, int(duration_seconds))
        except (TypeError, ValueError):
            continue
        artist_key = normalize_playlist_history_text(artist_text)
        title_key = normalize_playlist_history_text(title_text)
        if artist_key and title_key:
            key = (artist_key, title_key)
            label = f"{artist_text} — {title_text}"
        else:
            key = (playlist_history_filename_key(filename_text), "")
            label = filename_text
        previous = matches.get(key)
        if previous is None or timestamp > previous[0]:
            matches[key] = (timestamp, label)

    ordered = [(timestamp, Path(label)) for timestamp, label in matches.values()]
    ordered.sort(key=lambda item: (-item[0], natural_path_key(item[1])))
    columns = shutil.get_terminal_size((120, 30)).columns
    header, body, summary = build_playlist_analysis_table(
        ordered,
        terminal_columns=columns,
        value_header="History identity",
        summary_subject="matching history identity/identities",
    )
    summary = f"{summary}  Regex: /{pattern}/"
    page_playlist_analysis_table(header, body, summary)
    return 0


def playlist_history_runtime_key(track: Path) -> str:
    """Return the in-process path key used for background history results."""
    return lexical_path_key(track)


def prefetch_playlist_history_filename(track: Path) -> None:
    """Prefetch one track's SQLite history bucket in a daemon thread.

    Motivation: when the next playlist track is already predictable, its SQL
    lookup belongs in the background while the current song is still playing,
    not on the next track's critical startup path. Only the normalized filename
    is required; duration and Artist/Song are matched later from metadata that
    playback already needs for the HUD.
    """
    filename_key = playlist_history_filename_key(track)
    if not filename_key:
        return
    with _PLAYLIST_HISTORY_PREFETCH_LOCK:
        if (
            filename_key in _PLAYLIST_HISTORY_PREFETCH_ROWS
            or filename_key in _PLAYLIST_HISTORY_PREFETCH_INFLIGHT
        ):
            return
        _PLAYLIST_HISTORY_PREFETCH_INFLIGHT.add(filename_key)

    def worker() -> None:
        rows: list[tuple[int, str, float]] = []
        try:
            with playlist_history_connection() as database:
                fetched = database.execute(
                    "SELECT duration_seconds, tag, played_at "
                    "FROM played_tracks_recent WHERE filename=?",
                    (filename_key,),
                ).fetchall()
            rows = [
                (int(duration), str(tag), float(played_at))
                for duration, tag, played_at in fetched
            ]
        except (OSError, sqlite3.Error, TypeError, ValueError):
            rows = []
        finally:
            with _PLAYLIST_HISTORY_PREFETCH_LOCK:
                _PLAYLIST_HISTORY_PREFETCH_ROWS[filename_key] = rows
                _PLAYLIST_HISTORY_PREFETCH_INFLIGHT.discard(filename_key)

    threading.Thread(
        target=worker,
        name=f"history-prefetch-{filename_key[:32]}",
        daemon=True,
    ).start()


def _prefetched_playlist_history_last_played(
    track: Path,
    duration_seconds: float | int | None,
    tags: dict[str, str] | None,
) -> float | None:
    """Resolve a prefetched filename bucket using the v285 safe identity contract."""
    filename_key = playlist_history_filename_key(track)
    with _PLAYLIST_HISTORY_PREFETCH_LOCK:
        rows = list(_PLAYLIST_HISTORY_PREFETCH_ROWS.get(filename_key, ()))
    return playlist_history_resolve_filename_candidates(rows, duration_seconds=duration_seconds, tags=tags)



def _playlist_history_track_number_hint(track: Path) -> int | None:
    """Return a trustworthy current-track number hint without launching another probe.

    V304 uses this only to prove that an old Last.fm title was polluted with
    ``" - <album> <track>"``.  Prefer the already-cached raw metadata; fall back
    to the conventional numeric filename prefix used throughout Claire's library.
    """
    path = Path(track)
    try:
        raw = probe_audio_raw_tags(path)
    except Exception:
        raw = {}
    for key in ("track", "tracknumber", "trck"):
        value = str(raw.get(key, "") or "").strip()
        match = re.match(r"^(\d{1,3})(?:\s*/\s*\d+)?\b", value)
        if match:
            number = int(match.group(1))
            if number > 0:
                return number
    # Multi-disc prefixes such as 1-03 Song mean disc 1, track 03.
    multi = re.match(r"^\s*\d{1,2}[ _-](\d{1,3})[ _.-]+", path.name)
    if multi:
        number = int(multi.group(1))
        if number > 0:
            return number
    simple = re.match(r"^\s*(\d{1,3})[ _.-]+", path.name)
    if simple:
        number = int(simple.group(1))
        if number > 0:
            return number
    return None


def _playlist_history_polluted_suffix_matches_current_track(
    polluted_title: str,
    *,
    current_title: str,
    current_album: str,
    track_number: int | None,
) -> bool:
    """Prove one old Last.fm ``title - album track`` corruption structurally.

    This is intentionally *not* fuzzy title matching.  The historical title must
    begin with the complete current title, followed by `` - ``; the remainder
    must reduce to the complete current album plus the current track number.
    Optional literal ``track`` text and leading zeroes are tolerated because the
    old crawler emitted both forms.  Without album + track evidence we refuse to
    manufacture an alias.
    """
    if not current_title or not current_album or not track_number:
        return False
    polluted = normalize_playlist_history_text(polluted_title)
    title = normalize_playlist_history_text(current_title)
    album = normalize_playlist_history_text(current_album)
    if not polluted or not title or not album:
        return False
    prefix = title + " - "
    if not polluted.startswith(prefix):
        return False
    suffix = polluted[len(prefix):].strip()
    # The corrupted corpus contains both ``Album 10`` and ``Album track 10``.
    match = re.match(r"^(.*?)(?:\s+track)?\s+0*(\d{1,3})$", suffix)
    if not match:
        return False
    suffix_album = normalize_playlist_history_text(match.group(1))
    try:
        suffix_track = int(match.group(2))
    except (TypeError, ValueError):
        return False
    return bool(suffix_album == album and suffix_track == int(track_number))


def playlist_history_repair_polluted_lastfm_alias(
    database: sqlite3.Connection,
    track: Path,
    *,
    duration_seconds: float | int | None,
    tags: dict[str, str],
) -> float | None:
    """Repair one proven old Last.fm title-pollution alias and return its play time.

    The original historical identity is preserved as evidence.  Once a match is
    proven from current Artist/Song/Album/track-number metadata, V304 additionally
    writes the canonical Artist/Song row *and* the current filename/duration row.
    Future HUD lookups and history shuffles therefore use the repaired identity
    through their ordinary exact/filename indexes instead of repeating this path.
    """
    artist = re.sub(r"\s+", " ", history_punctuation_fold(str(tags.get("Artist", "") or ""))).strip()
    title = re.sub(r"\s+", " ", history_punctuation_fold(str(tags.get("Song", "") or ""))).strip()
    album = re.sub(r"\s+", " ", history_punctuation_fold(str(tags.get("Album", "") or ""))).strip()
    artist_key = normalize_playlist_history_text(artist)
    title_key = normalize_playlist_history_text(title)
    if not artist_key or not title_key or not album:
        return None
    track_number = _playlist_history_track_number_hint(Path(track))
    if not track_number:
        return None
    try:
        rows = database.execute(
            "SELECT title,duration_seconds,played_at FROM played_history_identities_recent "
            "WHERE artist_key=? AND duration_seconds=1 AND title_key<>?",
            (artist_key, title_key),
        ).fetchall()
    except sqlite3.Error:
        return None
    matches: list[tuple[str, float]] = []
    for historical_title, historical_duration, played_at in rows:
        try:
            when = float(played_at)
        except (TypeError, ValueError):
            continue
        if _playlist_history_polluted_suffix_matches_current_track(
            str(historical_title or ""),
            current_title=title,
            current_album=album,
            track_number=track_number,
        ):
            matches.append((str(historical_title or ""), when))
    if not matches:
        return None
    newest = max(when for _old_title, when in matches)
    filename_key = playlist_history_filename_key(Path(track))
    try:
        numeric = float(duration_seconds) if duration_seconds is not None else 0.0
        duration = max(1, int(round(numeric))) if math.isfinite(numeric) and numeric > 0 else 0
    except (TypeError, ValueError):
        duration = 0
    playlist_history_mark_artist_title_played(
        artist, title, duration, played_at=newest, filename=filename_key, database=database
    )
    if filename_key and duration > 0:
        playlist_history_mark_identity_played(
            filename_key, duration, playlist_history_tag_key(tags), played_at=newest, database=database
        )
    database.commit()
    append_pafplayer_trace(
        "history.alias-repair.v304",
        track=track,
        artist=artist,
        title=title,
        album=album,
        track_number=track_number,
        historical_titles=" | ".join(old for old, _when in matches),
        played_at=newest,
    )
    _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE["\x1f".join((artist_key, title_key))] = newest
    _PLAYLIST_HISTORY_LAST_PLAYED_CACHE.pop(playlist_history_runtime_key(Path(track)), None)
    return newest



_HISTORY_IDENTITY_TIME_UNSET = object()


def playlist_history_resolve_authoritative_loaded(
    track: Path,
    *,
    duration_seconds: float | int | None,
    tags: dict[str, str] | None,
    filename_candidates: list[tuple[int, str, float]] | tuple[tuple[int, str, float], ...] = (),
    filename_checked: bool = True,
    identity_played_at=_HISTORY_IDENTITY_TIME_UNSET,
    database: sqlite3.Connection | None = None,
    allow_alias_repair: bool = True,
) -> float | None:
    """Resolve one track's Last play from every safe identity source.

    V308 is the single final-resolution engine used by bulk shuffle scoring,
    playlist browsing, and the synchronous playback fallback.  A basename match
    is accepted only through the v285 duration/tag safety contract.  Exact
    Artist+Song history is considered independently, and the newest trustworthy
    timestamp wins.  A structured v304 Last.fm alias repair is attempted only
    after an exact Artist+Song miss.  ``None`` means *not yet authoritative*;
    ``0.0`` means every available source was checked and the track is genuinely
    Never according to the current database.
    """
    path = Path(track)
    best = 0.0
    candidates = list(filename_candidates or ())
    filename_match = playlist_history_resolve_filename_candidates(
        candidates,
        duration_seconds=duration_seconds,
        tags=tags,
    )
    if filename_match is not None:
        try:
            best = max(best, float(filename_match))
        except (TypeError, ValueError):
            pass

    tag_key = playlist_history_tag_key(tags or {}) if tags else ""
    artist_key, separator, title_key = tag_key.partition("\x1f")
    usable_identity = bool(separator and artist_key and title_key)
    exact_identity_time = identity_played_at
    identity_checked = not usable_identity

    if usable_identity and exact_identity_time is _HISTORY_IDENTITY_TIME_UNSET:
        if tag_key in _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE:
            exact_identity_time = _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE[tag_key]
            identity_checked = True
        elif database is not None:
            try:
                row = database.execute(
                    "SELECT played_at FROM played_history_identities_recent "
                    "WHERE artist_key=? AND title_key=?",
                    (artist_key, title_key),
                ).fetchone()
            except sqlite3.Error:
                row = None
            exact_identity_time = None if row is None else row[0]
            identity_checked = True
        else:
            exact_identity_time = _HISTORY_IDENTITY_TIME_UNSET

    if usable_identity and exact_identity_time is not _HISTORY_IDENTITY_TIME_UNSET:
        identity_checked = True
        if exact_identity_time is not None:
            try:
                exact_when = float(exact_identity_time)
            except (TypeError, ValueError):
                exact_when = 0.0
            if exact_when > 0.0:
                best = max(best, exact_when)
                _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE[tag_key] = exact_when
        elif allow_alias_repair and database is not None and best <= 0.0:
            repaired = playlist_history_repair_polluted_lastfm_alias(
                database,
                path,
                duration_seconds=duration_seconds,
                tags=tags or {},
            )
            if repaired is not None:
                best = max(best, float(repaired))

    # Do not publish even a positive timestamp as authoritative until every
    # available identity source for this track has been checked; the unchecked
    # source could contain a newer play.  This keeps HUD, playlist view and
    # shuffle scoring from disagreeing merely because one cache happened to be
    # warmer than another.
    all_sources_checked = bool(filename_checked and identity_checked)
    if best > 0.0 and all_sources_checked:
        return best

    # A DB/CSV reconciliation in flight, or an unqueried filename/Artist+Song
    # source on the nonblocking startup path, makes absence/provisional history
    # unknown.  Never cache that as zero.
    if not all_sources_checked or not _PLAYLIST_FULL_HISTORY_BACKFILL_READY.is_set():
        return None

    return 0.0


def playlist_history_artist_title_last_played_sync(
    tags: dict[str, str] | None,
    *,
    track: Path | None = None,
    duration_seconds: float | int | None = None,
) -> float | None:
    """Resolve exact Artist/Song history through the V308 authoritative engine."""
    if not tags:
        return None
    tag_key = playlist_history_tag_key(tags)
    artist_key, separator, title_key = tag_key.partition("\x1f")
    if not separator or not artist_key or not title_key:
        return None
    try:
        with playlist_history_connection() as database:
            row = database.execute(
                "SELECT played_at FROM played_history_identities_recent WHERE artist_key=? AND title_key=?",
                (artist_key, title_key),
            ).fetchone()
            resolved = playlist_history_resolve_authoritative_loaded(
                Path(track) if track is not None else Path(title_key),
                duration_seconds=duration_seconds,
                tags=tags,
                filename_candidates=(),
                identity_played_at=(None if row is None else row[0]),
                database=database,
                allow_alias_repair=track is not None,
            )
    except (OSError, sqlite3.Error):
        return None
    if resolved is None or float(resolved) <= 0.0:
        if resolved == 0.0:
            _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE[tag_key] = 0.0
        return None
    _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE[tag_key] = float(resolved)
    return float(resolved)




def playlist_history_last_played(
    track: Path,
    *,
    duration_seconds: float | int | None = None,
    tags: dict[str, str] | None = None,
) -> float | None:
    """Return cached/nonblocking Last-play state through the V308 resolver.

    No SQLite query is issued on the playback startup path.  Bulk shuffle scoring
    and targeted background prefetches populate the same caches consumed here.
    """
    path = Path(track)
    runtime_key = playlist_history_runtime_key(path)
    if runtime_key in _PLAYLIST_HISTORY_LAST_PLAYED_CACHE:
        return _PLAYLIST_HISTORY_LAST_PLAYED_CACHE[runtime_key]
    filename_key = playlist_history_filename_key(path)
    with _PLAYLIST_HISTORY_PREFETCH_LOCK:
        filename_checked = filename_key in _PLAYLIST_HISTORY_PREFETCH_ROWS
        candidates = list(_PLAYLIST_HISTORY_PREFETCH_ROWS.get(filename_key, ()))
    tag_key = playlist_history_tag_key(tags or {}) if tags else ""
    identity_value = (
        _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE[tag_key]
        if tag_key and tag_key in _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE
        else _HISTORY_IDENTITY_TIME_UNSET
    )
    resolved = playlist_history_resolve_authoritative_loaded(
        path,
        duration_seconds=duration_seconds,
        tags=tags,
        filename_candidates=candidates,
        filename_checked=filename_checked,
        identity_played_at=identity_value,
        database=None,
        allow_alias_repair=False,
    )
    if resolved is not None:
        _PLAYLIST_HISTORY_LAST_PLAYED_CACHE[runtime_key] = float(resolved)
    return resolved




def playlist_history_last_played_sync_candidate(track: Path) -> float | None:
    """Synchronously resolve one track with the exact V308 authoritative engine."""
    path = Path(track)
    runtime_key = playlist_history_runtime_key(path)
    if runtime_key in _PLAYLIST_HISTORY_LAST_PLAYED_CACHE:
        return float(_PLAYLIST_HISTORY_LAST_PLAYED_CACHE[runtime_key])
    filename_key = playlist_history_filename_key(path)
    try:
        duration, tags = probe_audio_metadata(path)
    except Exception:
        duration, tags = None, {}
    try:
        with playlist_history_connection() as database:
            rows = database.execute(
                "SELECT duration_seconds, tag, played_at FROM played_tracks_recent WHERE filename=?",
                (filename_key,),
            ).fetchall() if filename_key else []
            candidates = [(int(d), str(tag), float(when)) for d, tag, when in rows]
            tag_key = playlist_history_tag_key(tags or {}) if tags else ""
            artist_key, separator, title_key = tag_key.partition("\x1f")
            identity_row = None
            if separator and artist_key and title_key:
                identity_row = database.execute(
                    "SELECT played_at FROM played_history_identities_recent WHERE artist_key=? AND title_key=?",
                    (artist_key, title_key),
                ).fetchone()
            resolved = playlist_history_resolve_authoritative_loaded(
                path,
                duration_seconds=duration,
                tags=tags,
                filename_candidates=candidates,
                identity_played_at=(None if identity_row is None else identity_row[0]),
                database=database,
                allow_alias_repair=True,
            )
    except (OSError, sqlite3.Error):
        return None
    with _PLAYLIST_HISTORY_PREFETCH_LOCK:
        if filename_key:
            _PLAYLIST_HISTORY_PREFETCH_ROWS[filename_key] = list(candidates)
    if resolved is not None:
        _PLAYLIST_HISTORY_LAST_PLAYED_CACHE[runtime_key] = float(resolved)
    return resolved



def playlist_track_was_recently_played(
    track: Path,
    *,
    now: float | None = None,
    recent_seconds: float = SHUFFLE_RECENT_AVOID_SECONDS,
    allow_sync_fallback: bool = False,
) -> bool:
    """Return legacy recent-window status when that optional policy is enabled.

    V307 leaves the old 3-hour machinery available behind the top-of-file
    SHUFFLE_RECENT_AVOID_ENABLED switch, but normal playback keeps it disabled.
    """
    if not SHUFFLE_RECENT_AVOID_ENABLED:
        return False
    path = Path(track)
    earned_when = playlist_history_last_played(path)
    if earned_when is None and allow_sync_fallback:
        earned_when = playlist_history_last_played_sync_candidate(path)
    visit_when = _PLAYLIST_RECENT_VISIT_CACHE.get(lexical_path_key(path))
    known_times = [
        float(value)
        for value in (earned_when, visit_when)
        if value is not None and float(value) > 0.0
    ]
    if not known_times:
        return False
    when = max(known_times)
    reference = time.time() if now is None else float(now)
    return 0.0 <= reference - float(when) < max(0.0, float(recent_seconds))


def shuffle_candidate_avoiding_recent(
    order: list[Path],
    current_track: Path,
    proposed_track: Path,
    *,
    now: float | None = None,
    recent_seconds: float = SHUFFLE_RECENT_AVOID_SECONDS,
) -> Path:
    """Apply the optional legacy recent-window substitution policy.

    With V307's default SHUFFLE_RECENT_AVOID_ENABLED=False this is an identity
    function: the prepared shuffle order is authoritative and elapsed wall-clock
    time cannot recycle/reject tracks behind its back.
    """
    if not SHUFFLE_RECENT_AVOID_ENABLED:
        return Path(proposed_track)
    if not order:
        return Path(proposed_track)
    proposed = Path(proposed_track)
    current = Path(current_track)
    reference = time.time() if now is None else float(now)
    if not playlist_track_was_recently_played(
        proposed, now=reference, recent_seconds=recent_seconds, allow_sync_fallback=True
    ):
        append_pafplayer_trace(
            "shuffle.candidate.accept",
            current=current,
            proposed=proposed,
            reason="proposal is outside recent window",
            queue_size=len(order),
        )
        return proposed

    proposed_key = lexical_path_key(proposed)
    start_index = next(
        (index for index, entry in enumerate(order) if lexical_path_key(entry) == proposed_key),
        -1,
    )
    if start_index < 0:
        start_index = 0

    # range(len(order)) is the explicit no-infinite-loop guarantee.
    for offset in range(1, len(order) + 1):
        candidate = Path(order[(start_index + offset) % len(order)])
        if same_audio_file_identity_strict(candidate, current):
            continue
        if playlist_track_was_recently_played(
            candidate, now=reference, recent_seconds=recent_seconds, allow_sync_fallback=True
        ):
            continue
        if candidate.is_file():
            append_pafplayer_trace(
                "shuffle.candidate.replace",
                current=current,
                proposed=proposed,
                selected=candidate,
                scanned=offset,
                queue_size=len(order),
                recent_window_seconds=recent_seconds,
            )
            return candidate
    append_pafplayer_trace(
        "shuffle.candidate.fallback",
        current=current,
        proposed=proposed,
        reason="no distinct existing non-recent candidate",
        queue_size=len(order),
        recent_window_seconds=recent_seconds,
    )
    return proposed


def sanitize_playlist_resume_position(
    track: Path,
    saved_position: float,
    *,
    duration_probe=None,
) -> float:
    """Prevent a bookmark at EOF from producing an instant-complete relaunch.

    Motivation: playlist quit saves the current position.  If that bookmark lands
    in the last few seconds, the next process used to clamp it to roughly
    ``duration - 0.05`` and FFplay could exit almost immediately.  That looks like
    PAFPlayer "restarted on the same song and dropped straight back to the command
    line."  A near-EOF bookmark is not useful continuity, so restart that same song
    at 0 instead.  Ordinary mid-song bookmarks remain untouched.
    """
    position = max(0.0, float(saved_position))
    if duration_probe is None:
        duration_probe = probe_duration_seconds
    try:
        duration = duration_probe(Path(track))
        duration = float(duration) if duration is not None else 0.0
    except (OSError, TypeError, ValueError):
        duration = 0.0
    if not math.isfinite(duration) or duration <= 0.0:
        return position
    threshold = min(
        float(PLAYLIST_RESUME_NEAR_EOF_RESET_SECONDS),
        max(0.5, duration * 0.02),
    )
    if position >= max(0.0, duration - threshold):
        return 0.0
    return min(position, duration)


def playlist_history_mark_played(
    track: Path,
    *,
    duration_seconds: float | int | None = None,
    tags: dict[str, str] | None = None,
) -> bool:
    """Upsert the track's most-recent play and refresh the in-process history cache."""
    try:
        if duration_seconds is not None and tags is not None:
            filename, duration, tag = cache_playlist_history_identity(track, duration_seconds, tags)
        else:
            filename, duration, tag = playlist_history_identity(track)
        when = time.time()
        playlist_history_mark_identity_played(filename, duration, tag, played_at=when)
        if tags is not None:
            history_artist = str(tags.get("Artist", "") or "")
            history_title = str(tags.get("Song", "") or "")
        else:
            history_artist, _separator, history_title = str(tag).partition("\x1f")
        playlist_history_mark_artist_title_played(
            history_artist, history_title, duration, played_at=when, filename=filename
        )
        _PLAYLIST_HISTORY_LAST_PLAYED_CACHE[playlist_history_runtime_key(track)] = when
        with _PLAYLIST_HISTORY_PREFETCH_LOCK:
            bucket = _PLAYLIST_HISTORY_PREFETCH_ROWS.setdefault(filename, [])
            replaced = False
            for index, (stored_duration, stored_tag, stored_when) in enumerate(bucket):
                if stored_duration == duration and stored_tag == tag:
                    bucket[index] = (duration, tag, max(stored_when, when))
                    replaced = True
                    break
            if not replaced:
                bucket.append((duration, tag, when))
        append_pafplayer_trace(
            "history.play.write",
            track=track,
            filename=filename,
            duration_seconds=duration,
            played_at=when,
            success=True,
        )
        return True
    except (OSError, sqlite3.Error) as exc:
        append_pafplayer_exception("write local play history", exc)
        append_pafplayer_trace("history.play.write", track=track, success=False)
        return False



def _playlist_history_infer_filename_identity(
    filename_key: str,
    candidates: list[tuple[int, str, float]] | tuple[tuple[int, str, float], ...],
) -> tuple[str, int, str] | None:
    """Infer an unambiguous cached identity without touching the audio file.

    One filename row is authoritative for the filename-first contract. Multiple
    rows are also safe when every usable row names the same Artist/Song; format
    conversions and small duration changes commonly create exactly that shape.
    A genuine multi-identity collision returns ``None`` and earns a lazy probe.
    """
    rows = list(candidates or ())
    if not rows:
        return None
    if len(rows) == 1:
        duration, tag, _played_at = rows[0]
        return filename_key, int(duration), normalize_playlist_history_stored_tag(str(tag))
    usable_tags = {
        normalize_playlist_history_stored_tag(str(tag))
        for _duration, tag, _played_at in rows
        if playlist_history_tag_is_usable(str(tag))
    }
    if len(usable_tags) != 1:
        return None
    tag = next(iter(usable_tags))
    matching = [
        (int(duration), float(played_at))
        for duration, stored_tag, played_at in rows
        if normalize_playlist_history_stored_tag(str(stored_tag)) == tag
    ]
    duration = max(matching, key=lambda item: item[1])[0] if matching else 0
    return filename_key, duration, tag


def _playlist_history_metadata_from_identity(
    identity: tuple[str, int, str],
) -> tuple[float | None, dict[str, str]]:
    """Translate cached shuffle identity data to the authoritative resolver API."""
    _filename, duration, tag = identity
    artist, separator, title = normalize_playlist_history_stored_tag(tag).partition("\x1f")
    tags = {"Artist": artist, "Song": title} if separator and artist and title else {}
    return (float(duration) if int(duration) > 0 else None), tags


def playlist_history_scores(entries: list[Path], status_callback=None, progress_callback=None) -> list[tuple[float, Path]]:
    """Bulk-score with one SQL session and lazy, persistent metadata probes.

    V314 accepts unambiguous filename history immediately, including repeated
    rows that all identify the same Artist/Song. Only missing filename buckets
    and genuine collisions touch ffprobe. Those identities are cached by full
    path + size + mtime in temp storage, so later expired shuffle rebuilds avoid
    rereading unchanged files. The final score still runs through the shared
    V308 authoritative resolver and considers newer exact Artist/Song history.
    """
    if not entries:
        return []
    if status_callback is not None:
        status_callback(True)
    try:
        if not _PLAYLIST_FULL_HISTORY_BACKFILL_READY.is_set():
            _PLAYLIST_FULL_HISTORY_BACKFILL_READY.wait()

        paths = [Path(entry) for entry in entries]
        filename_keys = [playlist_history_filename_key(entry) for entry in paths]
        rows_by_filename: dict[str, list[tuple[int, str, float]]] = {}
        unique_filenames = sorted({key for key in filename_keys if key})
        # Query + identity preparation + final resolution are separate progress
        # stages so a cold cache never looks frozen during its small lazy subset.
        total_work = len(unique_filenames) + (2 * len(paths))
        completed_work = 0
        if progress_callback is not None:
            progress_callback(completed_work, total_work, "query")

        with playlist_history_connection() as database:
            for offset in range(0, len(unique_filenames), 900):
                batch = unique_filenames[offset:offset + 900]
                if not batch:
                    continue
                placeholders = ",".join("?" for _ in batch)
                rows = database.execute(
                    "SELECT filename, duration_seconds, tag, played_at "
                    f"FROM played_tracks_recent WHERE filename IN ({placeholders})",
                    batch,
                ).fetchall()
                for filename, duration_seconds, tag, played_at in rows:
                    rows_by_filename.setdefault(str(filename), []).append(
                        (int(duration_seconds), str(tag), float(played_at))
                    )
                completed_work += len(batch)
                if progress_callback is not None:
                    progress_callback(completed_work, total_work, "query")

            with _PLAYLIST_HISTORY_PREFETCH_LOCK:
                for filename_key in unique_filenames:
                    _PLAYLIST_HISTORY_PREFETCH_ROWS[filename_key] = list(
                        rows_by_filename.get(filename_key, ())
                    )

            metadata_by_runtime: dict[str, tuple[float | None, dict[str, str]]] = {}
            identities: list[tuple[str, str]] = []
            for entry, filename_key in zip(paths, filename_keys):
                candidates = rows_by_filename.get(filename_key, ())
                identity = _playlist_history_infer_filename_identity(filename_key, candidates)
                if identity is None:
                    try:
                        duration, tags = playlist_shuffle_cached_metadata(entry)
                    except Exception:
                        duration, tags = None, {}
                else:
                    duration, tags = _playlist_history_metadata_from_identity(identity)
                metadata_by_runtime[playlist_history_runtime_key(entry)] = (duration, dict(tags))
                tag_key = playlist_history_tag_key(tags) if tags else ""
                artist_key, separator, title_key = tag_key.partition("\x1f")
                if separator and artist_key and title_key:
                    identities.append((artist_key, title_key))
                completed_work += 1
                if progress_callback is not None:
                    progress_callback(completed_work, total_work, "metadata")

            identity_times: dict[tuple[str, str], float] = {}
            unique_identities = list(dict.fromkeys(identities))
            scored: list[tuple[float, Path]] = []
            for offset in range(0, len(unique_identities), 300):
                batch = unique_identities[offset:offset + 300]
                if not batch:
                    continue
                where = " OR ".join("(artist_key=? AND title_key=?)" for _ in batch)
                params = [part for pair in batch for part in pair]
                for artist_key, title_key, played_at in database.execute(
                    "SELECT artist_key,title_key,played_at FROM played_history_identities_recent WHERE " + where,
                    params,
                ).fetchall():
                    key = (str(artist_key), str(title_key))
                    identity_times[key] = max(identity_times.get(key, 0.0), float(played_at))
                    _PLAYLIST_FULL_IDENTITY_LAST_PLAYED_CACHE["\x1f".join(key)] = identity_times[key]

            for entry, filename_key in zip(paths, filename_keys):
                duration, tags = metadata_by_runtime[playlist_history_runtime_key(entry)]
                tag_key = playlist_history_tag_key(tags or {}) if tags else ""
                artist_key, separator, title_key = tag_key.partition("\x1f")
                identity_value = (
                    identity_times.get((artist_key, title_key))
                    if separator and artist_key and title_key
                    else _HISTORY_IDENTITY_TIME_UNSET
                )
                # For a usable exact identity, ``dict.get`` returning None means
                # the batched query definitively found no row; that distinction
                # enables structured alias repair.  With no usable identity we
                # leave the source unset and let filename evidence stand alone.
                if separator and artist_key and title_key and (artist_key, title_key) not in identity_times:
                    identity_value = None
                resolved = playlist_history_resolve_authoritative_loaded(
                    entry,
                    duration_seconds=duration,
                    tags=tags,
                    filename_candidates=rows_by_filename.get(filename_key, ()),
                    identity_played_at=identity_value,
                    database=database,
                    allow_alias_repair=True,
                )
                # Backfill readiness was awaited above, so None here means an IO/
                # metadata uncertainty rather than Never.  Do not poison the
                # shared cache; score it as Never only for this one ordering pass
                # if no better identity is possible.  Normal files resolve 0.0.
                score = 0.0 if resolved is None else float(resolved)
                scored.append((score, entry))
                if resolved is not None:
                    _PLAYLIST_HISTORY_LAST_PLAYED_CACHE[playlist_history_runtime_key(entry)] = float(resolved)
                completed_work += 1
                if progress_callback is not None:
                    progress_callback(completed_work, total_work, "resolve")
        save_playlist_shuffle_metadata_cache()
        return scored
    finally:
        if status_callback is not None:
            status_callback(False)



def history_decile_shuffle_from_scores(scored: list[tuple[float, Path]], preferred_first: Path | None = None) -> list[Path]:
    """Shuffle Never as bucket 0, then ten oldest→newest known-play deciles.

    V307 deliberately removes Never from the population used to calculate the ten
    historical deciles.  Every unknown/never-played track is randomized together
    first; only positive timestamps are then ranked and split into ten equal
    populations.  Thus the newest known plays remain in the newest known-history
    decile regardless of how many Never entries the playlist contains.
    """
    if not scored:
        return []
    never: list[Path] = []
    known: list[tuple[float, Path]] = []
    for played_at, entry in scored:
        when = float(played_at)
        if when <= 0.0:
            never.append(Path(entry))
        else:
            known.append((when, Path(entry)))

    # Shuffle before sorting so equal known timestamps do not inherit playlist
    # source order; Python's stable sort then preserves that randomized tie order.
    random.shuffle(never)
    random.shuffle(known)
    known.sort(key=lambda item: item[0])

    order: list[Path] = list(never)
    total_known = len(known)
    for decile in range(10):
        start = total_known * decile // 10
        end = total_known * (decile + 1) // 10
        if end <= start:
            continue
        bucket = [entry for _played_at, entry in known[start:end]]
        random.shuffle(bucket)
        order.extend(bucket)

    if preferred_first is not None:
        key = lexical_path_key(Path(preferred_first))
        index = next((i for i, item in enumerate(order) if lexical_path_key(item) == key), -1)
        if index > 0:
            order[0], order[index] = order[index], order[0]
    return order


def choose_least_recent_playlist_track(
    entries: list[Path], status_callback=None,
) -> Path:
    """Choose randomly from the 15% played longest ago (or never played)."""
    if not entries:
        raise ValueError("Cannot choose from an empty playlist")
    try:
        scored = playlist_history_scores(entries, status_callback)
        scored.sort(key=lambda item: item[0])
        oldest_count = max(1, math.ceil(len(scored) * 0.15))
        cutoff = scored[oldest_count - 1][0]
        return random.choice([entry for played_at, entry in scored if played_at <= cutoff])
    except sqlite3.Error:
        return random.choice(entries)


def build_playlist_shuffle_order(entries: list[Path], status_callback=None) -> list[Path]:
    """Build Never bucket 0 followed by ten known-history deciles."""
    if not entries: return []
    try: scored=playlist_history_scores(entries,status_callback)
    except sqlite3.Error:
        order=list(entries); random.shuffle(order); return order
    return history_decile_shuffle_from_scores(scored)


def build_playlist_shuffle_order_progressive(entries: list[Path], progress_callback=None) -> list[Path]:
    """Score once while presenting ten lightweight progress bands."""
    if not entries:
        if progress_callback is not None: progress_callback("historical shuffling done")
        return []
    last_band = [-1]

    def report_scoring_progress(completed: int, total: int, _stage: str) -> None:
        if progress_callback is None:
            return
        percent = 100 if total <= 0 else min(99, max(0, int(completed) * 100 // int(total)))
        band = min(9, percent // 10)
        if band != last_band[0]:
            last_band[0] = band
            progress_callback(f"shuffling {band * 10}%–{(band + 1) * 10}%")

    try:
        scored = playlist_history_scores(entries, progress_callback=report_scoring_progress)
    except sqlite3.Error:
        order=list(entries); random.shuffle(order)
        if progress_callback is not None: progress_callback("historical shuffling done")
        return order
    order=history_decile_shuffle_from_scores(scored)
    if progress_callback is not None: progress_callback("historical shuffling done")
    return order



def playlist_shuffle_cache_path(playlist_path: Path) -> Path:
    """Return the per-playlist temporary cache file for the completed shuffle order."""
    identity = str(playlist_path.resolve()).casefold().encode("utf-8")
    digest = hashlib.sha256(identity).hexdigest()[:32]
    return Path(tempfile.gettempdir()) / "play_audio_file" / "shuffle_cache" / f"{digest}.json"


def load_playlist_shuffle_cache(
    playlist_path: Path,
    expiration_hours: float,
) -> tuple[list[Path], list[Path]] | None:
    """Load a fresh completed shuffle, invalidating it if age or playlist metadata changed."""
    if expiration_hours <= 0:
        return None
    cache_path = playlist_shuffle_cache_path(playlist_path)
    try:
        playlist_stat = playlist_path.stat()
        payload = json.loads(cache_path.read_text(encoding="utf-8"))
        created_at = float(payload["created_at"])
        if payload.get("shuffle_algorithm") != PLAYLIST_SHUFFLE_ALGORITHM_ID:
            return None
        if time.time() - created_at > expiration_hours * 3600.0:
            return None
        if int(payload.get("playlist_mtime_ns", -1)) != int(playlist_stat.st_mtime_ns):
            return None
        if int(payload.get("playlist_size", -1)) != int(playlist_stat.st_size):
            return None
        entries = [Path(value) for value in payload["entries"]]
        order = [Path(value) for value in payload["order"]]
        # Older cache files carried a snapshot of last-played timestamps.  That
        # snapshot can remain valid for five hours while another PAFPlayer run or
        # playlist records a newer play, so treating it as authoritative defeats
        # the recent-repeat guard.  History now comes from the live SQLite query/
        # prefetch path; ignore the legacy payload even when it is present.
        if not entries or not order:
            return None
        # The playlist file is unchanged, but individual media files can still
        # disappear.  Filter them out rather than reviving dead cache entries.
        # Avoid 50k+ eager stat/resolve operations when loading a huge cached
        # queue. Dead entries are skipped lazily when selected for playback.
        if len(entries) <= PLAYLIST_EAGER_EXISTENCE_CHECK_LIMIT:
            entry_keys = {lexical_path_key(entry) for entry in entries if entry.is_file()}
            entries = [entry for entry in entries if lexical_path_key(entry) in entry_keys]
            order = [entry for entry in order if lexical_path_key(entry) in entry_keys]
            if not entries or not order:
                return None
        return entries, order
    except (OSError, ValueError, TypeError, KeyError, json.JSONDecodeError):
        return None


def save_playlist_shuffle_cache(
    playlist_path: Path,
    entries: list[Path],
    order: list[Path],
    *,
    created_at: float | None = None,
) -> None:
    """Atomically cache the fully prepared internal playlist shuffle in the temp directory."""
    if not entries or not order:
        return
    cache_path = playlist_shuffle_cache_path(playlist_path)
    try:
        playlist_stat = playlist_path.stat()
        payload = {
            "created_at": time.time() if created_at is None else float(created_at),
            "playlist": str(playlist_path.resolve()),
            "playlist_mtime_ns": int(playlist_stat.st_mtime_ns),
            "playlist_size": int(playlist_stat.st_size),
            "shuffle_algorithm": PLAYLIST_SHUFFLE_ALGORITHM_ID,
            "entries": [str(entry) for entry in entries],
            "order": [str(entry) for entry in order],
        }
        cache_path.parent.mkdir(parents=True, exist_ok=True)
        temporary = cache_path.with_suffix(cache_path.suffix + ".tmp")
        temporary.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
        os.replace(temporary, cache_path)
    except OSError:
        return



class PlaylistShuffleCacheAsyncWriter:
    """Serialize latest-wins cache writes without blocking track transitions.

    A large playlist cache can be several megabytes of JSON. V26 rewrote that file
    synchronously between tracks, which made the next FFplay launch wait on JSON
    serialization + disk I/O. This worker snapshots the queue immediately, then writes
    it on one daemon thread. If several tracks are skipped quickly, only the newest
    pending snapshot matters; writes can never race out of order.
    """

    def __init__(self, playlist_path: Path) -> None:
        self.playlist_path = playlist_path
        self._lock = threading.Lock()
        self._event = threading.Event()
        self._pending: tuple[list[Path], list[Path], float | None] | None = None
        self._written_generation = 0
        self._scheduled_generation = 0
        self._thread = threading.Thread(
            target=self._worker,
            name="playlist-cache-writer",
            daemon=True,
        )
        self._thread.start()

    def schedule(
        self,
        entries: list[Path],
        order: list[Path],
        *,
        created_at: float | None,
    ) -> int:
        snapshot = (list(entries), list(order), created_at)
        with self._lock:
            self._scheduled_generation += 1
            generation = self._scheduled_generation
            self._pending = snapshot
        self._event.set()
        return generation

    def _worker(self) -> None:
        while True:
            self._event.wait()
            # Give the newly-selected track time to launch before serializing a
            # potentially huge playlist JSON. Additional schedules during this
            # grace period simply replace _pending with the newest queue state.
            time.sleep(max(0.0, SHUFFLE_CACHE_ASYNC_WRITE_DELAY_SECONDS))
            while True:
                with self._lock:
                    pending = self._pending
                    generation = self._scheduled_generation
                    self._pending = None
                    self._event.clear()
                if pending is None:
                    break
                entries, order, created_at = pending
                save_playlist_shuffle_cache(
                    self.playlist_path, entries, order, created_at=created_at
                )
                with self._lock:
                    self._written_generation = max(self._written_generation, generation)
                    # If a newer snapshot arrived while this one was being written,
                    # loop immediately and write only the latest pending state.
                    if self._pending is not None:
                        self._event.set()
                        continue
                break

    def wait_for_generation(self, generation: int, timeout: float = 1.0) -> bool:
        """Testing/shutdown helper; normal track changes never call this."""
        deadline = time.monotonic() + max(0.0, timeout)
        while time.monotonic() < deadline:
            with self._lock:
                if self._written_generation >= generation:
                    return True
            time.sleep(0.005)
        with self._lock:
            return self._written_generation >= generation


def playlist_shuffle_cache_created_at(playlist_path: Path) -> float | None:
    """Return the original shuffle-generation time without refreshing its expiry."""
    try:
        payload = json.loads(playlist_shuffle_cache_path(playlist_path).read_text(encoding="utf-8"))
        return float(payload.get("created_at"))
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return None


def delete_playlist_shuffle_cache(playlist_path: Path) -> None:
    """Remove the persistent shuffled queue so the next preparation must rebuild it."""
    with contextlib.suppress(OSError):
        playlist_shuffle_cache_path(playlist_path).unlink()


def playlist_source_signature(playlist_path: Path) -> tuple[int, int] | None:
    """Cheap signature for the active file-backed playlist watcher."""
    try:
        stat=Path(playlist_path).stat()
        return int(stat.st_mtime_ns), int(stat.st_size)
    except OSError:
        return None


def _playlist_slot_index(order: list[Path], track: Path) -> int:
    """Find one queue slot for track, preferring exact lexical spelling; never collapse duplicates."""
    key = lexical_path_key(track)
    for index, entry in enumerate(order):
        if lexical_path_key(entry) == key:
            return index
    for index, entry in enumerate(order):
        if same_audio_file_identity(entry, track):
            return index
    return -1


def rotate_playlist_queue_after_play(order: list[Path], played_track: Path) -> list[Path]:
    """Move exactly one departed playlist slot to the tail; queue length is invariant."""
    result = list(order)
    if not result:
        return result
    index = _playlist_slot_index(result, Path(played_track))
    if index < 0:
        return result
    slot = result.pop(index)
    result.append(slot)
    return result


def rotate_playlist_queue_to_front(order: list[Path], track: Path) -> list[Path]:
    """Rotate an N-slot queue around exactly one matching slot, preserving duplicate slots."""
    result = list(order)
    index = _playlist_slot_index(result, Path(track))
    if index < 0:
        return result
    return result[index:] + result[:index]


def move_playlist_track_to_front_preserving_order(order: list[Path], track: Path) -> list[Path]:
    """Promote exactly one matching slot while preserving every other slot and its order."""
    result = list(order)
    index = _playlist_slot_index(result, Path(track))
    if index < 0:
        return result
    slot = result.pop(index)
    return [slot] + result


def playlist_resume_successor(order: list[Path], current_track: Path) -> Path | None:
    """Return the literal next queue slot; duplicate physical files are legitimate entries."""
    if len(order) < 2:
        return Path(order[0]) if order else None
    index = _playlist_slot_index(list(order), Path(current_track))
    if index < 0:
        return Path(order[0])
    return Path(order[(index + 1) % len(order)])


def same_audio_file_identity_strict(
    left: Path | str | os.PathLike[str],
    right: Path | str | os.PathLike[str],
) -> bool:
    """Return physical identity without the basename shortcut used by bulk queue code.

    Legacy diagnostic identity helper retained for historical anti-repeat tests.
    V309+ live playlist playback intentionally does not call this function because
    duplicate physical files can represent distinct literal playlist slots.
    """
    if lexical_path_key(left) == lexical_path_key(right):
        return True
    try:
        return os.path.samefile(os.fspath(left), os.fspath(right))
    except (OSError, ValueError, TypeError):
        return False


def force_distinct_forward_playlist_candidate(
    order: list[Path],
    previous_track: Path,
    proposed_track: Path,
) -> Path:
    """LEGACY V89 diagnostic helper; V309 live playlist playback must not call this.

    Historically this guaranteed that a forward transition could not relaunch the
    just-played physical file. Under V309's literal-slot queue contract, duplicate
    slots are intentional and this behavior would be destructive if used live.

    Motivation: resume + background historical shuffling has accumulated several
    layers of queue/history protection, but the user has still observed `>` landing
    on the same song.  This helper is the intentionally boring last word: if the
    proposed forward candidate is physically the same file as the track we just
    played, find that candidate/current occurrence in the active order and walk
    forward again — "next-next" — skipping every duplicate/alias of the previous
    physical file until a genuinely different existing audio file is found.

    It is designed for the final playback boundary, not shuffle construction.
    Therefore one or a few `is_file()` checks are acceptable; it never stats the
    entire order unless the playlist is pathological and contains only duplicates.
    If no distinct existing entry can be found, the original proposal is returned
    because there is no legal alternative to launch.
    """
    previous = Path(previous_track)
    proposed = Path(proposed_track)
    if not same_audio_file_identity_strict(proposed, previous):
        return proposed
    if not order:
        return proposed

    # Prefer the exact proposed representation as the anchor.  If a stale alias
    # means it is absent, anchor at any representation of the previous physical
    # file.  If neither is present, scan from the beginning.
    proposed_key = lexical_path_key(proposed)
    start_index = next(
        (
            index for index, entry in enumerate(order)
            if lexical_path_key(entry) == proposed_key
        ),
        -1,
    )
    if start_index < 0:
        start_index = next(
            (
                index for index, entry in enumerate(order)
                if same_audio_file_identity_strict(entry, previous)
            ),
            -1,
        )

    for step in range(1, len(order) + 1):
        index = (
            (start_index + step) % len(order)
            if start_index >= 0
            else step - 1
        )
        candidate = Path(order[index])
        if same_audio_file_identity_strict(candidate, previous):
            continue
        if candidate.is_file():
            return candidate

    return proposed


def playlist_queue_neighbor_distinct(
    order: list[Path], current_track: Path, direction: int
) -> Path | None:
    """Return the literal adjacent existing queue slot, even if it names the same physical file."""
    if not order:
        return None
    step = -1 if direction < 0 else 1
    index = _playlist_slot_index(list(order), Path(current_track))
    if index < 0:
        index = 0 if step < 0 else -1
    for distance in range(1, len(order) + 1):
        candidate = Path(order[(index + step * distance) % len(order)])
        if candidate.is_file():
            return candidate
    return None


def audio_navigation_root(directory: Path) -> Path:
    """Prefer the surrounding MUSIC/MP3 library; otherwise use the parent."""
    for candidate in (directory, *directory.parents):
        if candidate.name.casefold() in {"music", "mp3"}:
            return candidate
    return directory.parent


def advance_playlist_visit_history(
    history: list[Path],
    cursor: int,
    result: str,
    queue_neighbor,
) -> tuple[Path, int]:
    """Navigate visit history while preserving literal playlist-slot semantics."""
    if not history:
        first = queue_neighbor(0)
        history.append(first)
        return first, 0
    if result == PREVIOUS_FILE:
        if cursor > 0:
            cursor -= 1
            return history[cursor], cursor
        previous_track = queue_neighbor(-1)
        history.insert(0, previous_track)
        return previous_track, 0
    if result in {NEXT_FILE, "completed"} and cursor + 1 < len(history):
        cursor += 1
        return history[cursor], cursor
    next_track = queue_neighbor(1)
    if cursor + 1 < len(history):
        del history[cursor + 1:]
    history.append(next_track)
    return next_track, len(history) - 1


def navigate_audio_path(current_path: Path, action: str) -> Path:
    """Resolve one wrapping file or audio-directory navigation action."""
    current_path = current_path.resolve()
    current_directory = current_path.parent
    direction = -1 if action in {PREVIOUS_FILE, PREVIOUS_DIRECTORY} else 1
    if action in {PREVIOUS_FILE, NEXT_FILE}:
        files = audio_files_in(current_directory)
        if not files:
            return current_path
        try:
            current_index = files.index(current_path)
        except ValueError:
            current_index = 0
        return files[(current_index + direction) % len(files)]

    root = audio_navigation_root(current_directory).resolve()

    def children(directory: Path) -> list[Path]:
        try:
            return sorted(
                (path.resolve() for path in directory.iterdir() if path.is_dir()),
                key=natural_path_key,
            )
        except OSError:
            return []

    def adjacent(directory: Path) -> Path | None:
        if direction > 0:
            nested = children(directory)
            if nested:
                return nested[0]
        cursor = directory
        while cursor != root and root in cursor.parents:
            siblings = children(cursor.parent)
            try:
                index = siblings.index(cursor)
            except ValueError:
                index = -1
            target_index = index + direction
            if 0 <= target_index < len(siblings):
                target = siblings[target_index]
                if direction < 0:
                    while children(target):
                        target = children(target)[-1]
                return target
            cursor = cursor.parent
        if directory == root:
            return None
        wrapped = root
        nested = children(wrapped)
        if direction > 0:
            return nested[0] if nested else root
        while nested:
            wrapped = nested[-1]
            nested = children(wrapped)
        return wrapped

    candidate = adjacent(current_directory)
    deadline = time.monotonic() + 4.0
    while candidate is not None and time.monotonic() < deadline:
        files = audio_files_in(candidate)
        if files:
            return files[-1 if direction < 0 else 0]
        candidate = adjacent(candidate)
    return current_path


def ffplay_executable() -> Path:
    """Locate FFplay, which performs the actual audio decoding and output."""
    discovered = shutil.which("ffplay")
    if not discovered:
        raise RuntimeError(
            "ffplay was not found in PATH.\n" + tool_install_instructions("ffmpeg")
        )
    return Path(discovered)


def direct_ffmpeg_executable() -> Path | None:
    """Return a native ffmpeg executable, refusing BAT/CMD wrappers on Windows."""
    discovered = shutil.which("ffmpeg")
    if os.name != "nt":
        return Path(discovered) if discovered else None
    candidates: list[Path] = []
    if discovered:
        found = Path(discovered)
        if found.suffix.casefold() == ".exe":
            return found
        candidates.extend((found.with_name("ffmpeg.exe"), found.parent / "ffmpeg.exe"))
    for raw_directory in os.environ.get("PATH", "").split(os.pathsep):
        directory = raw_directory.strip().strip('"')
        if directory:
            candidates.append(Path(directory) / "ffmpeg.exe")
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate).casefold()
        if key in seen:
            continue
        seen.add(key)
        try:
            if candidate.is_file():
                return candidate
        except OSError:
            continue
    return None


def tool_install_instructions(tool: str) -> str:
    """Return Winget installation and Desktop App Installer recovery steps."""
    commands = {
        "ffmpeg": "winget install -e --id Gyan.FFmpeg",
        "chafa": "winget install -e --id hpjansson.Chafa",
    }
    install = commands[tool.casefold()]
    return (
        f"Install {tool}: {install}\n"
        "If winget is unavailable, install/register it with:\n"
        'powershell -Command "Add-AppxPackage -RegisterByFamilyName -MainPackage '
        'Microsoft.DesktopAppInstaller_8wekyb3d8bbwe"\n'
        "If that does not work, try:\n"
        'powershell -Command "Add-AppxPackage -Path \\\"https://aka.ms/getwinget\\\""'
    )


def ffprobe_executable() -> Path | None:
    """Locate optional FFprobe for duration and metadata inspection."""
    discovered = shutil.which("ffprobe")
    return Path(discovered) if discovered else None


def _audio_metadata_cache_location(audio_path: Path) -> tuple[str, int, int] | None:
    try:
        stat = audio_path.stat()
        return str(audio_path.resolve()).casefold(), stat.st_size, stat.st_mtime_ns
    except OSError:
        return None


def _id3_synchsafe_int(raw: bytes) -> int:
    """Decode a four-byte ID3 synchsafe integer."""
    if len(raw) != 4:
        return 0
    return (
        ((raw[0] & 0x7F) << 21)
        | ((raw[1] & 0x7F) << 14)
        | ((raw[2] & 0x7F) << 7)
        | (raw[3] & 0x7F)
    )


def _swap_adjacent_bytes(raw: bytes) -> bytes:
    """Undo the pair-swapped byte damage seen in some malformed ID3 text."""
    swapped = bytearray()
    for index in range(0, len(raw), 2):
        pair = raw[index:index + 2]
        swapped.extend(pair[::-1] if len(pair) == 2 else pair)
    return bytes(swapped)


def _clean_recovered_id3_text(text: str) -> str:
    """Strip NULs/BOM debris while preserving normal Unicode text."""
    return text.replace("\ufeff", "").replace("\x00", "").strip()


def _decode_id3_text_payload(payload: bytes) -> str:
    """Decode normal ID3 text plus the broken UTF-8/BOM/pair-swapped variant.

    A few damaged files in this library declare encoding 3 (UTF-8), then place a
    UTF-16 BOM in front of bytes whose adjacent pairs were swapped.  Standards-
    compliant readers quite reasonably discard those frames.  Recover that exact
    signature before falling back to the normal ID3 text encodings.
    """
    if not payload:
        return ""
    encoding = payload[0]
    raw = payload[1:]

    if encoding == 3 and raw.startswith((b"\xff\xfe", b"\xfe\xff")):
        damaged = raw[2:]
        candidate = _swap_adjacent_bytes(damaged)
        for codec in ("utf-8", "cp1252", "latin1"):
            try:
                recovered = _clean_recovered_id3_text(candidate.decode(codec))
            except UnicodeDecodeError:
                continue
            if recovered and sum(character.isprintable() for character in recovered) >= max(1, len(recovered) - 1):
                return recovered

    codec = {0: "latin1", 1: "utf-16", 2: "utf-16-be", 3: "utf-8"}.get(encoding)
    if codec is None:
        return ""
    try:
        return _clean_recovered_id3_text(raw.decode(codec, errors="replace"))
    except (LookupError, UnicodeError):
        return ""


def _recover_raw_id3_display_tags(audio_path: Path) -> dict[str, str]:
    """Best-effort raw ID3 recovery for MP3s rejected by normal tag readers.

    This is deliberately conservative: recovered values only fill otherwise-empty
    display fields.  It never overwrites a valid ffprobe tag and it does not infer
    Artist or Album from directory names.
    """
    if audio_path.suffix.casefold() != ".mp3":
        return {}
    try:
        with audio_path.open("rb") as handle:
            header = handle.read(10)
            if len(header) != 10 or header[:3] != b"ID3":
                return {}
            major = header[3]
            if major not in {3, 4}:
                return {}
            tag_size = _id3_synchsafe_int(header[6:10])
            if tag_size <= 0 or tag_size > 64 * 1024 * 1024:
                return {}
            body = handle.read(tag_size)
    except OSError:
        return {}

    # Skip an extended header when present.  This is uncommon here, but keeping
    # the raw reader standards-aware prevents false frame IDs on healthy files.
    position = 0
    if header[5] & 0x40 and len(body) >= 4:
        if major == 3:
            extended_size = int.from_bytes(body[:4], "big", signed=False)
            position = min(len(body), 4 + max(0, extended_size))
        else:
            extended_size = _id3_synchsafe_int(body[:4])
            position = min(len(body), max(4, extended_size))

    recovered: dict[str, str] = {}
    frame_map = {
        "TIT2": "Song",
        "TPE1": "Artist",
        "TPE2": "Artist",  # album artist is better than nothing if TPE1 is absent
        "TALB": "Album",
        "TCON": "Genre",
        "TOPE": "Original artist",
        "TCOM": "Composer",
        "TDRC": "Year",
        "TYER": "Year",
    }
    while position + 10 <= len(body):
        frame_header = body[position:position + 10]
        frame_id_bytes = frame_header[:4]
        if frame_id_bytes == b"\x00\x00\x00\x00":
            break
        try:
            frame_id = frame_id_bytes.decode("ascii")
        except UnicodeDecodeError:
            break
        if not re.fullmatch(r"[A-Z0-9]{4}", frame_id):
            break
        frame_size = (
            int.from_bytes(frame_header[4:8], "big", signed=False)
            if major == 3 else _id3_synchsafe_int(frame_header[4:8])
        )
        if frame_size <= 0 or position + 10 + frame_size > len(body):
            break
        payload = body[position + 10:position + 10 + frame_size]
        field = frame_map.get(frame_id)
        if field and field not in recovered:
            value = _decode_id3_text_payload(payload)
            if field == "Year":
                match = re.search(r"\b(?:19|20)\d{2}\b", value)
                value = match.group(0) if match else value[:4]
            if value:
                recovered[field] = value
        elif frame_id == "COMM" and "Comment" not in recovered and len(payload) > 4:
            # COMM = encoding byte + three-byte language + description + text.
            encoding = payload[0]
            rest = payload[4:]
            delimiter = b"\x00\x00" if encoding in {1, 2} else b"\x00"
            split_at = rest.find(delimiter)
            text_payload = bytes([encoding]) + (rest[split_at + len(delimiter):] if split_at >= 0 else rest)
            value = _decode_id3_text_payload(text_payload)
            if value:
                recovered["Comment"] = value
        elif frame_id in {"WOAR", "WOAF", "WOAS", "WORS", "WPUB"} and "URL" not in recovered:
            value = payload.decode("latin1", errors="replace").strip("\x00 \t\r\n")
            if re.match(r"https?://", value, flags=re.I):
                recovered["URL"] = value
        position += 10 + frame_size
    return recovered


def _fallback_song_title_from_filename(audio_path: Path) -> str:
    """Turn a filename such as ``19_Scott.mp3`` into a safe title fallback."""
    stem = audio_path.stem.strip()
    # Only strip a leading number when it is visibly a track prefix.  A song
    # genuinely named ``1984.mp3`` therefore remains ``1984``.
    title = re.sub(r"^\s*\d{1,3}\s*[-_.]+\s*", "", stem, count=1)
    title = re.sub(r"_+", " ", title).strip()
    return title or stem



@dataclass(frozen=True)
class ReplayGainInfo:
    """Carry one track visit's fully-resolved ReplayGain decision.

    Motivation: PAFPlayer restarts FFplay for seeking, speed, balance, channel
    layout, volume, and pause/resume transitions.  If ReplayGain were re-read or
    re-selected during each restart, a tag-cache race or format-specific probe
    difference could make one continuous visit jump in loudness.  This immutable
    object is therefore calculated once near track startup and passed unchanged
    into every reconstructed FFplay command.  ``requested_db`` is the tag's
    requested normalization; ``applied_db`` is the mathematically peak-limited
    value actually used by playback; ``source`` records whether track or album
    metadata won the configured preference/fallback rule.
    """

    enabled: bool
    mode: str
    source: str | None
    requested_db: float | None
    peak: float | None
    applied_db: float | None
    clipping_prevented: bool


def _normalize_replaygain_tag_key(key: object) -> str | None:
    """Map ffprobe/Mutagen key spellings onto the four supported RG names.

    Motivation: ReplayGain tags travel through several container/tag systems.
    Vorbis comments commonly expose ``replaygain_track_gain`` directly, ID3 uses
    keys such as ``TXXX:REPLAYGAIN_TRACK_GAIN``, and MP4 freeform atoms can look
    like ``----:com.apple.iTunes:replaygain_track_gain``.  Matching the final
    standard textual name case-insensitively lets the playback math stay format
    agnostic without treating unrelated MP3Gain undo metadata as ReplayGain.
    """

    folded = str(key or "").strip().casefold()
    for wanted in REPLAYGAIN_TAG_KEYS:
        if folded == wanted or folded.endswith(":" + wanted):
            return wanted
    return None


def _mutagen_tag_text(value: object) -> str:
    """Convert one Mutagen tag value to the textual payload ReplayGain expects.

    Motivation: Mutagen deliberately exposes format-native objects rather than
    one universal string type: ID3 TXXX frames have ``.text``, Vorbis comments
    are lists of strings, MP4 freeform values are bytes-like, and APE values can
    stringify directly.  This small adapter extracts only the first textual
    value because ReplayGain defines one scalar per field; it never rewrites or
    saves the source file.
    """

    candidate = value
    if hasattr(candidate, "text"):
        candidate = getattr(candidate, "text")
    if isinstance(candidate, (list, tuple)):
        candidate = candidate[0] if candidate else ""
    if isinstance(candidate, (bytes, bytearray, memoryview)):
        raw = bytes(candidate)
        try:
            return raw.decode("utf-8").strip("\x00 \t\r\n")
        except UnicodeDecodeError:
            return raw.decode("latin1", errors="replace").strip("\x00 \t\r\n")
    return str(candidate or "").strip()


def _mutagen_replaygain_tags(audio_path: Path) -> dict[str, str]:
    """Read standard textual ReplayGain fields with Mutagen as a cheap fallback.

    Motivation: the primary path is ffprobe because PAFPlayer already pays for
    that metadata lookup and caches it.  A few containers/tag mappings can hide
    standard textual ReplayGain from ffprobe while Mutagen still exposes it
    cheaply (notably ID3 TXXX and MP4 freeform atoms).  This fallback is invoked
    only by actual playback ReplayGain resolution, never by the bulk playlist
    history scanner, so it cannot turn a 50k-track history pass into 50k extra
    metadata reads.  Only the four explicit REPLAYGAIN_* names are accepted;
    MP3Gain undo/global-gain metadata is intentionally ignored.
    """

    try:
        mutagen = importlib.import_module("mutagen")
        audio = mutagen.File(str(audio_path), easy=False)
    except Exception:
        return {}
    if audio is None or getattr(audio, "tags", None) is None:
        return {}

    recovered: dict[str, str] = {}
    try:
        items = audio.tags.items()
    except Exception:
        return recovered
    for key, value in items:
        normalized = _normalize_replaygain_tag_key(key)
        if normalized is None or normalized in recovered:
            continue
        text_value = _mutagen_tag_text(value)
        if text_value:
            recovered[normalized] = text_value
    return recovered


def probe_replaygain_tags(audio_path: Path) -> dict[str, str]:
    """Return cached standard ReplayGain text without another ffprobe process.

    Motivation: ``probe_audio_metadata`` is already PAFPlayer's shared ffprobe
    cache for duration and display tags.  It now also captures the four
    ReplayGain fields in a private parallel cache.  This function first forces
    that ordinary cached probe to exist, then performs at most one Mutagen
    fallback for this exact file size/mtime generation.  The returned dictionary
    never enters Artist/Song/Album HUD metadata or now-playing payloads.
    """

    path = Path(audio_path)
    cache_location = _audio_metadata_cache_location(path)
    probe_audio_metadata(path)                                                    # Reuses the normal metadata lookup; on a warm cache this does not spawn ffprobe.
    if cache_location is None:
        return _mutagen_replaygain_tags(path)

    cache_key, size, mtime_ns = cache_location
    cached = _AUDIO_REPLAYGAIN_TAG_CACHE.get(cache_key)
    values: dict[str, str] = {}
    mutagen_done = False
    if cached is not None and cached[0] == size and cached[1] == mtime_ns:
        values = dict(cached[2])
        mutagen_done = bool(cached[3])

    if not mutagen_done:
        fallback = _mutagen_replaygain_tags(path)
        for key, value in fallback.items():
            values.setdefault(key, value)                                        # ffprobe wins when both probes expose the same standard textual field.
        mutagen_done = True
        _AUDIO_REPLAYGAIN_TAG_CACHE[cache_key] = (size, mtime_ns, dict(values), mutagen_done)
    return values


_REPLAYGAIN_GAIN_VALUE_RE = re.compile(
    r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?\s*(?:d\s*b)?$",
    flags=re.IGNORECASE,
)
_REPLAYGAIN_PEAK_VALUE_RE = re.compile(
    r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$",
)


def parse_replaygain_gain(value: object) -> float | None:
    """Parse one ReplayGain gain scalar expressed in dB.

    Motivation: real libraries contain ``-7.43 dB``, ``+2.10db``, bare numeric
    values, and inconsistent whitespace/capitalization.  A strict numeric+optional
    dB grammar accepts those legitimate variants while rejecting NaN/Inf,
    arbitrary prose, comma decimals, and malformed units before any value reaches
    FFmpeg's gain stage.
    """

    raw = str(value or "").strip()
    if not raw or _REPLAYGAIN_GAIN_VALUE_RE.fullmatch(raw) is None:
        return None
    numeric = re.sub(r"\s*d\s*b\s*$", "", raw, flags=re.IGNORECASE).strip()
    try:
        parsed = float(numeric)
    except (TypeError, ValueError):
        return None
    return parsed if math.isfinite(parsed) else None


def parse_replaygain_peak(value: object) -> float | None:
    """Parse a ReplayGain peak as a positive finite linear full-scale ratio.

    Motivation: clipping prevention uses the actual peak mathematically, so zero,
    negative, NaN, Inf, and unit-bearing garbage cannot be treated as usable peak
    evidence.  Values greater than 1.0 are valid and intentionally preserved:
    they require attenuation if the requested ReplayGain would otherwise leave
    the normalized signal above full scale.
    """

    raw = str(value or "").strip()
    if not raw or _REPLAYGAIN_PEAK_VALUE_RE.fullmatch(raw) is None:
        return None
    try:
        parsed = float(raw)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(parsed) or parsed <= 0.0:
        return None
    return parsed


def calculate_replaygain_info(
    tags: dict[str, str],
    mode: str = REPLAYGAIN_DEFAULT_MODE,
) -> ReplayGainInfo:
    """Select track/album gain, apply fallback policy, and peak-limit it exactly.

    Motivation: ReplayGain normalization and PAFPlayer's user volume are separate
    controls.  This function resolves only the normalization baseline.  Track
    mode prefers TRACK_GAIN and falls back to ALBUM_GAIN; album mode reverses
    that preference.  For the selected source, the corresponding peak limits the
    ReplayGain multiplier to ``1 / peak``.  In dB that ceiling is
    ``-20*log10(peak)``; therefore ``applied_db = min(requested_db, ceiling_db)``.
    A peak over 1.0 is valid and can make the safe ceiling negative.  Missing or
    malformed peaks do not invent a clamp.  No user volume percentage participates
    in this calculation, preserving deliberate >100% amplification downstream.
    """

    normalized_mode = str(mode or REPLAYGAIN_DEFAULT_MODE).strip().casefold()
    if normalized_mode == "on":
        normalized_mode = "track"
    if normalized_mode == "off":
        return ReplayGainInfo(False, "off", None, None, None, None, False)
    if normalized_mode not in {"track", "album"}:
        normalized_mode = REPLAYGAIN_DEFAULT_MODE if REPLAYGAIN_DEFAULT_MODE in {"track", "album"} else "track"

    normalized_tags: dict[str, str] = {}
    for key, value in dict(tags or {}).items():
        normalized = _normalize_replaygain_tag_key(key)
        if normalized is not None:
            normalized_tags[normalized] = str(value).strip()

    preference = ("track", "album") if normalized_mode == "track" else ("album", "track")
    for source in preference:
        gain_key = f"replaygain_{source}_gain"
        peak_key = f"replaygain_{source}_peak"
        requested_db = parse_replaygain_gain(normalized_tags.get(gain_key, ""))
        if requested_db is None:
            continue
        peak = parse_replaygain_peak(normalized_tags.get(peak_key, ""))
        applied_db = requested_db
        clipping_prevented = False
        if peak is not None:
            ceiling_db = -20.0 * math.log10(peak)                                # This is exactly the dB form of peak * 10**(gain/20) <= 1.
            if applied_db > ceiling_db:
                applied_db = ceiling_db
                clipping_prevented = True
        return ReplayGainInfo(
            True,
            normalized_mode,
            source,
            requested_db,
            peak,
            applied_db,
            clipping_prevented,
        )

    return ReplayGainInfo(True, normalized_mode, None, None, None, None, False)


def replaygain_info_for_audio(
    audio_path: Path,
    mode: str = REPLAYGAIN_DEFAULT_MODE,
) -> ReplayGainInfo:
    """Resolve one file's ReplayGain once from the cached metadata path.

    Motivation: callers should not need to know whether ffprobe or Mutagen
    supplied the tags.  Keeping selection in one helper also makes it trivial for
    ``play_audio_file`` to calculate the immutable ReplayGain decision once per
    track visit and reuse that exact result across every FFplay restart.
    """

    normalized_mode = str(mode or REPLAYGAIN_DEFAULT_MODE).strip().casefold()
    if normalized_mode == "off":
        return calculate_replaygain_info({}, "off")
    return calculate_replaygain_info(probe_replaygain_tags(Path(audio_path)), normalized_mode)


def replaygain_linear_multiplier(info: ReplayGainInfo | None) -> float | None:
    """Return the exact linear multiplier for FFmpeg's explicit volume filter.

    Motivation: using an explicit numeric ``volume=`` stage avoids depending on
    FFmpeg demuxers to convert format-specific ReplayGain tags into replaygain
    side-data consistently.  ``None`` means no ReplayGain stage is required;
    zero dB likewise returns 1.0 so the command builder may omit a no-op filter.
    """

    if info is None or not info.enabled or info.applied_db is None:
        return None
    return 10.0 ** (info.applied_db / 20.0)


def _format_replaygain_db_number(value: float) -> str:
    """Format a signed dB number compactly for the diagnostic help masthead.

    Motivation: ReplayGain's help line is intentionally concise.  One decimal is
    enough for human diagnosis while retaining a leading ``+`` for boosts, and
    trimming ``-0.0`` avoids suggesting a meaningful attenuation where none
    exists.
    """

    rounded = 0.0 if abs(value) < 0.05 else value
    return f"{rounded:+.1f}".rstrip("0").rstrip(".")


def replaygain_help_text(info: ReplayGainInfo) -> tuple[str, str]:
    """Return plain and ANSI help text describing the actually applied RG value.

    Motivation: the ordinary HUD must stay untouched, but the ``?`` overlay needs
    enough information to prove which normalization PAFPlayer chose.  Missing
    metadata is deliberately loud (blinking red ``None``), album-source fallback
    is identified, and clipping prevention shows requested→applied values while
    writing the ``dB`` unit only once as requested.
    """

    if not info.enabled:
        plain = "Off"
        return plain, "\033[2;38;2;150;150;160mOff\033[0m"
    if info.applied_db is None or info.requested_db is None:
        plain = "None"
        return plain, "\033[1;5;38;2;255;45;45mNone\033[0m"

    source_suffix = (
        " (album)" if info.source == "album"
        else " (track)" if info.mode == "album" and info.source == "track"
        else ""
    )
    if info.clipping_prevented:
        requested = _format_replaygain_db_number(info.requested_db)
        applied = _format_replaygain_db_number(info.applied_db)
        plain = f"{requested} → {applied}dB (clipping prevention){source_suffix}"
    else:
        applied = _format_replaygain_db_number(info.applied_db)
        plain = f"{applied}dB{source_suffix}"
    return plain, "\033[1;38;2;235;190;105m" + plain + "\033[0m"


def canonical_audio_tag_key(value: object) -> str:
    """Normalize a metadata key for alias matching without changing the displayed/raw key.

    Motivation: ffprobe exposes the same semantic field under several spellings
    across containers.  For example ID3 TOPE can remain literally ``TOPE`` while
    Vorbis may expose ``ORIGINALARTIST`` and another source may use
    ``original_artist``.  Canonicalization lets HUD field selection be robust
    while the Alt+3 browser can still show the original raw tag names.
    """
    return re.sub(r"[^a-z0-9]+", "", str(value).casefold())


def first_audio_tag_value(
    merged: dict[str, str],
    *aliases: str,
) -> str:
    """Return the first non-empty value whose raw/canonical key matches one alias."""
    canonical = {
        canonical_audio_tag_key(key): value
        for key, value in merged.items()
        if str(value).strip()
    }
    for alias in aliases:
        folded = str(alias).casefold()
        if folded in merged and str(merged[folded]).strip():
            return str(merged[folded]).strip()
        value = canonical.get(canonical_audio_tag_key(alias), "")
        if value:
            return value
    return ""


def probe_audio_metadata(
    audio_path: Path,
    *,
    executable: Path | None = None,
) -> tuple[float | None, dict[str, str]]:
    """Return duration/display metadata while privately caching ReplayGain text.

    Motivation: PAFPlayer already needs one ffprobe pass for duration plus normal
    Artist/Song/Album metadata, so ReplayGain must hitchhike on that exact JSON
    payload instead of launching a second expensive probe.  The function still
    returns the same public two-tuple it always did; only the four explicit
    REPLAYGAIN_* textual fields are copied into a separate private cache.  That
    separation prevents normalization internals from leaking into the ordinary
    HUD, Last.fm/now-playing payloads, or unrelated metadata-writing paths.
    """
    cache_location = _audio_metadata_cache_location(audio_path)
    if cache_location is not None:
        cache_key, size, mtime_ns = cache_location
        cached = _AUDIO_METADATA_CACHE.get(cache_key)
        if cached is not None and cached[0] == size and cached[1] == mtime_ns:
            return cached[2], dict(cached[3])

    ffprobe = executable or ffprobe_executable()
    payload: dict[str, object] = {}
    if ffprobe is not None:
        result = subprocess.run(
            [
                str(ffprobe), "-v", "error", "-show_entries",
                "format=duration,bit_rate:format_tags:stream=channels,channel_layout:stream_tags", "-of", "json", str(audio_path),
            ],
            check=False,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
        try:
            payload = json.loads(result.stdout)
        except (TypeError, ValueError, json.JSONDecodeError):
            payload = {}

    duration: float | None = None
    try:
        raw_duration = float(payload.get("format", {}).get("duration", ""))
        if math.isfinite(raw_duration) and raw_duration > 0:
            duration = raw_duration
    except (TypeError, ValueError):
        pass

    merged: dict[str, str] = {}
    sources = [payload.get("format", {}).get("tags", {})]
    sources.extend(stream.get("tags", {}) for stream in payload.get("streams", []))
    for source in sources:
        if not isinstance(source, dict):
            continue
        for key, value in source.items():
            folded = str(key).casefold()
            if folded not in merged and str(value).strip():
                merged[folded] = str(value).strip()
    # Keep ReplayGain private: the same ffprobe payload feeds a dedicated cache,
    # but these fields never enter the display-tag dictionary or now-playing data.
    raw_replaygain = {
        key: merged[key]
        for key in REPLAYGAIN_TAG_KEYS
        if key in merged and str(merged[key]).strip()
    }

    year = merged.get("year", "") or merged.get("date", "")[:4]
    bitrate_text = ""
    try:
        raw_bitrate = float(payload.get("format", {}).get("bit_rate", ""))
        if math.isfinite(raw_bitrate) and raw_bitrate > 0:
            bitrate_text = f"{int(round(raw_bitrate / 1000.0))}kbps"
    except (TypeError, ValueError):
        pass

    tags = {
        "Artist": merged.get("artist", "") or merged.get("album_artist", ""),
        "Song": merged.get("title", ""),
        "Album": merged.get("album", ""),
        "Year": year,
        "Genre": merged.get("genre", ""),
        "Original artist": first_audio_tag_value(
            merged,
            "original_artist",
            "originalartist",
            "original artist",
            "tope",
        ),
        "Composer": first_audio_tag_value(
            merged,
            "composer",
            "tcom",
            "writer",
        ),
        "URL": merged.get("url", ""),
        "Comment": merged.get("comment", "") or merged.get("description", ""),
        "Bitrate": bitrate_text,
    }

    # Some damaged MP3s contain valid-looking ID3 frame headers whose text is
    # rejected by ffprobe/Mutagen because the encoding marker and payload bytes
    # disagree.  Recover only fields that the normal probe could not read.
    for field, value in _recover_raw_id3_display_tags(audio_path).items():
        if not tags.get(field) and value:
            tags[field] = value

    # A missing title is still recoverable without guessing who made the track
    # or which album it belongs to.  Keep Artist/Album blank unless the file gave
    # us trustworthy metadata, but make ``19_Scott.mp3`` display as ``Scott``.
    if not tags.get("Song"):
        tags["Song"] = _fallback_song_title_from_filename(audio_path)

    if cache_location is not None:
        cache_key, size, mtime_ns = cache_location
        _AUDIO_METADATA_CACHE[cache_key] = (size, mtime_ns, duration, dict(tags))
        _AUDIO_RAW_TAG_CACHE[cache_key] = (size, mtime_ns, dict(merged))
        _AUDIO_REPLAYGAIN_TAG_CACHE[cache_key] = (
            size,
            mtime_ns,
            dict(raw_replaygain),
            False,
        )
        stream_channels = None
        stream_layout = None
        for stream in payload.get("streams", []):
            if not isinstance(stream, dict):
                continue
            try:
                candidate_channels = int(stream.get("channels", 0) or 0)
            except (TypeError, ValueError):
                candidate_channels = 0
            if candidate_channels > 0:
                stream_channels = candidate_channels
                candidate_layout = str(stream.get("channel_layout", "") or "").strip()
                stream_layout = candidate_layout or None
                break
        _AUDIO_STREAM_LAYOUT_CACHE[cache_key] = (size, mtime_ns, stream_channels, stream_layout)
    return duration, tags


def _infer_standard_channel_layout(source_channels: int | None) -> str | None:
    try: count=int(source_channels or 0)
    except (TypeError,ValueError): return None
    return {1:"mono",2:"stereo",6:"5.1(side)",8:"7.1",12:"7.1.4"}.get(count)


def probe_audio_stream_layout(audio_path: Path, *, executable: Path | None = None) -> tuple[int | None, str | None]:
    """Return the source channel count/layout, using the same ffprobe pass when possible."""
    location=_audio_metadata_cache_location(audio_path)
    if location is not None:
        key,size,mtime_ns=location
        cached=_AUDIO_STREAM_LAYOUT_CACHE.get(key)
        if cached is not None and cached[0]==size and cached[1]==mtime_ns:
            return cached[2], cached[3] or _infer_standard_channel_layout(cached[2])
    # The normal metadata probe now carries stream layout too.
    with contextlib.suppress(Exception):
        probe_audio_metadata(audio_path, executable=executable)
    if location is not None:
        key,size,mtime_ns=location
        cached=_AUDIO_STREAM_LAYOUT_CACHE.get(key)
        if cached is not None and cached[0]==size and cached[1]==mtime_ns:
            return cached[2], cached[3] or _infer_standard_channel_layout(cached[2])
    return None, None


def probe_duration_seconds(
    audio_path: Path,
    *,
    executable: Path | None = None,
) -> float | None:
    """Return decoded duration, sharing the same cached ffprobe as tag reads."""
    duration, _tags = probe_audio_metadata(audio_path, executable=executable)
    return duration


def probe_audio_tags(audio_path: Path) -> dict[str, str]:
    """Read only user-facing tags from the shared metadata probe.

    Motivation: ReplayGain is playback control data, not song identity.  This
    accessor deliberately keeps returning only display metadata even though the
    underlying cached ffprobe now also captures ReplayGain privately.  V88's
    display subset includes Original artist and Composer in addition to the
    established Artist/Song/Album/Year/Genre/URL/Comment fields.
    """
    _duration, tags = probe_audio_metadata(audio_path)
    return tags


def probe_audio_raw_tags(audio_path: Path) -> dict[str, str]:
    """Return every unique ffprobe tag from the already-shared metadata probe.

    Motivation: Alt+3 should expose metadata rather than merely the small HUD
    subset, but it should not add another ffprobe to normal playback.  Calling
    ``probe_audio_metadata`` primes the raw cache from the exact same payload.
    """
    path = Path(audio_path)
    probe_audio_metadata(path)
    location = _audio_metadata_cache_location(path)
    if location is None:
        return {}
    key, size, mtime_ns = location
    cached = _AUDIO_RAW_TAG_CACHE.get(key)
    if cached is None or cached[0] != size or cached[1] != mtime_ns:
        return {}
    return dict(cached[2])


