def load_external_floating_lyrics_position() -> tuple[int, int] | None:
    """Return authoritative floating-lyric top-left screen coordinates.

    V302 stores position separately from width/height so switching between edit
    chrome, runtime layout sizes, DPI changes, and restored playback cannot move
    the lyric window merely because its dimensions changed.
    """
    if os.name != "nt":
        return None
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\ClaireCJS\play_audio_file") as key:
            value, _kind = winreg.QueryValueEx(key, EXTERNAL_FLOATING_LYRICS_POSITION_VALUE)
        match = re.fullmatch(r"\s*(-?\d+)\s*,\s*(-?\d+)\s*", str(value))
        if match is None:
            return None
        return int(match.group(1)), int(match.group(2))
    except (OSError, TypeError, ValueError):
        return None


