WEB_CHOICE_MARK_SPECS: dict[str, tuple[str, str]] = {
    # key: (registry favorites value, user-default setting name)
    "visualizer_type": ("VisualizerStyleFavorites", "VisualizerMode"),
    "visualizer_treatment": ("VisualizerTreatmentFavorites", "VisualizerMode"),
    "color_style": ("PaletteFavorites", "ColorStyle"),
    "processing_style": ("ProcessingFavorites", "ProcessingStyle"),
    "persistence_mode": ("PersistenceFavorites", "PersistenceMode"),
    "visualizer_granularity": ("GranularityFavorites", "VisualizerGranularity"),
    "karaoke_style": ("KaraokeStyleFavorites", "KaraokeStyle"),
    "karaoke_treatment": ("KaraokeTreatmentFavorites", "KaraokeTreatment"),
    "progress_style": ("ProgressStyleFavorites", "ProgressStyle"),
    "progress_beat_detector": ("ProgressBeatDetectorFavorites", "ProgressBeatDetector"),
    "progress_beat_treatment": ("ProgressBeatTreatmentFavorites", "ProgressBeatTreatment"),
    "output_device": ("OutputDeviceFavorites", "OutputDevice"),
    "fade_style": ("BarFadeStyleFavorites", "BarFadeStyle"),
}

WEB_UI_PREFERENCES_REGISTRY_VALUE = "WebUiPreferencesV241"


def _web_ui_preferences_fallback_path() -> Path:
    base = Path(os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()) / "PAFPlayer"
    return base / "web-ui-preferences-v241.json"


def load_web_ui_preferences() -> dict[str, object]:
    raw = _read_registry_json_string(WEB_UI_PREFERENCES_REGISTRY_VALUE, {})
    if isinstance(raw, dict) and raw:
        return dict(raw)
    try:
        fallback = json.loads(_web_ui_preferences_fallback_path().read_text(encoding="utf-8"))
        return dict(fallback) if isinstance(fallback, dict) else {}
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return dict(raw) if isinstance(raw, dict) else {}


def save_web_ui_preferences(value: object) -> dict[str, object]:
    """Persist browser-only configuration independently of browser localStorage."""
    if not isinstance(value, dict):
        raise ValueError("web preferences must be an object")
    # Keep this small and primitive so an accidentally huge browser payload can
    # never turn a registry preference into storage abuse.
    def clean_value(item, *, depth: int = 0):
        if isinstance(item, (str, int, float, bool)) or item is None:
            return item
        if depth >= 2:
            return None
        if isinstance(item, dict):
            return {
                str(k)[:80]: cleaned
                for k, v in list(item.items())[:64]
                if (cleaned := clean_value(v, depth=depth + 1)) is not None
            }
        if isinstance(item, (list, tuple)):
            return [
                cleaned
                for v in list(item)[:64]
                if (cleaned := clean_value(v, depth=depth + 1)) is not None
            ]
        return None

    clean: dict[str, object] = {}
    for key, item in list(value.items())[:128]:
        name = str(key)[:120]
        cleaned = clean_value(item)
        if cleaned is not None:
            clean[name] = cleaned
    _write_registry_json_string(WEB_UI_PREFERENCES_REGISTRY_VALUE, clean)
    try:
        target = _web_ui_preferences_fallback_path()
        target.parent.mkdir(parents=True, exist_ok=True)
        temporary = target.with_suffix(target.suffix + ".tmp")
        temporary.write_text(json.dumps(clean, ensure_ascii=False, sort_keys=True), encoding="utf-8")
        os.replace(temporary, target)
    except OSError:
        pass
    return clean



def paf_web_choice_value_is_valid(key: str, value: int) -> bool:
    maxima = {
        "visualizer_type": len(VISUALIZER_TYPE_NAMES),
        "visualizer_treatment": len(VISUALIZER_TREATMENT_NAMES),
        "color_style": len(PALETTE_NAMES),
        "processing_style": len(PROCESSING_STYLE_NAMES),
        "persistence_mode": len(PERSISTENCE_MODE_NAMES),
        "visualizer_granularity": len(VISUALIZER_GRANULARITY_NAMES),
        "karaoke_style": len(KARAOKE_STYLE_NAMES),
        "karaoke_treatment": len(KARAOKE_TREATMENT_NAMES),
        "progress_style": len(PROGRESS_STYLE_NAMES),
        "progress_beat_detector": len(PROGRESS_BEAT_DETECTOR_NAMES),
        "progress_beat_treatment": len(PROGRESS_BEAT_TREATMENT_NAMES),
        "fade_style": len(FADE_STYLE_NAMES),
    }
    key = str(key)
    if key == "output_device":
        return int(value) in {int(item.get("value", -1)) for item in waveout_output_devices()}
    maximum = maxima.get(key)
    return maximum is not None and 1 <= int(value) <= maximum


def paf_web_choice_default_value(key: str) -> int:
    """Return the current registry-backed default for one marked web selector."""
    defaults = effective_player_defaults()
    key = str(key)
    if key == "visualizer_type":
        mode = int(defaults.get("VisualizerMode", 1))
        return (mode - 1) % len(VISUALIZER_TYPE_NAMES) + 1
    if key == "visualizer_treatment":
        mode = int(defaults.get("VisualizerMode", 1))
        return (mode - 1) // len(VISUALIZER_TYPE_NAMES) + 1
    spec = WEB_CHOICE_MARK_SPECS.get(key)
    if spec is None:
        return 0
    return int(defaults.get(spec[1], 1))


def set_paf_web_choice_favorite(key: str, value: int, enabled: bool) -> bool:
    spec = WEB_CHOICE_MARK_SPECS.get(str(key))
    if spec is None or not paf_web_choice_value_is_valid(key, value):
        return False
    values = registry_favorites(spec[0])
    value = int(value)
    if enabled and value not in values:
        values.append(value)
    elif not enabled and value in values:
        values.remove(value)
    save_registry_favorites(spec[0], values)
    return True


def set_paf_web_choice_default(key: str, value: int) -> bool:
    """Set one exact default; the browser performs the user confirmation first."""
    key = str(key)
    value = int(value)
    spec = WEB_CHOICE_MARK_SPECS.get(key)
    if spec is None or not paf_web_choice_value_is_valid(key, value):
        return False
    if key in {"visualizer_type", "visualizer_treatment"}:
        mode = int(effective_player_defaults().get("VisualizerMode", 1))
        style = (mode - 1) % len(VISUALIZER_TYPE_NAMES) + 1
        treatment = (mode - 1) // len(VISUALIZER_TYPE_NAMES) + 1
        if key == "visualizer_type":
            style = value
        else:
            treatment = value
        save_user_default("VisualizerMode", (treatment - 1) * len(VISUALIZER_TYPE_NAMES) + style)
    else:
        save_user_default(spec[1], value)
    return True


