        self.assertEqual((2, 4, 6), lyric_scroll_rows(0.0))
        self.assertEqual((1, 3, 5), lyric_scroll_rows(LYRIC_SCROLL_STEP_SECONDS))
        self.assertIsNone(lyric_scroll_rows(LYRIC_SCROLL_STEP_SECONDS * 2))

