    def test_seek_restarts_ffplay_at_requested_offsets(self) -> None:
        class FakeProcess:
            def __init__(self) -> None:
                self.running = True
                self.terminated = False
                self.killed = False

            def poll(self):
                return None if self.running else 0

            def terminate(self) -> None:
                self.terminated = True
                self.running = False

            def wait(self, timeout=None) -> int:
                self.running = False
                return 0

            def kill(self) -> None:
                self.killed = True
                self.running = False

        processes: list[FakeProcess] = []
        commands: list[list[str]] = []

        def factory(command, **_kwargs):
            commands.append(command)
            process = FakeProcess()
            processes.append(process)
            return process

        actions = iter(
            (SEEK_FORWARD_5, SEEK_FORWARD_15, STOP)
        )
        clock = itertools.repeat(100.0)
        with tempfile.TemporaryDirectory() as temp:
            audio = Path(temp) / "fixture.flac"
            audio.write_bytes(b"generated audio fixture")
            with contextlib.redirect_stdout(io.StringIO()):
                result = play_audio_file(
                    audio,
                    ffplay=Path("ffplay.exe"),
                    duration_probe=lambda _path: 60.0,
                    key_action_reader=lambda: next(actions),
                    process_factory=factory,
                    monotonic=lambda: next(clock),
                    sleeper=lambda _seconds: None,
                    install_signal_handlers=False,
                )
        self.assertEqual("stopped", result)
        self.assertEqual(3, len(commands))
        self.assertEqual("0.000", commands[0][commands[0].index("-ss") + 1])
        self.assertEqual("5.000", commands[1][commands[1].index("-ss") + 1])
        self.assertEqual("20.000", commands[2][commands[2].index("-ss") + 1])
        self.assertTrue(all(command[command.index("-volume") + 1] == "100" for command in commands))
        self.assertTrue(all("-ar" not in command for command in commands))
        self.assertTrue(all(
            "aresample=48000" in command[command.index("-af") + 1]
            for command in commands
        ))
        self.assertTrue(all(process.terminated for process in processes[:-1]))
        self.assertTrue(processes[-1].killed)  # final STOP is intentionally hard in V175
        boosted = ffplay_command(Path("ffplay.exe"), audio, 0, 400, 1.0)
        self.assertIn("volume=4", boosted[boosted.index("-af") + 1])
        self.assertEqual("100", boosted[boosted.index("-volume") + 1])
        expanded_51 = ffplay_command(Path("ffplay.exe"), audio, 0, 100, 1.0, 5)
        expanded_71 = ffplay_command(Path("ffplay.exe"), audio, 0, 100, 1.0, 7)
        self.assertIn("pan=5.1", expanded_51[expanded_51.index("-af") + 1])
        self.assertIn("pan=7.1", expanded_71[expanded_71.index("-af") + 1])
        self.assertIn("FC=0.4*FL+0.4*FR", expanded_51[expanded_51.index("-af") + 1])
        self.assertIn("SL=0.7*FL", expanded_51[expanded_51.index("-af") + 1])
        self.assertIn("SR=0.7*FR", expanded_51[expanded_51.index("-af") + 1])
        self.assertIn("SL=0.7*FL", expanded_71[expanded_71.index("-af") + 1])
        self.assertIn("BL=0.55*FL", expanded_71[expanded_71.index("-af") + 1])
        self.assertIn("BR=0.55*FR", expanded_71[expanded_71.index("-af") + 1])
        self.assertNotIn("FL-", expanded_51[expanded_51.index("-af") + 1])
        self.assertNotIn("FR-", expanded_71[expanded_71.index("-af") + 1])
        self.assertIn("lowpass=f=60:c=LFE", expanded_51[expanded_51.index("-af") + 1])
        self.assertNotIn("alimiter=", expanded_71[expanded_71.index("-af") + 1])

