    def test_v230_mminspo_accumulates_short_pipe_reads_into_real_audio_blocks(self) -> None:
        class ShortReader:
            def __init__(self, payload: bytes) -> None:
                self.payload = bytearray(payload)
            def read(self, requested: int) -> bytes:
                if not self.payload:
                    return b""
                amount = min(3, requested, len(self.payload))
                chunk = bytes(self.payload[:amount])
                del self.payload[:amount]
                return chunk
        reader = ShortReader(b"abcdefghijklmnop")
        self.assertEqual(b"abcdefghij", matrixmixer_read_pcm_block(reader, 10))
        self.assertEqual(b"klmnop", matrixmixer_read_pcm_block(reader, 10))
        self.assertEqual(8192, MM_INSPIRED_BUFFER_FRAMES)
        self.assertEqual(8, MM_INSPIRED_PENDING_BUFFERS)

