    def test_v71_last_heard_colon_aligns_exactly_with_album(self) -> None:
        """V263 no longer lets metadata Last play own Album's right-side colon."""
        tags = {
            "Artist": "Dethklok",
            "Song": "Die Tonight (Steel Sarcophagus) (TV Edit)",
            "Album": "Metalocalypse: S2E11 Dethrace",
            "Year": "2008",
            "Genre": "Thrash Metal",
            "Last play": "43.7h",
        }
        rows, _ansi = format_tag_panel(tags, width=150)
        self.assertGreaterEqual(len(rows), 2)
        joined = "\n".join(rows)
        self.assertIn("Last play: 43.7h", joined)
        self.assertTrue(all(terminal_cell_width(row) <= 150 for row in rows))

        def label_colon(row: str, label: str) -> int:
            marker = label + ":"
            position = row.index(marker) + len(label)
            return terminal_cell_width(row[:position])

        act_row = next(row for row in rows if "Act:" in row)
        year_row = next(row for row in rows if "Year:" in row)
        song_row = next(row for row in rows if "Song:" in row)
        genre_row = next(row for row in rows if "Genre:" in row)
        self.assertEqual(label_colon(act_row, "Act"), label_colon(year_row, "Year"))
        self.assertEqual(label_colon(song_row, "Song"), label_colon(genre_row, "Genre"))


