    def test_v106_media_previous_next_modifier_contract(self) -> None:
        """Bare media keys scrub, Shift scrubs 8x, and Ctrl/Alt navigate tracks."""
        self.assertEqual(SEEK_FORWARD_10, media_transport_key_action(0xB0))
        self.assertEqual(SEEK_BACK_10, media_transport_key_action(0xB1))
        self.assertEqual(SEEK_FORWARD_80, media_transport_key_action(0xB0, shift=True))
        self.assertEqual(SEEK_BACK_80, media_transport_key_action(0xB1, shift=True))
        for modifiers in (
            {"ctrl": True},
            {"alt": True},
            {"ctrl": True, "alt": True},
            {"shift": True, "ctrl": True},
        ):
            self.assertEqual(NEXT_FILE, media_transport_key_action(0xB0, **modifiers))
            self.assertEqual(PREVIOUS_FILE, media_transport_key_action(0xB1, **modifiers))

