    def test_v108_shuffle_excludes_sampled_launches_before_earned_play_threshold(self) -> None:
        """A quick visit is recent even when it never earned local/scrobble history."""
        with tempfile.TemporaryDirectory() as temp:
            root = Path(temp)
            current = root / "current.mp3"
            sampled = root / "sampled.mp3"
            safe = root / "safe.mp3"
            for path in (current, sampled, safe):
                path.write_bytes(b"x")
            now = 1_000_000.0
            _PLAYLIST_RECENT_VISIT_CACHE.clear()
            _PLAYLIST_RECENT_VISIT_CACHE[lexical_path_key(sampled)] = now - 60.0
            with mock.patch(__name__ + ".SHUFFLE_RECENT_AVOID_ENABLED", True), mock.patch(
                __name__ + ".playlist_history_last_played_sync_candidate",
                return_value=0.0,
            ):
                chosen = shuffle_candidate_avoiding_recent(
                    [current, sampled, safe],
                    current,
                    sampled,
                    now=now,
                )
            self.assertEqual(safe, chosen)

    def test_v108_shuffle_visit_ledger_persists_separately_from_earned_history(self) -> None:
        """Launch visits survive a new process without manufacturing an earned play."""
