        self.assertEqual("📴", semantic.get("off"))
        self.assertEqual(36, len(EMOJIMAX_V319_REMOVALS_BY_UNDO_CODE))
        for word, _glyph in EMOJIMAX_V319_REMOVALS_BY_UNDO_CODE.values():
            self.assertNotIn(word, semantic)
