    def test_v241_history_identity_folds_case_smart_quotes_and_duration(self) -> None:
        self.assertEqual(
            normalize_playlist_history_text('Metallica — When Hell Freezes Over (“The Call Of Ktulu”)'),
            normalize_playlist_history_text('metallica - when hell freezes over ("the call of ktulu")'),
        )
        self.assertEqual(normalize_playlist_history_text("Guns N’ Roses"), normalize_playlist_history_text("guns n' roses"))
        database = sqlite3.connect(":memory:")
        database.execute("CREATE TABLE playlist_history_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
        database.execute(
            """CREATE TABLE played_history_identities_recent (
                artist_key TEXT NOT NULL, title_key TEXT NOT NULL, artist TEXT NOT NULL, title TEXT NOT NULL,
                duration_seconds INTEGER NOT NULL, filename TEXT NOT NULL, played_at REAL NOT NULL,
                PRIMARY KEY (artist_key, title_key, duration_seconds)
            ) WITHOUT ROWID"""
        )
        database.execute(
            "INSERT INTO played_history_identities_recent VALUES (?,?,?,?,?,?,?)",
            ("Metallica", "When Hell Freezes Over", "Metallica", 'When Hell Freezes Over (“The Call Of Ktulu”)', 481, "", 100.0),
        )
        database.execute(
            "INSERT INTO played_history_identities_recent VALUES (?,?,?,?,?,?,?)",
            ("metallica", "when hell freezes over", "metallica", 'when hell freezes over ("the call of ktulu")', 482, "", 200.0),
        )
        _ensure_playlist_full_identity_table(database)
        rows = database.execute("SELECT artist_key,title_key,played_at FROM played_history_identities_recent").fetchall()
        self.assertEqual(1, len(rows))
        self.assertEqual(200.0, rows[0][2])
        database.close()

