    def test_v246_7_1_back_only_mute_uses_native_pcm_channel_order(self) -> None:
        """BL/BR-only program audio must survive the safety mute pan in 7.1/7.1.4."""
        global _MM_MATRIX_LOADED, _ACTIVE_MM_MUTES, _ACTIVE_MM_CROSSOVERS
        old_loaded = _MM_MATRIX_LOADED
        old_mutes = {key: set(value) for key, value in _ACTIVE_MM_MUTES.items()}
        old_cross = {key: dict(value) for key, value in _ACTIVE_MM_CROSSOVERS.items()}
        try:
            _MM_MATRIX_LOADED = True
            _ACTIVE_MM_MUTES[7] = {"FL", "FR", "FC", "LFE", "SL", "SR"}
            _ACTIVE_MM_CROSSOVERS[7] = {"enabled": True, "hz": 60.0}
            filt = output_expansion_filter(7)
            final_pan = filt.rsplit(",pan=", 1)[-1]
            self.assertEqual(
                "7.1|FL=0*c0|FR=0*c1|FC=0*c2|LFE=0*c3|BL=1*c4|BR=1*c5|SL=0*c6|SR=0*c7",
                final_pan,
            )
            _ACTIVE_MM_MUTES[12] = {"FL", "FR", "FC", "LFE", "SL", "SR", "TFL", "TFR", "TBL", "TBR"}
            _ACTIVE_MM_CROSSOVERS[12] = {"enabled": True, "hz": 60.0}
            filt12 = output_expansion_filter(12)
            final12 = filt12.rsplit(",pan=", 1)[-1]
            self.assertIn("BL=1*c4|BR=1*c5|SL=0*c6|SR=0*c7", final12)
        finally:
            _MM_MATRIX_LOADED = old_loaded
            _ACTIVE_MM_MUTES = old_mutes
            _ACTIVE_MM_CROSSOVERS = old_cross

