    def test_v255_tone_arrival_detector_synthetic(self) -> None:
        try:
            import numpy as np
        except ImportError:
            self.skipTest("NumPy unavailable")
        rate = 48000; seconds = 1.2; onset_ms = 347.0; frequency = 877.0
        samples = np.zeros(int(rate * seconds), dtype=np.float64)
        start = int(rate * onset_ms / 1000.0)
        t = np.arange(samples.size - start, dtype=np.float64) / rate
        samples[start:] = 0.35 * np.sin(2 * np.pi * frequency * t)
        pcm = np.clip(samples * 32767.0, -32768, 32767).astype("<i2").tobytes()
        arrival, snr = estimate_tone_arrival_ms(pcm, channels=1, sample_rate=rate, frequency=frequency)
        self.assertIsNotNone(arrival)
        self.assertGreater(snr, 10.0)
        self.assertLess(abs(float(arrival) - onset_ms), 25.0)


