    def test_v262_waterfall_vector_fast_path_matches_legacy_formula(self) -> None:
        state = new_visualizer_persistence_state()
        frames = [[((i + frame) % 17) / 16.0 for i in range(32)] for frame in range(10)]
        history: list[list[float]] = []
        for current in frames:
            history.append(list(current))
            history = history[-16:]
            samples = history[-8:]
            denominator = sum(range(1, len(samples) + 1)) or 1
            expected = [
                max(max(0.0, min(1.0, current[i])), sum(frame[i] * (j + 1) for j, frame in enumerate(samples)) / denominator * 0.92)
                for i in range(len(current))
            ]
            actual = apply_visualizer_persistence(current, state, 12, 1.0 / 120.0)
            for left, right in zip(actual, expected):
                self.assertAlmostEqual(left, right, places=12)


    def test_v263_idle_art_dance_never_straddles_monitor_seam(self) -> None:
        monitors = [
            (0, 0, 1920, 1040, True, r"\\.\DISPLAY1"),
            (1920, 0, 3840, 1040, False, r"\\.\DISPLAY2"),
        ]
        # Deliberately begin across the seam.  The center is on DISPLAY2.
        original = (1850, 200, 2250, 700)
        safe, monitor = external_album_art_idle_safe_outer_rect(original, monitors)
        self.assertEqual(monitors[1], monitor)
        self.assertGreaterEqual(safe[0], monitor[0] + 5)
        self.assertGreaterEqual(safe[1], monitor[1] + 5)
        self.assertLessEqual(safe[2], monitor[2] - 5)
        self.assertLessEqual(safe[3], monitor[3] - 5)
        geometry = (safe[2] - safe[0], safe[3] - safe[1], safe[0], safe[1])
        bounds = external_album_art_idle_drift_bounds(geometry, geometry, monitor)
        min_x, max_x, min_y, max_y = bounds
        self.assertGreaterEqual(min_x, monitor[0] + 5)
        self.assertLessEqual(max_x + geometry[0], monitor[2] - 5)
        self.assertGreaterEqual(min_y, monitor[1] + 5)
        self.assertLessEqual(max_y + geometry[1], monitor[3] - 5)

        # Oversized manual windows are temporarily reduced for idle mode rather
        # than allowing a corner to live on another monitor.
        giant = (1700, -50, 4300, 1600)
        giant_safe, giant_monitor = external_album_art_idle_safe_outer_rect(giant, monitors)
        self.assertIsNotNone(giant_monitor)
        assert giant_monitor is not None
        self.assertGreaterEqual(giant_safe[0], giant_monitor[0] + 5)
        self.assertGreaterEqual(giant_safe[1], giant_monitor[1] + 5)
        self.assertLessEqual(giant_safe[2], giant_monitor[2] - 5)
        self.assertLessEqual(giant_safe[3], giant_monitor[3] - 5)

