class V265BrowserOwnedVisualizerRegressionTests(unittest.TestCase):
    def test_v265_web_visualizer_is_browser_owned_and_gated(self):
        self.assertEqual("V265", PROGRAM_VERSION)
        html = _paf_web_html()
        self.assertIn('id="webVisualizerToggle"', html)
        self.assertIn("fetch('/api/spectrum.raw'", html)
        self.assertIn('initSpectrumWorker()', html)
        self.assertIn('browserSpectrumProcess', html)
        self.assertIn("fetch('/api/web-visualizer'", html)
        server_source = inspect.getsource(PAFWebServer)
        self.assertIn('def publish_spectrum_raw', server_source)
        self.assertIn('def web_visualizer_active', server_source)
        player_source = inspect.getsource(play_audio_file)
        self.assertIn('web_server.publish_spectrum_raw(web_raw_spectrum)', player_source)
        hot = player_source[player_source.index('web_visualizer_active ='):player_source.index('if web_server is not None and now - last_web_publish')]
        self.assertNotIn('visualizer_mode_heights(', hot)
        self.assertNotIn('normalize_visualizer_heights(', hot)
        self.assertNotIn('spectrum_frame_interpolated_at(', hot)


# V266 transport/governor regression checks are intentionally source-structural:
# they protect the historical performance contract even on non-Windows CI.
def _v266_transport_contract_selftest() -> None:
    assert VISUALIZER_TRANSPORT_DEFAULT_MODE == "row-delta"
    assert tuple(VISUALIZER_TRANSPORT_MODES) == ("row-delta", "full-frame", "semantic-cell")
    assert not bool(VISUALIZER_GOVERNOR_INCLUDE_TRANSPORT)
    probe_rows: list[str] = []
    rendered = render_drcs_visualizer(24, [0.2] * 48, [0.2] * 48, rows=6, granularity=3, rows_out=probe_rows, rows_only=True)
    assert rendered == "" and probe_rows


